bject": "english", "explanation": "January 是一月。"}, {"id": "high-english-113", "band": "high", "answer": "a", "prompt": "“good”的最高级是哪个？", "choices": [{"id": "a", "text": "best"}, {"id": "b", "text": "goodest"}, {"id": "c", "text": "more good"}], "subject": "english", "explanation": "good-better-best，最高级是 best。"}, {"id": "high-english-114", "band": "high", "answer": "a", "prompt": "“excited”形容人是什么感觉？", "choices": [{"id": "a", "text": "兴奋激动"}, {"id": "b", "text": "很困"}, {"id": "c", "text": "生病了"}], "subject": "english", "explanation": "excited 就是又激动又兴奋。"}, {"id": "high-english-115", "band": "high", "answer": "a", "prompt": "“This is ___ apple.”填哪个？", "choices": [{"id": "a", "text": "an"}, {"id": "b", "text": "a"}, {"id": "c", "text": "the"}], "subject": "english", "explanation": "apple 以元音开头，用 an。"}, {"id": "high-english-116", "band": "high", "answer": "a", "prompt": "“rainy”是描述什么天气？", "choices": [{"id": "a", "text": "下雨"}, {"id": "b", "text": "晴天"}, {"id": "c", "text": "下雪"}], "subject": "english", "explanation": "rain 是雨，rainy 就是下雨的。"}, {"id": "high-english-117", "band": "high", "answer": "a", "prompt": "“Where”这个词常用来问什么？", "choices": [{"id": "a", "text": "地点"}, {"id": "b", "text": "时间"}, {"id": "c", "text": "颜色"}], "subject": "english", "explanation": "Where 问“在哪里”，问地点。"}, {"id": "low-science-101", "band": "low", "answer": "a", "prompt": "太阳是从哪边升起来的？", "choices": [{"id": "a", "text": "东边"}, {"id": "b", "text": "西边"}, {"id": "c", "text": "北边"}], "subject": "science", "explanation": "太阳东升西落，早上从东边出来。"}, {"id": "low-science-102", "band": "low", "answer": "b", "prompt": "小鱼用什么呼吸？", "choices": [{"id": "a", "text": "鼻子"}, {"id": "b", "text": "鳃"}, {"id": "c", "text": "耳朵"}], "subject": "science", "explanation": "鱼用鳃在水里呼吸。"}, {"id": "low-science-103", "band": "low", "answer": "a", "prompt": "下雨前天空通常会怎样？", "choices": [{"id": "a", "text": "乌云密布"}, {"id": "b", "text": "万里晴空"}, {"id": "c", "text": "出彩虹"}], "subject": "science", "explanation": "乌云聚多了就要下雨啦。"}, {"id": "low-science