36", "band": "high", "answer": "d", "prompt": "“I usually ___ up at six.” 填哪个？", "choices": [{"id": "a", "text": "gets"}, {"id": "b", "text": "getting"}, {"id": "c", "text": "got"}, {"id": "d", "text": "get"}], "subject": "english", "explanation": "主语 I 用动词原形 get。"}, {"id": "hi-english-37", "band": "high", "answer": "a", "prompt": "“There are seven days in a ___.” 填哪个？", "choices": [{"id": "a", "text": "week"}, {"id": "b", "text": "month"}, {"id": "c", "text": "year"}, {"id": "d", "text": "day"}], "subject": "english", "explanation": "一周（week）有七天。"}, {"id": "hi-english-38", "band": "high", "answer": "b", "prompt": "“He can't come because he ___ busy.” 填哪个？", "choices": [{"id": "a", "text": "are"}, {"id": "b", "text": "is"}, {"id": "c", "text": "be"}, {"id": "d", "text": "am"}], "subject": "english", "explanation": "主语 he 用 is。"}, {"id": "hi-english-39", "band": "high", "answer": "c", "prompt": "“Look at the boys. They ___ football.” 填哪个？", "choices": [{"id": "a", "text": "plays"}, {"id": "b", "text": "is playing"}, {"id": "c", "text": "are playing"}, {"id": "d", "text": "played"}], "subject": "english", "explanation": "Look! 提示正在进行，主语 they 用 are playing。"}, {"id": "hi-english-40", "band": "high", "answer": "d", "prompt": "“The word 'autumn' means ___ in Chinese.” 填哪个？", "choices": [{"id": "a", "text": "春天"}, {"id": "b", "text": "夏天"}, {"id": "c", "text": "冬天"}, {"id": "d", "text": "秋天"}], "subject": "english", "explanation": "autumn 是“秋天”。"}, {"id": "hi-science-1", "band": "high", "answer": "a", "prompt": "一天中，影子最短大约是在什么时候？", "choices": [{"id": "a", "text": "正午（太阳最高时）"}, {"id": "b", "text": "清晨"}, {"id": "c", "text": "傍晚"}, {"id": "d", "text": "半夜"}], "subject": "science", "explanation": "太阳越高，影子越短，正午前后太阳最高，影子最短。"}, {"id": "hi-science-2", "band": "high", "answer": "b", "prompt": "水有三种状态，冰、水、水蒸气分别是哪三态？", "choices": [{"id": "a", "text": "液态、固态、气态"}, {"id": "b", "text": "固态、液态、气态"}, {"id": "c", "text": "气态、液态、固态"}, {"id": "d", "text": "固态、气态、液态"}], "subject": "science", "explanation": "冰是固态、水是液态、水蒸气是气态。"}, {"id": "hi-science-3", "band": "high", "answer": "c", "prompt": "把空气吹进气球，气球鼓起来，说明气体有什么性质？", "choices": [{"id": "a", "text": "没有质量"}, {"id": "b", "text": "不会流动"}, {"id": "c", "text": "占据空间、能被压缩"}, {"id": "d", "text": "比固体重"}], "subject": "science", "explanation": "气体能占据空间，也比较容易被压缩。"}, {"id": "hi-science-4", "band": "high", "answer": "d", "prompt": "植物进行光合作用，放出的是哪种气体？", "choices": [{"id": "a", "text": "二氧化碳"}, {"id": "b", "text": "氮气"}, {"id": "c", "text": "水蒸气"}, {"id": "d", "text": "氧气"}], "subject": "science", "explanation": "光合作用吸收二氧化碳、放出氧气。"}, {"id": "hi-science-5", "band": "high", "answer": "a", "prompt": "人体消化吸收营养，主要在哪个器官完成？", "choices": [{"id": "a", "text": "小肠"}, {"id": "b", "text": "胃"}, {"id": "c", "text": "大肠"}, {"id": "d", "text": "食道"}], "subject": "science", "explanation": "小肠是吸收营养的主要场所。"}, {"id": "hi-science-6", "band": "high", "answer": "b", "prompt": "下面哪种动物是两栖动物？", "choices": [{"id": "a", "text": "鲫鱼"}, {"id": "b", "text": "青蛙"}, {"id": "c", "text": "麻雀"}, {"id": "d", "text": "兔子"}], "subject": "science", "explanation": "青蛙幼时生活在水中、成年可在陆地，是两栖动物。"}, {"id": "hi-science-7", "band": "high", "answer": "c", "prompt": "下面哪种是绝缘体，不容易导电？", "choices": [{"id": "a", "text": "铜丝"}, {"id": "b", "text": "铁钉"}, {"id": "c", "text": "橡胶"}, {"id": "d", "text": "盐水"}], "subject": "science", "explanation": "橡胶是绝缘体；铜、铁、盐水都能导电。"}, {"id": "hi-science-8", "band": "high", "answer": "d", "prompt": "我们听到声音，是因为物体在做什么？", "choices": [{"id": "a", "text": "发光"}, {"id": "b", "text": "发热"}, {"id": "c", "text": "变色"}, {"id": "d", "text": "振动"}], "subject": "science", "explanation": "声音是由物体振动产生的。"}, {"id": "hi-science-9", "band": "high", "answer": "a", "prompt": "同一个力，作用在面积越小的地方，压强会怎样？", "choices": [{"id": "a", "text": "越大"}, {"id": "b", "text": "越小"}, {"id": "c", "text": "不变"}, {"id": "d", "text": "消失"}], "subject": "science", "explanation": "受力面积越小，压强越大（这就是刀要磨薄的道理）。"}, {"id": "hi-science-10", "band": "high", "answer": "b", "prompt": "把一根铅笔放进装水的杯子，从侧面看铅笔像折断了，这是光的什么现象？", "choices": [{"id": "a", "text": "反射"}, {"id": "b", "text": "折射"}, {"id": "c", "text": "色散"}, {"id": "d", "text": "直线传播"}], "subject": "science", "explanation": "光从水进入空气时方向改变，发生折射，看起来像断了。"}, {"id": "hi-science-11", "band": "high", "answer": "c", "prompt": "为什么夏天穿浅色衣服比深色衣服凉快？", "choices": [{"id": "a", "text": "浅色更好看"}, {"id": "b", "text": "浅色更薄"}, {"id": "c", "text": "浅色反射阳光多、吸热少"}, {"id": "d", "text": "深色会发光"}], "subject": "science", "explanation": "浅色反射的阳光多，吸收的热少，所以更凉快。"}, {"id": "hi-science-12", "band": "high", "answer": "d", "prompt": "蜡烛燃烧后越来越短，蜡到哪里去了？", "choices": [{"id": "a", "text": "凭空消失了"}, {"id": "b", "text": "变成了灰"}, {"id": "c", "text": "流到桌子上全留着"}, {"id": "d", "text": "燃烧后变成气体跑到空气里"}], "subject": "science", "explanation": "蜡燃烧后主要变成二氧化碳和水蒸气散到空气中。"}, {"id": "hi-science-13", "band": "high", "answer": "a", "prompt": "下面哪种变化是化学变化（产生了新物质）？", "choices": [{"id": "a", "text": "木柴燃烧"}, {"id": "b", "text": "冰化成水"}, {"id": "c", "text": "纸被剪碎"}, {"id": "d", "text": "水变成水蒸气"}], "subject": "science", "explanation": "燃烧生成新物质属于化学变化；其余只是状态或形状改变。"}, {"id": "hi-science-14", "band": "high", "answer": "b", "prompt": "太阳系里体积最大的行星是哪个？", "choices": [{"id": "a", "text": "地球"}, {"id": "b", "text": "木星"}, {"id": "c", "text": "火星"}, {"id": "d", "text": "土星"}], "subject": "science", "explanation": "木星是太阳系中体积和质量最大的行星。"}, {"id": "hi-science-15", "band": "high", "answer": "c", "prompt": "月相变化（月亮圆缺）大约多少天循环一次？", "choices": [{"id": "a", "text": "约 7 天"}, {"id": "b", "text": "约一年"}, {"id": "c", "text": "约一个月（约30天）"}, {"id": "d", "text": "约一天"}], "subject": "science", "explanation": "月相变化的周期大约是一个月。"}, {"id": "hi-science-16", "band": "high", "answer": "d", "prompt": "人体里数量最多、负责运输氧气的血细胞是哪种？", "choices": [{"id": "a", "text": "白细胞"}, {"id": "b", "text": "血小板"}, {"id": "c", "text": "神经细胞"}, {"id": "d", "text": "红细胞"}], "subject": "science", "explanation": "红细胞里的血红蛋白负责运输氧气。"}, {"id": "hi-science-17", "band": "high", "answer": "a", "prompt": "下面哪种食物主要提供蛋白质？", "choices": [{"id": "a", "text": "鸡蛋"}, {"id": "b", "text": "米饭"}, {"id": "c", "text": "白糖"}, {"id": "d", "text": "食用油"}], "subject": "science", "explanation": "鸡蛋、瘦肉、豆类富含蛋白质；米饭主要是淀粉。"}, {"id": "hi-science-18", "band": "high", "answer": "b", "prompt": "电路要能让灯亮，必须形成什么？", "choices": [{"id": "a", "text": "断路"}, {"id": "b", "text": "通路（闭合回路）"}, {"id": "c", "text": "短路"}, {"id": "d", "text": "高温"}], "subject": "science", "explanation": "只有形成闭合回路，电流才能通过让灯亮。"}, {"id": "hi-science-19", "band": "high", "answer": "c", "prompt": "电池上的“＋”和“－”表示什么？", "choices": [{"id": "a", "text": "大小"}, {"id": "b", "text": "加减号"}, {"id": "c", "text": "正极和负极"}, {"id": "d", "text": "温度高低"}], "subject": "science", "explanation": "电池有正极（＋）和负极（－），方向接反灯不亮。"}, {"id": "hi-science-20", "band": "high", "answer": "d", "prompt": "为什么高山上烧水，水还没到100℃就开了？", "choices": [{"id": "a", "text": "山上水更脏"}, {"id": "b", "text": "山上火更旺"}, {"id": "c", "text": "山上水更少"}, {"id": "d", "text": "海拔高、气压低，沸点降低"}], "subject": "science", "explanation": "海拔越高气压越低，水的沸点也随之降低。"}, {"id": "hi-science-21", "band": "high", "answer": "a", "prompt": "把磁铁的同名磁极靠近，会发生什么？", "choices": [{"id": "a", "text": "互相排斥"}, {"id": "b", "text": "互相吸引"}, {"id": "c", "text": "没有反应"}, {"id": "d", "text": "会爆炸"}], "subject": "science", "explanation": "磁极“同名相斥、异名相吸”。"}, {"id": "hi-science-22", "band": "high", "answer": "b", "prompt": "彩虹其实是阳光经过水滴发生了什么形成的？", "choices": [{"id": "a", "text": "反射后燃烧"}, {"id": "b", "text": "折射和色散，分解成七种颜色"}, {"id": "c", "text": "变成热量"}, {"id": "d", "text": "被吸收掉"}], "subject": "science", "explanation": "阳光经水滴折射、色散，分成七色光形成彩虹。"}, {"id": "hi-science-23", "band": "high", "answer": "c", "prompt": "鱼用什么呼吸？", "choices": [{"id": "a", "text": "肺"}, {"id": "b", "text": "皮肤"}, {"id": "c", "text": "鳃"}, {"id": "d", "text": "鳍"}], "subject": "science", "explanation": "鱼用鳃从水中获取氧气。"}, {"id": "hi-science-24", "band": "high", "answer": "d", "prompt": "种子发芽一般不需要下面哪个条件？", "choices": [{"id": "a", "text": "适宜的温度"}, {"id": "b", "text": "水分"}, {"id": "c", "text": "空气"}, {"id": "d", "text": "阳光"}], "subject": "science", "explanation": "种子发芽需要水、空气和适宜温度，多数不一定需要光。"}, {"id": "hi-science-25", "band": "high", "answer": "a", "prompt": "下面哪种现象说明大气有压力（大气压）？", "choices": [{"id": "a", "text": "吸管能把饮料吸上来"}, {"id": "b", "text": "石头往下掉"}, {"id": "c", "text": "铁会生锈"}, {"id": "d", "text": "冰会融化"}], "subject": "science", "explanation": "吸管吸饮料靠的就是外界大气压把液体压上去。"}, {"id": "hi-science-26", "band": "high", "answer": "b", "prompt": "人体的“总指挥”，控制思维和身体活动的器官是哪个？", "choices": [{"id": "a", "text": "心脏"}, {"id": "b", "text": "大脑"}, {"id": "c", "text": "肝脏"}, {"id": "d", "text": "肾脏"}], "subject": "science", "explanation": "大脑是神经系统的中枢，指挥身体各项活动。"}, {"id": "hi-science-27", "band": "high", "answer": "c", "prompt": "下面哪种能源是可再生能源？", "choices": [{"id": "a", "text": "煤"}, {"id": "b", "text": "石油"}, {"id": "c", "text": "太阳能"}, {"id": "d", "text": "天然气"}], "subject": "science", "explanation": "太阳能用之不竭，是可再生能源；煤、石油、天然气是化石能源。"}, {"id": "hi-science-28", "band": "high", "answer": "d", "prompt": "为什么冬天往手上哈气会觉得暖，往手上吹气却觉得凉？", "choices": [{"id": "a", "text": "哈气是热气、吹气是冷气"}, {"id": "b", "text": "手会变颜色"}, {"id": "c", "text": "没有区别"}, {"id": "d", "text": "哈气慢、带的热气多；吹气快、加速蒸发带走热"}], "subject": "science", "explanation": "哈气慢且湿热；吹气快加速皮肤上水分蒸发，蒸发吸热让人觉凉。"}, {"id": "hi-science-29", "band": "high", "answer": "a", "prompt": "蝴蝶的一生要经过哪几个阶段？", "choices": [{"id": "a", "text": "卵→幼虫→蛹→成虫"}, {"id": "b", "text": "卵→成虫"}, {"id": "c", "text": "幼虫→成虫"}, {"id": "d", "text": "蛹→卵→成虫"}], "subject": "science", "explanation": "蝴蝶是完全变态：卵、幼虫、蛹、成虫四个阶段。"}, {"id": "hi-science-30", "band": "high", "answer": "b", "prompt": "夜空中看起来一闪一闪、自己不动的“星星”，大多是什么？", "choices": [{"id": "a", "text": "行星"}, {"id": "b", "text": "会自己发光的恒星"}, {"id": "c", "text": "卫星"}, {"id": "d", "text": "流星"}], "subject": "science", "explanation": "夜空中绝大多数星星是自己发光的恒星。"}, {"id": "hi-science-31", "band": "high", "answer": "c", "prompt": "下面哪种做法能加快糖在水里溶解？", "choices": [{"id": "a", "text": "用冷水、不搅拌"}, {"id": "b", "text": "把糖块整个放进去不动"}, {"id": "c", "text": "用热水并搅拌"}, {"id": "d", "text": "盖上盖子放一夜"}], "subject": "science", "explanation": "提高温度、搅拌、把糖弄碎都能加快溶解。"}, {"id": "hi-science-32", "band": "high", "answer": "d", "prompt": "地球上一年有四季交替，主要是因为什么？", "choices": [{"id": "a", "text": "地球离太阳忽远忽近"}, {"id": "b", "text": "月亮绕地球转"}, {"id": "c", "text": "太阳忽大忽小"}, {"id": "d", "text": "地轴是倾斜的，地球绕太阳公转"}], "subject": "science", "explanation": "地轴倾斜加上公转，使各地受到的太阳照射强弱随季节变化。"}, {"id": "hi-science-33", "band": "high", "answer": "a", "prompt": "下面哪个不是昆虫？", "choices": [{"id": "a", "text": "蜘蛛"}, {"id": "b", "text": "蚂蚁"}, {"id": "c", "text": "蜜蜂"}, {"id": "d", "text": "蝗虫"}], "subject": "science", "explanation": "昆虫有 6 条腿；蜘蛛有 8 条腿，属于蛛形类，不是昆虫。"}, {"id": "hi-science-34", "band": "high", "answer": "b", "prompt": "热水瓶能保温，主要是因为它能减少热量的什么？", "choices": [{"id": "a", "text": "产生"}, {"id": "b", "text": "传递（散失）"}, {"id": "c", "text": "颜色"}, {"id": "d", "text": "重量"}], "subject": "science", "explanation": "保温瓶通过真空夹层等减少热量散失，从而保温。"}, {"id": "hi-science-35", "band": "high", "answer": "c", "prompt": "我们看到闪电后过一会儿才听到雷声，这说明什么？", "choices": [{"id": "a", "text": "声音比光快"}, {"id": "b", "text": "它们速度一样"}, {"id": "c", "text": "光比声音传播得快"}, {"id": "d", "text": "雷在闪电之后才发生"}], "subject": "science", "explanation": "光速远大于声速，所以先看到闪电、后听到雷声。"}, {"id": "hi-science-36", "band": "high", "answer": "d", "prompt": "下面哪种物质能被磁铁吸引？", "choices": [{"id": "a", "text": "铜"}, {"id": "b", "text": "铝"}, {"id": "c", "text": "塑料"}, {"id": "d", "text": "铁"}], "subject": "science", "explanation": "铁、钴、镍等能被磁铁吸引；铜、铝、塑料不能。"}, {"id": "hi-science-37", "band": "high", "answer": "a", "prompt": "把一杯热水和一杯冷水放在房间里，过一会儿它们的温度会怎样？", "choices": [{"id": "a", "text": "都接近室温"}, {"id": "b", "text": "热水更热、冷水更冷"}, {"id": "c", "text": "都变成 0℃"}, {"id": "d", "text": "完全不变"}], "subject": "science", "explanation": "热会从高温向低温传递，最终都趋近室温。"}, {"id": "hi-science-38", "band": "high", "answer": "b", "prompt": "下面哪种食物含有丰富的维生素 C？", "choices": [{"id": "a", "text": "米饭"}, {"id": "b", "text": "橙子"}, {"id": "c", "text": "黄油"}, {"id": "d", "text": "白盐"}], "subject": "science", "explanation": "橙子、猕猴桃等新鲜水果蔬菜富含维生素 C。"}, {"id": "hi-science-39", "band": "high", "answer": "c", "prompt": "把同样多的水分别装进高瘦杯和矮胖杯，水的体积怎样？", "choices": [{"id": "a", "text": "高瘦杯里多"}, {"id": "b", "text": "矮胖杯里多"}, {"id": "c", "text": "一样多"}, {"id": "d", "text": "没法比"}], "subject": "science", "explanation": "水量没变，体积就一样多，只是形状不同。"}, {"id": "hi-science-40", "band": "high", "answer": "d", "prompt": "人在剧烈运动后呼吸和心跳加快，主要是为了什么？", "choices": [{"id": "a", "text": "给身体散热好看"}, {"id": "b", "text": "让人变高"}, {"id": "c", "text": "没有原因"}, {"id": "d", "text": "更快地给肌肉运送氧气、带走废物"}], "subject": "science", "explanation": "运动时肌肉需要更多氧气，呼吸心跳加快以加速供氧排废。"}, {"id": "low-math-b2-001", "band": "low", "answer": "a", "prompt": "🐰🐰🐰🐰🐰🐰🐰 草地上有几只小兔子？", "choices": [{"id": "a", "text": "7 只"}, {"id": "b", "text": "6 只"}, {"id": "c", "text": "8 只"}], "subject": "math", "difficulty": "quick", "explanation": "一个一个数小兔子：1、2、3、4、5、6、7，正好 7 只。"}, {"id": "low-math-b2-002", "band": "low", "answer": "b", "prompt": "🍓🍓🍓🍓🍓🍓🍓🍓🍓🍓 盘子里有几颗草莓？", "choices": [{"id": "a", "text": "9 颗"}, {"id": "b", "text": "10 颗"}, {"id": "c", "text": "11 颗"}], "subject": "math", "difficulty": "quick", "explanation": "数一数草莓：1 到 10，正好 10 颗。"}, {"id": "low-math-b2-003", "band": "low", "answer": "b", "prompt": "11 加 6 等于几？", "choices": [{"id": "a", "text": "16"}, {"id": "b", "text": "17"}, {"id": "c", "text": "18"}], "subject": "math", "difficulty": "quick", "explanation": "把 11 拆成 10 和 1，1 加 6 等于 7，再加上 10 就是 17。"}, {"id": "low-math-b2-004", "band": "low", "answer": "a", "prompt": "14 加 5 等于几？", "choices": [{"id": "a", "text": "19"}, {"id": "b", "text": "18"}, {"id": "c", "text": "20"}], "subject": "math", "difficulty": "quick", "explanation": "14 加 5，个位 4 加 5 等于 9，所以是 19。"}, {"id": "low-math-b2-005", "band": "low", "answer": "c", "prompt": "16 减 8 等于几？", "choices": [{"id": "a", "text": "9"}, {"id": "b", "text": "7"}, {"id": "c", "text": "8"}], "subject": "math", "difficulty": "quick", "explanation": "16 减 8，可以想 8 加几等于 16，8 加 8 等于 16，所以答案是 8。"}, {"id": "low-math-b2-006", "band": "low", "answer": "a", "prompt": "18 减 9 等于几？", "choices": [{"id": "a", "text": "9"}, {"id": "b", "text": "10"}, {"id": "c", "text": "8"}], "subject": "math", "difficulty": "quick", "explanation": "9 加 9 等于 18，所以 18 减 9 就是 9。"}, {"id": "low-math-b2-007", "band": "low", "answer": "c", "prompt": "停车场原来有 7 辆车，又开来 6 辆，现在一共几辆？", "choices": [{"id": "a", "text": "12 辆"}, {"id": "b", "text": "14 辆"}, {"id": "c", "text": "13 辆"}], "subject": "math", "difficulty": "quick", "explanation": "7 加 6 等于 13，所以现在有 13 辆车。"}, {"id": "low-math-b2-008", "band": "low", "answer": "c", "prompt": "树上有 12 只小鸟，飞走了 5 只，还剩几只？", "choices": [{"id": "a", "text": "8 只"}, {"id": "b", "text": "6 只"}, {"id": "c", "text": "7 只"}], "subject": "math", "difficulty": "quick", "explanation": "12 减 5 等于 7，所以树上还剩 7 只小鸟。"}, {"id": "low-math-b2-009", "band": "low", "answer": "c", "prompt": "20 加 30 等于多少？", "choices": [{"id": "a", "text": "60"}, {"id": "b", "text": "40"}, {"id": "c", "text": "50"}], "subject": "math", "difficulty": "quick", "explanation": "2 个十加 3 个十等于 5 个十，也就是 50。"}, {"id": "low-math-b2-010", "band": "low", "answer": "a", "prompt": "60 减 20 等于多少？", "choices": [{"id": "a", "text": "40"}, {"id": "b", "text": "30"}, {"id": "c", "text": "50"}], "subject": "math", "difficulty": "quick", "explanation": "6 个十减 2 个十等于 4 个十，也就是 40。"}, {"id": "low-math-b2-011", "band": "low", "answer": "b", "prompt": "35 加 4 等于多少？", "choices": [{"id": "a", "text": "40"}, {"id": "b", "text": "39"}, {"id": "c", "text": "38"}], "subject": "math", "difficulty": "quick", "explanation": "个位 5 加 4 等于 9，十位不变，所以是 39。"}, {"id": "low-math-b2-012", "band": "low", "answer": "a", "prompt": "48 减 6 等于多少？", "choices": [{"id": "a", "text": "42"}, {"id": "b", "text": "43"}, {"id": "c", "text": "41"}], "subject": "math", "difficulty": "quick", "explanation": "个位 8 减 6 等于 2，十位不变，所以是 42。"}, {"id": "low-math-b2-013", "band": "low", "answer": "c", "prompt": "2 乘 3 等于多少？（口诀：二三得六）", "choices": [{"id": "a", "text": "8"}, {"id": "b", "text": "5"}, {"id": "c", "text": "6"}], "subject": "math", "difficulty": "quick", "explanation": "2 乘 3 就是 3 个 2 相加：2 加 2 加 2 等于 6。"}, {"id": "low-math-b2-014", "band": "low", "answer": "c", "prompt": "3 乘 4 等于多少？（口诀：三四十二）", "choices": [{"id": "a", "text": "14"}, {"id": "b", "text": "7"}, {"id": "c", "text": "12"}], "subject": "math", "difficulty": "quick", "explanation": "3 乘 4 就是 4 个 3：3 加 3 加 3 加 3 等于 12。"}, {"id": "low-math-b2-015", "band": "low", "answer": "b", "prompt": "5 乘 5 等于多少？（口诀：五五二十五）", "choices": [{"id": "a", "text": "20"}, {"id": "b", "text": "25"}, {"id": "c", "text": "10"}], "subject": "math", "difficulty": "quick", "explanation": "5 乘 5 就是 5 个 5 相加，等于 25。"}, {"id": "low-math-b2-016", "band": "low", "answer": "c", "prompt": "4 乘 2 等于多少？", "choices": [{"id": "a", "text": "6"}, {"id": "b", "text": "10"}, {"id": "c", "text": "8"}], "subject": "math", "difficulty": "quick", "explanation": "4 乘 2 就是 2 个 4：4 加 4 等于 8。"}, {"id": "low-math-b2-017", "band": "low", "answer": "b", "prompt": "每个小朋友分 2 颗糖，3 个小朋友一共要几颗糖？", "choices": [{"id": "a", "text": "7 颗"}, {"id": "b", "text": "6 颗"}, {"id": "c", "text": "5 颗"}], "subject": "math", "difficulty": "deep", "explanation": "3 个小朋友每人 2 颗，就是 2 乘 3 等于 6 颗。"}, {"id": "low-math-b2-018", "band": "low", "answer": "a", "prompt": "找规律：3、6、9、12、后面是几？", "choices": [{"id": "a", "text": "15"}, {"id": "b", "text": "14"}, {"id": "c", "text": "13"}], "subject": "math", "difficulty": "quick", "explanation": "每次多 3：3、6、9、12，再加 3 就是 15。"}, {"id": "low-math-b2-019", "band": "low", "answer": "a", "prompt": "找规律：5、10、15、20、后面是几？", "choices": [{"id": "a", "text": "25"}, {"id": "b", "text": "22"}, {"id": "c", "text": "30"}], "subject": "math", "difficulty": "quick", "explanation": "每次多 5：20 再加 5 就是 25。"}, {"id": "low-math-b2-020", "band": "low", "answer": "a", "prompt": "找规律：1、2、4、8、后面是几？", "choices": [{"id": "a", "text": "16"}, {"id": "b", "text": "12"}, {"id": "c", "text": "10"}], "subject": "math", "difficulty": "deep", "explanation": "每个数是前面的 2 倍：8 的 2 倍是 16。"}, {"id": "low-math-b2-021", "band": "low", "answer": "c", "prompt": "一个三角形 3 条边，两个三角形一共有几条边？", "choices": [{"id": "a", "text": "5 条"}, {"id": "b", "text": "9 条"}, {"id": "c", "text": "6 条"}], "subject": "math", "difficulty": "quick", "explanation": "一个三角形 3 条边，两个就是 3 加 3 等于 6 条边。"}, {"id": "low-math-b2-022", "band": "low", "answer": "c", "prompt": "下面哪种图形有 4 条边、4 个角，而且 4 条边一样长？", "choices": [{"id": "a", "text": "三角形"}, {"id": "b", "text": "圆形"}, {"id": "c", "text": "正方形"}], "subject": "math", "difficulty": "quick", "explanation": "正方形有 4 条一样长的边和 4 个角；三角形只有 3 条边，圆形没有角。"}, {"id": "low-math-b2-023", "band": "low", "answer": "a", "prompt": "钟表上短针指着 9，长针指着 12，是几点？", "choices": [{"id": "a", "text": "9 点"}, {"id": "b", "text": "12 点"}, {"id": "c", "text": "3 点"}], "subject": "math", "difficulty": "quick", "explanation": "长针指 12、短针指着几就是几点，短针指 9 所以是 9 点。"}, {"id": "low-math-b2-024", "band": "low", "answer": "b", "prompt": "长针指着 6、短针在 7 和 8 中间，大约是几点半？", "choices": [{"id": "a", "text": "8 点半"}, {"id": "b", "text": "7 点半"}, {"id": "c", "text": "6 点半"}], "subject": "math", "difficulty": "deep", "explanation": "长针指 6 表示半点，短针在 7 和 8 中间表示 7 点多，所以是 7 点半。"}, {"id": "low-math-b2-025", "band": "low", "answer": "b", "prompt": "1 个 5 角和 1 个 5 角合起来是多少钱？", "choices": [{"id": "a", "text": "5 角"}, {"id": "b", "text": "1 元"}, {"id": "c", "text": "2 元"}], "subject": "math", "difficulty": "quick", "explanation": "5 角加 5 角等于 10 角，10 角正好是 1 元。"}, {"id": "low-math-b2-026", "band": "low", "answer": "b", "prompt": "一支铅笔 3 元，买 2 支要多少钱？", "choices": [{"id": "a", "text": "8 元"}, {"id": "b", "text": "6 元"}, {"id": "c", "text": "5 元"}], "subject": "math", "difficulty": "deep", "explanation": "一支 3 元，2 支就是 3 加 3 等于 6 元。"}, {"id": "low-math-b2-027", "band": "low", "answer": "a", "prompt": "8 个小朋友排队，从前往后数小红排第 3，她后面有几个人？", "choices": [{"id": "a", "text": "5 人"}, {"id": "b", "text": "6 人"}, {"id": "c", "text": "4 人"}], "subject": "math", "difficulty": "deep", "explanation": "一共 8 人，小红和她前面的 2 人共 3 人，剩下 8 减 3 等于 5 人在她后面。"}, {"id": "low-math-b2-028", "band": "low", "answer": "b", "prompt": "妈妈买了 6 个苹果，吃了 2 个，又买回 3 个，现在有几个苹果？", "choices": [{"id": "a", "text": "8 个"}, {"id": "b", "text": "7 个"}, {"id": "c", "text": "6 个"}], "subject": "math", "difficulty": "deep", "explanation": "6 个吃掉 2 个还剩 4 个，再买 3 个，4 加 3 等于 7 个。"}, {"id": "low-math-b2-029", "band": "low", "answer": "a", "prompt": "比 20 少 3 的数是几？", "choices": [{"id": "a", "text": "17"}, {"id": "b", "text": "16"}, {"id": "c", "text": "23"}], "subject": "math", "difficulty": "deep", "explanation": "“少 3”就是减 3，20 减 3 等于 17。"}, {"id": "low-math-b2-030", "band": "low", "answer": "b", "prompt": "一个数和 8 合起来是 15，这个数是几？", "choices": [{"id": "a", "text": "8"}, {"id": "b", "text": "7"}, {"id": "c", "text": "6"}], "subject": "math", "difficulty": "deep", "explanation": "15 减 8 等于 7，所以这个数是 7。"}, {"id": "high-math-b2-001", "band": "high", "answer": "c", "prompt": "3/8 加 1/8 等于多少？", "choices": [{"id": "a", "text": "4/16"}, {"id": "b", "text": "3/8"}, {"id": "c", "text": "1/2"}], "subject": "math", "difficulty": "quick", "explanation": "分母相同，分子相加：3 加 1 等于 4，得 4/8，约分后是 1/2。"}, {"id": "high-math-b2-002", "band": "high", "answer": "a", "prompt": "2/3 减 1/6 等于多少？", "choices": [{"id": "a", "text": "1/2"}, {"id": "b", "text": "1/6"}, {"id": "c", "text": "1/3"}], "subject": "math", "difficulty": "deep", "explanation": "2/3 通分成 4/6，4/6 减 1/6 等于 3/6，约分后是 1/2。"}, {"id": "high-math-b2-003", "band": "high", "answer": "b", "prompt": "0.6 乘 0.5 等于多少？", "choices": [{"id": "a", "text": "3.0"}, {"id": "b", "text": "0.3"}, {"id": "c", "text": "0.11"}], "subject": "math", "difficulty": "quick", "explanation": "6 乘 5 等于 30，两个因数共 2 位小数，所以是 0.30，也就是 0.3。"}, {"id": "high-math-b2-004", "band": "high", "answer": "c", "prompt": "7.2 除以 0.8 等于多少？", "choices": [{"id": "a", "text": "0.9"}, {"id": "b", "text": "90"}, {"id": "c", "text": "9"}], "subject": "math", "difficulty": "deep", "explanation": "把除数和被除数同时乘 10 变成 72 除以 8 等于 9。"}, {"id": "high-math-b2-005", "band": "high", "answer": "c", "prompt": "40 的 15% 是多少？", "choices": [{"id": "a", "text": "4"}, {"id": "b", "text": "15"}, {"id": "c", "text": "6"}], "subject": "math", "difficulty": "quick", "explanation": "15% 就是 0.15，40 乘 0.15 等于 6。"}, {"id": "high-math-b2-006", "band": "high", "answer": "b", "prompt": "一个数的 30% 是 21，这个数是多少？", "choices": [{"id": "a", "text": "63"}, {"id": "b", "text": "70"}, {"id": "c", "text": "7"}], "subject": "math", "difficulty": "deep", "explanation": "用 21 除以 30%，也就是 21 除以 0.3 等于 70。"}, {"id": "high-math-b2-007", "band": "high", "answer": "c", "prompt": "一件商品标价 200 元，先打九折，再减 20 元，实付多少？", "choices": [{"id": "a", "text": "180 元"}, {"id": "b", "text": "170 元"}, {"id": "c", "text": "160 元"}], "subject": "math", "difficulty": "deep", "explanation": "九折就是 200 乘 0.9 等于 180 元，再减 20 元就是 160 元。"}, {"id": "high-math-b2-008", "band": "high", "answer": "a", "prompt": "商店进一件衣服花 80 元，卖 100 元，利润率是多少？", "choices": [{"id": "a", "text": "25%"}, {"id": "b", "text": "80%"}, {"id": "c", "text": "20%"}], "subject": "math", "difficulty": "deep", "explanation": "利润是 100 减 80 等于 20 元，利润率等于利润除以成本：20 除以 80 等于 25%。"}, {"id": "high-math-b2-009", "band": "high", "answer": "c", "prompt": "甲乙两地相距 360 千米，一辆车 4 小时跑完，平均每小时多少千米？", "choices": [{"id": "a", "text": "80 千米"}, {"id": "b", "text": "100 千米"}, {"id": "c", "text": "90 千米"}], "subject": "math", "difficulty": "quick", "explanation": "速度等于路程除以时间：360 除以 4 等于 90 千米每小时。"}, {"id": "high-math-b2-010", "band": "high", "answer": "a", "prompt": "两车从相距 300 千米的两地相向而行，一辆每小时 60 千米，另一辆每小时 40 千米，几小时相遇？", "choices": [{"id": "a", "text": "3 小时"}, {"id": "b", "text": "4 小时"}, {"id": "c", "text": "5 小时"}], "subject": "math", "difficulty": "deep", "explanation": "两车每小时一共靠近 60 加 40 等于 100 千米，300 除以 100 等于 3 小时相遇。"}, {"id": "high-math-b2-011", "band": "high", "answer": "b", "prompt": "一项工程甲单独做 12 天完成，乙单独做 6 天完成，两人合做几天完成？", "choices": [{"id": "a", "text": "3 天"}, {"id": "b", "text": "4 天"}, {"id": "c", "text": "9 天"}], "subject": "math", "difficulty": "deep", "explanation": "甲每天做 1/12，乙每天做 1/6 即 2/12，合起来每天做 3/12 即 1/4，所以 4 天完成。"}, {"id": "high-math-b2-012", "band": "high", "answer": "c", "prompt": "一个长方形的长是 12 厘米，宽是长的一半，面积是多少？", "choices": [{"id": "a", "text": "36 平方厘米"}, {"id": "b", "text": "144 平方厘米"}, {"id": "c", "text": "72 平方厘米"}], "subject": "math", "difficulty": "deep", "explanation": "宽是 12 的一半即 6 厘米，面积等于长乘宽：12 乘 6 等于 72 平方厘米。"}, {"id": "high-math-b2-013", "band": "high", "answer": "a", "prompt": "一个正方体的棱长是 4 厘米，它的体积是多少？", "choices": [{"id": "a", "text": "64 立方厘米"}, {"id": "b", "text": "16 立方厘米"}, {"id": "c", "text": "48 立方厘米"}], "subject": "math", "difficulty": "quick", "explanation": "正方体体积等于棱长乘棱长乘棱长：4 乘 4 乘 4 等于 64 立方厘米。"}, {"id": "high-math-b2-014", "band": "high", "answer": "c", "prompt": "一个圆的直径是 6 厘米，它的面积约是多少？(π取3.14)", "choices": [{"id": "a", "text": "18.84 平方厘米"}, {"id": "b", "text": "113.04 平方厘米"}, {"id": "c", "text": "28.26 平方厘米"}], "subject": "math", "difficulty": "deep", "explanation": "半径是直径的一半即 3 厘米，面积等于 π 乘半径的平方：3.14 乘 3 乘 3 等于 28.26 平方厘米。"}, {"id": "high-math-b2-015", "band": "high", "answer": "c", "prompt": "一个三角形面积是 24 平方厘米，底是 8 厘米，高是多少？", "choices": [{"id": "a", "text": "12 厘米"}, {"id": "b", "text": "3 厘米"}, {"id": "c", "text": "6 厘米"}], "subject": "math", "difficulty": "deep", "explanation": "三角形面积等于底乘高除以 2，所以高等于面积乘 2 再除以底：24 乘 2 除以 8 等于 6 厘米。"}, {"id": "high-math-b2-016", "band": "high", "answer": "a", "prompt": "18 和 24 的最大公因数是多少？", "choices": [{"id": "a", "text": "6"}, {"id": "b", "text": "12"}, {"id": "c", "text": "3"}], "subject": "math", "difficulty": "quick", "explanation": "18 的因数有 1、2、3、6、9、18，24 的因数有 1、2、3、4、6、8、12、24，最大的公共因数是 6。"}, {"id": "high-math-b2-017", "band": "high", "answer": "a", "prompt": "6 和 8 的最小公倍数是多少？", "choices": [{"id": "a", "text": "24"}, {"id": "b", "text": "14"}, {"id": "c", "text": "48"}], "subject": "math", "difficulty": "quick", "explanation": "6 的倍数有 6、12、18、24，8 的倍数有 8、16、24，最小的公共倍数是 24。"}, {"id": "high-math-b2-018", "band": "high", "answer": "c", "prompt": "下面哪个数既是 3 的倍数又是 5 的倍数？", "choices": [{"id": "a", "text": "20"}, {"id": "b", "text": "25"}, {"id": "c", "text": "45"}], "subject": "math", "difficulty": "quick", "explanation": "45 等于 3 乘 15，也等于 5 乘 9，所以同时是 3 和 5 的倍数；20、25 不是 3 的倍数。"}, {"id": "high-math-b2-019", "band": "high", "answer": "a", "prompt": "甲乙两数的比是 2:3，甲是 18，乙是多少？", "choices": [{"id": "a", "text": "27"}, {"id": "b", "text": "24"}, {"id": "c", "text": "12"}], "subject": "math", "difficulty": "deep", "explanation": "甲占 2 份是 18，每份是 9，乙占 3 份就是 9 乘 3 等于 27。"}, {"id": "high-math-b2-020", "band": "high", "answer": "c", "prompt": "把 48 块糖按 1:3 分给两个人，多的那个人分到几块？", "choices": [{"id": "a", "text": "12 块"}, {"id": "b", "text": "24 块"}, {"id": "c", "text": "36 块"}], "subject": "math", "difficulty": "deep", "explanation": "一共 1 加 3 等于 4 份，每份 48 除以 4 等于 12 块，多的人占 3 份就是 36 块。"}, {"id": "high-math-b2-021", "band": "high", "answer": "a", "prompt": "解方程：3x 加 5 等于 20，x 等于多少？", "choices": [{"id": "a", "text": "5"}, {"id": "b", "text": "15"}, {"id": "c", "text": "6"}], "subject": "math", "difficulty": "deep", "explanation": "两边先减 5 得 3x 等于 15，再除以 3 得 x 等于 5。"}, {"id": "high-math-b2-022", "band": "high", "answer": "c", "prompt": "一个数加上它的一半等于 30，这个数是多少？", "choices": [{"id": "a", "text": "45"}, {"id": "b", "text": "15"}, {"id": "c", "text": "20"}], "subject": "math", "difficulty": "deep", "explanation": "这个数加它的一半就是它的 1.5 倍，30 除以 1.5 等于 20。"}, {"id": "high-math-b2-023", "band": "high", "answer": "a", "prompt": "把 0.45 化成最简分数是多少？", "choices": [{"id": "a", "text": "9/20"}, {"id": "b", "text": "4/5"}, {"id": "c", "text": "45/100"}], "subject": "math", "difficulty": "quick", "explanation": "0.45 等于 45/100，分子分母同时除以 5 得 9/20，不能再约分。"}, {"id": "high-math-b2-024", "band": "high", "answer": "c", "prompt": "5/8 化成百分数是多少？", "choices": [{"id": "a", "text": "58%"}, {"id": "b", "text": "80%"}, {"id": "c", "text": "62.5%"}], "subject": "math", "difficulty": "deep", "explanation": "5 除以 8 等于 0.625，化成百分数就是 62.5%。"}, {"id": "high-math-b2-025", "band": "high", "answer": "c", "prompt": "一组数据 4、6、8、10、12 的平均数是多少？", "choices": [{"id": "a", "text": "9"}, {"id": "b", "text": "7"}, {"id": "c", "text": "8"}], "subject": "math", "difficulty": "quick", "explanation": "5 个数相加等于 40，平均数等于 40 除以 5 等于 8。"}, {"id": "high-math-b2-026", "band": "high", "answer": "c", "prompt": "一个袋子里有 3 个红球和 2 个白球，随便摸一个，摸到红球的可能性是多少？", "choices": [{"id": "a", "text": "2/5"}, {"id": "b", "text": "1/2"}, {"id": "c", "text": "3/5"}], "subject": "math", "difficulty": "quick", "explanation": "一共 5 个球，红球有 3 个，所以摸到红球的可能性是 3/5。"}, {"id": "high-math-b2-027", "band": "high", "answer": "b", "prompt": "把一根 2 米长的绳子平均分成 5 段，每段长多少米？", "choices": [{"id": "a", "text": "0.5 米"}, {"id": "b", "text": "0.4 米"}, {"id": "c", "text": "0.2 米"}], "subject": "math", "difficulty": "quick", "explanation": "2 除以 5 等于 0.4，所以每段长 0.4 米。"}, {"id": "high-math-b2-028", "band": "high", "answer": "a", "prompt": "鸡兔同笼，共 10 个头、28 条腿，鸡有几只？", "choices": [{"id": "a", "text": "6 只"}, {"id": "b", "text": "4 只"}, {"id": "c", "text": "8 只"}], "subject": "math", "difficulty": "deep", "explanation": "假设全是鸡有 20 条腿，少了 8 条，每把一只鸡换成兔多 2 条腿，8 除以 2 等于 4 只兔，鸡就是 10 减 4 等于 6 只。"}, {"id": "high-math-b2-029", "band": "high", "answer": "a", "prompt": "找规律：1、3、6、10、15、后面一个数是几？", "choices": [{"id": "a", "text": "21"}, {"id": "b", "text": "20"}, {"id": "c", "text": "18"}], "subject": "math", "difficulty": "deep", "explanation": "相邻两数差是 2、3、4、5，下一个差是 6，所以 15 加 6 等于 21。"}, {"id": "high-math-b2-030", "band": "high", "answer": "a", "prompt": "一个圆柱和一个圆锥底面积、高都相等，圆锥体积是圆柱的几分之几？", "choices": [{"id": "a", "text": "1/3"}, {"id": "b", "text": "1/2"}, {"id": "c", "text": "2/3"}], "subject": "math", "difficulty": "deep", "explanation": "等底等高时，圆锥体积是圆柱体积的三分之一。"}, {"id": "low-chinese-b2-001", "band": "low", "answer": "c", "prompt": "声母“b”和韵母“o”拼在一起，读出来是哪个？", "choices": [{"id": "a", "text": "po（婆婆的婆）"}, {"id": "b", "text": "mo（馒头的馒）"}, {"id": "c", "text": "bo（菠菜的菠）"}], "subject": "chinese", "difficulty": "quick", "explanation": "b+o拼读为bo，就像“菠菜”的“菠”。"}, {"id": "low-chinese-b2-002", "band": "low", "answer": "b", "prompt": "下面哪个字的声母是“zh”？", "choices": [{"id": "a", "text": "草（cǎo）"}, {"id": "b", "text": "桌（zhuō）"}, {"id": "c", "text": "丝（sī）"}], "subject": "chinese", "difficulty": "quick", "explanation": "“桌”读zhuō，声母是翘舌音zh。"}, {"id": "low-chinese-b2-003", "band": "low", "answer": "a", "prompt": "“j、q、x”后面跟“ü”的时候，两点要怎么样？", "choices": [{"id": "a", "text": "去掉两点写成u"}, {"id": "b", "text": "还要保留两点"}, {"id": "c", "text": "换成o"}], "subject": "chinese", "difficulty": "deep", "explanation": "小口诀：j、q、x见到ü，去掉两点还读ü，如“ju、qu、xu”。"}, {"id": "low-chinese-b2-004", "band": "low", "answer": "a", "prompt": "看拼音选字：xià tiān（夏天）的“xià”是哪个字？", "choices": [{"id": "a", "text": "夏"}, {"id": "b", "text": "下"}, {"id": "c", "text": "虾"}], "subject": "chinese", "difficulty": "quick", "explanation": "“夏天”的“夏”，指炎热的季节。"}, {"id": "low-chinese-b2-005", "band": "low", "answer": "a", "prompt": "看拼音选字：bái yún（白云）的“yún”是哪个字？", "choices": [{"id": "a", "text": "云"}, {"id": "b", "text": "运"}, {"id": "c", "text": "匀"}], "subject": "chinese", "difficulty": "quick", "explanation": "天上飘的是“白云”的“云”。"}, {"id": "low-chinese-b2-006", "band": "low", "answer": "c", "prompt": "“青”和“清”是形近字。形容水很干净，应该用哪个？", "choices": [{"id": "a", "text": "晴（晴天）"}, {"id": "b", "text": "青（青草）"}, {"id": "c", "text": "清（河水很清）"}], "subject": "chinese", "difficulty": "deep", "explanation": "带三点水的“清”和水有关，如“清水、清澈”。"}, {"id": "low-chinese-b2-007", "band": "low", "answer": "c", "prompt": "“日”加上“月”，合成的是哪个字？", "choices": [{"id": "a", "text": "晚"}, {"id": "b", "text": "星"}, {"id": "c", "text": "明"}], "subject": "chinese", "difficulty": "quick", "explanation": "日+月=明，太阳和月亮都很亮，所以是“明亮”的“明”。"}, {"id": "low-chinese-b2-008", "band": "low", "answer": "a", "prompt": "同音字辨析：“在”和“再”。“我们明天____见！”填哪个？", "choices": [{"id": "a", "text": "再"}, {"id": "b", "text": "在"}, {"id": "c", "text": "载"}], "subject": "chinese", "difficulty": "deep", "explanation": "“再见”表示又一次见面，用“再”。"}, {"id": "low-chinese-b2-009", "band": "low", "answer": "b", "prompt": "“天”字一共有几画？", "choices": [{"id": "a", "text": "5画"}, {"id": "b", "text": "4画"}, {"id": "c", "text": "3画"}], "subject": "chinese", "difficulty": "quick", "explanation": "“天”：横、横、撇、捺，共4画。"}, {"id": "low-chinese-b2-010", "band": "low", "answer": "b", "prompt": "“出”字一共有几画？", "choices": [{"id": "a", "text": "4画"}, {"id": "b", "text": "5画"}, {"id": "c", "text": "6画"}], "subject": "chinese", "difficulty": "deep", "explanation": "“出”：竖折、竖、竖、竖折、竖，共5画。"}, {"id": "low-chinese-b2-011", "band": "low", "answer": "c", "prompt": "写“十”字时，先写哪一笔？", "choices": [{"id": "a", "text": "两笔一起写"}, {"id": "b", "text": "先写竖，再写横"}, {"id": "c", "text": "先写横，再写竖"}], "subject": "chinese", "difficulty": "quick", "explanation": "笔顺规则是先横后竖，所以“十”先写横。"}, {"id": "low-chinese-b2-012", "band": "low", "answer": "b", "prompt": "“我”字的第一笔是什么？", "choices": [{"id": "a", "text": "竖"}, {"id": "b", "text": "撇"}, {"id": "c", "text": "横"}], "subject": "chinese", "difficulty": "deep", "explanation": "“我”字第一笔是撇。"}, {"id": "low-chinese-b2-013", "band": "low", "answer": "b", "prompt": "用“学”可以组成下面哪个词？", "choices": [{"id": "a", "text": "学跑"}, {"id": "b", "text": "学校"}, {"id": "c", "text": "学红"}], "subject": "chinese", "difficulty": "quick", "explanation": "“学校”是我们上学的地方，是常用词。"}, {"id": "low-chinese-b2-014", "band": "low", "answer": "b", "prompt": "“手”字能跟哪个字组成词？", "choices": [{"id": "a", "text": "手云"}, {"id": "b", "text": "手心"}, {"id": "c", "text": "手天"}], "subject": "chinese", "difficulty": "quick", "explanation": "“手心”指手掌中间的部分，是常用词。"}, {"id": "low-chinese-b2-015", "band": "low", "answer": "a", "prompt": "一（   ）红旗，填哪个量词最合适？", "choices": [{"id": "a", "text": "面"}, {"id": "b", "text": "条"}, {"id": "c", "text": "只"}], "subject": "chinese", "difficulty": "deep", "explanation": "红旗用量词“面”，说“一面红旗”。"}, {"id": "low-chinese-b2-016", "band": "low", "answer": "b", "prompt": "一（   ）河，填哪个量词最合适？", "choices": [{"id": "a", "text": "个"}, {"id": "b", "text": "条"}, {"id": "c", "text": "只"}], "subject": "chinese", "difficulty": "quick", "explanation": "长长的河用“条”，说“一条河”。"}, {"id": "low-chinese-b2-017", "band": "low", "answer": "b", "prompt": "一（   ）牛，填哪个量词最合适？", "choices": [{"id": "a", "text": "张"}, {"id": "b", "text": "头"}, {"id": "c", "text": "片"}], "subject": "chinese", "difficulty": "deep", "explanation": "牛用量词“头”，说“一头牛”。"}, {"id": "low-chinese-b2-018", "band": "low", "answer": "a", "prompt": "一（   ）船，填哪个量词最合适？", "choices": [{"id": "a", "text": "艘"}, {"id": "b", "text": "棵"}, {"id": "c", "text": "件"}], "subject": "chinese", "difficulty": "deep", "explanation": "船用量词“艘”，说“一艘船”。也可说“一条船”。"}, {"id": "low-chinese-b2-019", "band": "low", "answer": "b", "prompt": "“早”的反义词是什么？", "choices": [{"id": "a", "text": "快"}, {"id": "b", "text": "晚"}, {"id": "c", "text": "亮"}], "subject": "chinese", "difficulty": "quick", "explanation": "早和晚是反义词，比如“早上”和“晚上”。"}, {"id": "low-chinese-b2-020", "band": "low", "answer": "b", "prompt": "“新”的反义词是什么？", "choices": [{"id": "a", "text": "大"}, {"id": "b", "text": "旧"}, {"id": "c", "text": "美"}], "subject": "chinese", "difficulty": "quick", "explanation": "新和旧是反义词，比如“新书”和“旧书”。"}, {"id": "low-chinese-b2-021", "band": "low", "answer": "b", "prompt": "“进”的反义词是哪个？", "choices": [{"id": "a", "text": "走"}, {"id": "b", "text": "出"}, {"id": "c", "text": "来"}], "subject": "chinese", "difficulty": "deep", "explanation": "进和出是反义词，比如“进门”和“出门”。"}, {"id": "low-chinese-b2-022", "band": "low", "answer": "b", "prompt": "“胖”的反义词是哪个？", "choices": [{"id": "a", "text": "矮"}, {"id": "b", "text": "瘦"}, {"id": "c", "text": "高"}], "subject": "chinese", "difficulty": "quick", "explanation": "胖和瘦是反义词。"}, {"id": "low-chinese-b2-023", "band": "low", "answer": "c", "prompt": "“安静”的反义词是哪个？", "choices": [{"id": "a", "text": "漂亮"}, {"id": "b", "text": "干净"}, {"id": "c", "text": "吵闹"}], "subject": "chinese", "difficulty": "deep", "explanation": "安静和吵闹意思相反。"}, {"id": "low-chinese-b2-024", "band": "low", "answer": "c", "prompt": "“高兴”的近义词是哪个？", "choices": [{"id": "a", "text": "难过"}, {"id": "b", "text": "生气"}, {"id": "c", "text": "快乐"}], "subject": "chinese", "difficulty": "quick", "explanation": "高兴和快乐意思相近，都是开心的意思。"}, {"id": "low-chinese-b2-025", "band": "low", "answer": "a", "prompt": "古诗《静夜思》：“床前明月光，疑是____。”横线上是哪句？", "choices": [{"id": "a", "text": "地上霜"}, {"id": "b", "text": "天上云"}, {"id": "c", "text": "水中月"}], "subject": "chinese", "difficulty": "quick", "explanation": "原句是“疑是地上霜”，月光像地上的白霜。"}, {"id": "low-chinese-b2-026", "band": "low", "answer": "a", "prompt": "古诗《咏鹅》：“鹅，鹅，鹅，____向天歌。”横线上填哪个？", "choices": [{"id": "a", "text": "曲项"}, {"id": "b", "text": "红掌"}, {"id": "c", "text": "白毛"}], "subject": "chinese", "difficulty": "deep", "explanation": "原句是“曲项向天歌”，“曲项”指弯弯的脖子。"}, {"id": "low-chinese-b2-027", "band": "low", "answer": "a", "prompt": "古诗《春晓》：“春眠不觉晓，处处闻____。”横线上填哪个？", "choices": [{"id": "a", "text": "啼鸟"}, {"id": "b", "text": "流水"}, {"id": "c", "text": "花香"}], "subject": "chinese", "difficulty": "deep", "explanation": "原句是“处处闻啼鸟”，到处听见鸟叫声。"}, {"id": "low-chinese-b2-028", "band": "low", "answer": "b", "prompt": "句子末尾表示问话，应该用哪个标点？", "choices": [{"id": "a", "text": "逗号 ，"}, {"id": "b", "text": "问号 ？"}, {"id": "c", "text": "句号 。"}], "subject": "chinese", "difficulty": "quick", "explanation": "提问的句子末尾用问号“？”。"}, {"id": "low-chinese-b2-029", "band": "low", "answer": "a", "prompt": "“小明喊道：‘太好啦！’”这个句子里用了什么标点表示很激动？", "choices": [{"id": "a", "text": "感叹号 ！"}, {"id": "b", "text": "句号 。"}, {"id": "c", "text": "问号 ？"}], "subject": "chinese", "difficulty": "deep", "explanation": "表示激动、惊喜的语气用感叹号“！”。"}, {"id": "low-chinese-b2-030", "band": "low", "answer": "b", "prompt": "“鸟、鸡、鸭”这几个字都有什么偏旁，和什么有关？", "choices": [{"id": "a", "text": "“水”字旁，和水有关"}, {"id": "b", "text": "“鸟”字旁，都和鸟类有关"}, {"id": "c", "text": "“木”字旁，和树木有关"}], "subject": "chinese", "difficulty": "deep", "explanation": "它们都带“鸟”字旁，都是会飞或长羽毛的动物。"}, {"id": "high-chinese-b2-001", "band": "high", "answer": "c", "prompt": "成语“亡羊补牢”比喻的是什么？", "choices": [{"id": "a", "text": "做了多余而无用的事"}, {"id": "b", "text": "做事拖拖拉拉不肯动手"}, {"id": "c", "text": "出了问题后及时补救，还不算晚"}], "subject": "chinese", "difficulty": "quick", "explanation": "羊跑了再修羊圈，比喻出了差错及时补救，免得继续受损失。"}, {"id": "high-chinese-b2-002", "band": "high", "answer": "a", "prompt": "补全成语：“________，焉得虎子。”横线上应填哪个？", "choices": [{"id": "a", "text": "不入虎穴"}, {"id": "b", "text": "不见兔子"}, {"id": "c", "text": "不上高山"}], "subject": "chinese", "difficulty": "quick", "explanation": "“不入虎穴，焉得虎子”，比喻不冒险就难以取得成功。"}, {"id": "high-chinese-b2-003", "band": "high", "answer": "c", "prompt": "“瓜熟蒂落”里的“蒂”指的是什么？", "choices": [{"id": "a", "text": "瓜的皮"}, {"id": "b", "text": "瓜里的种子"}, {"id": "c", "text": "瓜和藤相连的那个把儿"}], "subject": "chinese", "difficulty": "deep", "explanation": "“蒂”是花、果跟枝茎相连的部分。瓜熟了蒂自然脱落，比喻条件成熟事情自然成功。"}, {"id": "high-chinese-b2-004", "band": "high", "answer": "a", "prompt": "“囫囵吞枣”形容的是哪种学习态度？", "choices": [{"id": "a", "text": "不加分析、笼统接受，不求理解"}, {"id": "b", "text": "读书认真、反复钻研"}, {"id": "c", "text": "边读边记笔记"}], "subject": "chinese", "difficulty": "deep", "explanation": "把枣整个吞下去不嚼，比喻读书学习只求笼统接受，不动脑筋去理解。"}, {"id": "high-chinese-b2-005", "band": "high", "answer": "c", "prompt": "下面哪一组是近义词？", "choices": [{"id": "a", "text": "喜欢——讨厌"}, {"id": "b", "text": "清楚——模糊"}, {"id": "c", "text": "立刻——马上"}], "subject": "chinese", "difficulty": "quick", "explanation": "“立刻”和“马上”都表示时间很短、立即，是近义词；另两组是反义词。"}, {"id": "high-chinese-b2-006", "band": "high", "answer": "a", "prompt": "“慷慨”的反义词是哪个？", "choices": [{"id": "a", "text": "吝啬"}, {"id": "b", "text": "热情"}, {"id": "c", "text": "大方"}], "subject": "chinese", "difficulty": "deep", "explanation": "“慷慨”指大方、不吝惜，反义词是“吝啬”（小气）。"}, {"id": "high-chinese-b2-007", "band": "high", "answer": "a", "prompt": "杜甫《绝句》：“两个黄鹂鸣翠柳，____。”下一句是？", "choices": [{"id": "a", "text": "一行白鹭上青天"}, {"id": "b", "text": "霜叶红于二月花"}, {"id": "c", "text": "映日荷花别样红"}], "subject": "chinese", "difficulty": "quick", "explanation": "出自杜甫《绝句》，下一句是“一行白鹭上青天”。"}, {"id": "high-chinese-b2-008", "band": "high", "answer": "b", "prompt": "李白《赠汪伦》：“桃花潭水深千尺，____。”下一句是？", "choices": [{"id": "a", "text": "唯见长江天际流"}, {"id": "b", "text": "不及汪伦送我情"}, {"id": "c", "text": "轻舟已过万重山"}], "subject": "chinese", "difficulty": "deep", "explanation": "出自李白《赠汪伦》，用潭水之深反衬友情之深。"}, {"id": "high-chinese-b2-009", "band": "high", "answer": "b", "prompt": "杜甫《春夜喜雨》：“好雨知时节，____。”下一句是？", "choices": [{"id": "a", "text": "花重锦官城"}, {"id": "b", "text": "当春乃发生"}, {"id": "c", "text": "润物细无声"}], "subject": "chinese", "difficulty": "deep", "explanation": "出自杜甫《春夜喜雨》，紧接的是“当春乃发生”。“润物细无声”是后面的句子。"}, {"id": "high-chinese-b2-010", "band": "high", "answer": "c", "prompt": "“儿童急走追黄蝶”里的“走”，是什么意思？", "choices": [{"id": "a", "text": "散步"}, {"id": "b", "text": "离开"}, {"id": "c", "text": "跑"}], "subject": "chinese", "difficulty": "deep", "explanation": "文言里“走”常指“跑”，如“急走”就是急忙地跑。"}, {"id": "high-chinese-b2-011", "band": "high", "answer": "b", "prompt": "文言文里“吾”一般是什么意思？", "choices": [{"id": "a", "text": "他"}, {"id": "b", "text": "我"}, {"id": "c", "text": "你"}], "subject": "chinese", "difficulty": "quick", "explanation": "“吾”是文言中第一人称代词，意思是“我”。"}, {"id": "high-chinese-b2-012", "band": "high", "answer": "a", "prompt": "“开卷有益”这个成语鼓励我们做什么？", "choices": [{"id": "a", "text": "多读书，读书总有好处"}, {"id": "b", "text": "把书卷起来收好"}, {"id": "c", "text": "考试时偷看书"}], "subject": "chinese", "difficulty": "quick", "explanation": "“卷”指书，“开卷有益”意思是打开书读就有收获，鼓励多读书。"}, {"id": "high-chinese-b2-013", "band": "high", "answer": "a", "prompt": "《守株待兔》里“兔走触株，折颈而死”的“走”是什么意思？", "choices": [{"id": "a", "text": "奔跑"}, {"id": "b", "text": "行走"}, {"id": "c", "text": "逃走"}], "subject": "chinese", "difficulty": "deep", "explanation": "古文中“走”指“跑”。兔子奔跑撞到树桩，折断脖子死了。"}, {"id": "high-chinese-b2-014", "band": "high", "answer": "c", "prompt": "下面哪句话有语病？", "choices": [{"id": "a", "text": "这次活动让我懂得了团结的力量。"}, {"id": "b", "text": "经过这次活动，我懂得了团结的力量。"}, {"id": "c", "text": "通过这次活动，使我懂得了团结的力量。"}], "subject": "chinese", "difficulty": "deep", "explanation": "A句“通过……使……”同时用，缺少主语。去掉“通过”或“使”才通顺。"}, {"id": "high-chinese-b2-015", "band": "high", "answer": "b", "prompt": "下面三句话中，只有一句没有语病，是哪一句？", "choices": [{"id": "a", "text": "我们要防止类似事故不再发生。"}, {"id": "b", "text": "我们要养成讲文明、懂礼貌的好习惯。"}, {"id": "c", "text": "他大约有十岁左右。"}], "subject": "chinese", "difficulty": "deep", "explanation": "B“防止……不再”否定重复；C“大约”和“左右”意思重复。A句正确。"}, {"id": "high-chinese-b2-016", "band": "high", "answer": "c", "prompt": "“他刻苦学习，____取得了好成绩。”填哪组关联词最合适？", "choices": [{"id": "a", "text": "如果"}, {"id": "b", "text": "虽然"}, {"id": "c", "text": "因此"}], "subject": "chinese", "difficulty": "quick", "explanation": "前句是原因、后句是结果，用表因果的“因此”。"}, {"id": "high-chinese-b2-017", "band": "high", "answer": "c", "prompt": "“____明天下雨，运动会____改期。”填哪组关联词？", "choices": [{"id": "a", "text": "因为……所以……"}, {"id": "b", "text": "虽然……但是……"}, {"id": "c", "text": "如果……就……"}], "subject": "chinese", "difficulty": "deep", "explanation": "这是假设关系，用“如果……就……”。"}, {"id": "high-chinese-b2-018", "band": "high", "answer": "c", "prompt": "“弯弯的月亮像一只小船。”这句话用了什么修辞手法？", "choices": [{"id": "a", "text": "夸张"}, {"id": "b", "text": "拟人"}, {"id": "c", "text": "比喻"}], "subject": "chinese", "difficulty": "quick", "explanation": "把月亮比作小船，用“像”连接，是比喻。"}, {"id": "high-chinese-b2-019", "band": "high", "answer": "b", "prompt": "“春风一吹，小草偷偷地探出了头。”这句话用了什么修辞？", "choices": [{"id": "a", "text": "夸张"}, {"id": "b", "text": "拟人"}, {"id": "c", "text": "比喻"}], "subject": "chinese", "difficulty": "deep", "explanation": "“偷偷地探出头”是人的动作，赋予小草人的情态，是拟人。"}, {"id": "high-chinese-b2-020", "band": "high", "answer": "a", "prompt": "“他急得头上都要冒烟了。”这句话用了什么修辞？", "choices": [{"id": "a", "text": "夸张"}, {"id": "b", "text": "排比"}, {"id": "c", "text": "比喻"}], "subject": "chinese", "difficulty": "deep", "explanation": "人着急头上不会真冒烟，这是故意夸大，属于夸张。"}, {"id": "high-chinese-b2-021", "band": "high", "answer": "a", "prompt": "下面哪个词是褒义词（带赞美、肯定的感情色彩）？", "choices": [{"id": "a", "text": "果断"}, {"id": "b", "text": "专横"}, {"id": "c", "text": "武断"}], "subject": "chinese", "difficulty": "deep", "explanation": "“果断”是褒义，赞扬人有决断；“武断”“专横”是贬义。"}, {"id": "high-chinese-b2-022", "band": "high", "answer": "a", "prompt": "下面哪个词带有贬义（含批评、否定色彩）？", "choices": [{"id": "a", "text": "骄傲自满"}, {"id": "b", "text": "勤奋好学"}, {"id": "c", "text": "谦虚谨慎"}], "subject": "chinese", "difficulty": "quick", "explanation": "“骄傲自满”含批评意味，是贬义；另两个是褒义。"}, {"id": "high-chinese-b2-023", "band": "high", "answer": "c", "prompt": "成语“雪中送炭”和“锦上添花”相比，前者更强调什么？", "choices": [{"id": "a", "text": "做了多余的事"}, {"id": "b", "text": "在好的基础上更添光彩"}, {"id": "c", "text": "在别人困难时给予帮助"}], "subject": "chinese", "difficulty": "deep", "explanation": "“雪中送炭”指在别人急需时伸出援手；“锦上添花”是好上加好。"}, {"id": "high-chinese-b2-024", "band": "high", "answer": "c", "prompt": "“一年之计在于春，____。”补全这句谚语。", "choices": [{"id": "a", "text": "一寸光阴一寸金"}, {"id": "b", "text": "百年树人"}, {"id": "c", "text": "一日之计在于晨"}], "subject": "chinese", "difficulty": "deep", "explanation": "完整谚语是“一年之计在于春，一日之计在于晨”，强调及早安排。"}, {"id": "high-chinese-b2-025", "band": "high", "answer": "b", "prompt": "“危楼高百尺，手可摘星辰”中的“危”是什么意思？", "choices": [{"id": "a", "text": "危险"}, {"id": "b", "text": "高"}, {"id": "c", "text": "歪斜"}], "subject": "chinese", "difficulty": "deep", "explanation": "古文中“危”常指“高”，“危楼”即高楼，并非危险。"}, {"id": "high-chinese-b2-026", "band": "high", "answer": "b", "prompt": "“多”是多音字。在“多么美丽”里，“多”更接近下面哪个意思？", "choices": [{"id": "a", "text": "表示数量很多"}, {"id": "b", "text": "表示程度，相当于“非常”"}, {"id": "c", "text": "表示多余"}], "subject": "chinese", "difficulty": "deep", "explanation": "“多么美丽”里的“多”表示程度之深，相当于“多么、非常”。"}, {"id": "high-chinese-b2-027", "band": "high", "answer": "c", "prompt": "成语“再接再厉”中容易写错的“厉”，下面哪种写法才是对的？", "choices": [{"id": "a", "text": "再接再历"}, {"id": "b", "text": "再接再励"}, {"id": "c", "text": "再接再厉"}], "subject": "chinese", "difficulty": "deep", "explanation": "正确写法是“再接再厉”，“厉”本指磨快、振奋，不是“励”或“历”。"}, {"id": "high-chinese-b2-028", "band": "high", "answer": "a", "prompt": "阅读常识：写一篇记事文章，通常要交代清楚的“六要素”里不包括下面哪个？", "choices": [{"id": "a", "text": "文章用了几个成语"}, {"id": "b", "text": "事情的起因、经过和结果"}, {"id": "c", "text": "时间和地点"}], "subject": "chinese", "difficulty": "deep", "explanation": "记叙文六要素是时间、地点、人物、起因、经过、结果，与用了几个成语无关。"}, {"id": "high-chinese-b2-029", "band": "high", "answer": "c", "prompt": "“他这次考试名落孙山。”“名落孙山”的意思是？", "choices": [{"id": "a", "text": "考了第一名"}, {"id": "b", "text": "刚好压线考上"}, {"id": "c", "text": "考试没有考中、落榜"}], "subject": "chinese", "difficulty": "deep", "explanation": "“名落孙山”指考试未被录取、落榜，含委婉的意味。"}, {"id": "high-chinese-b2-030", "band": "high", "answer": "c", "prompt": "成语“专心致志”形容一个人怎么样？", "choices": [{"id": "a", "text": "东张西望、心不在焉"}, {"id": "b", "text": "一边玩一边学"}, {"id": "c", "text": "一心一意、注意力非常集中"}], "subject": "chinese", "difficulty": "quick", "explanation": "“致志”就是把心思都用上，形容一心一意、精神高度集中。"}, {"id": "low-english-b2-001", "band": "low", "answer": "a", "prompt": "字母 D 后面是哪个字母？", "choices": [{"id": "a", "text": "E"}, {"id": "b", "text": "C"}, {"id": "c", "text": "F"}], "subject": "english", "difficulty": "quick", "explanation": "字母表顺序是 A B C D E，D 后面是 E。"}, {"id": "low-english-b2-002", "band": "low", "answer": "a", "prompt": "“橙子/橘子”用英语怎么说？", "choices": [{"id": "a", "text": "orange"}, {"id": "b", "text": "apple"}, {"id": "c", "text": "grape"}], "subject": "english", "difficulty": "quick", "explanation": "orange 是橙子，apple 是苹果，grape 是葡萄。"}, {"id": "low-english-b2-003", "band": "low", "answer": "a", "prompt": "数字“4”用英语怎么说？", "choices": [{"id": "a", "text": "four"}, {"id": "b", "text": "five"}, {"id": "c", "text": "three"}], "subject": "english", "difficulty": "quick", "explanation": "4 是 four，5 是 five，3 是 three。"}, {"id": "low-english-b2-004", "band": "low", "answer": "c", "prompt": "“猪”用英语怎么说？", "choices": [{"id": "a", "text": "cat"}, {"id": "b", "text": "duck"}, {"id": "c", "text": "pig"}], "subject": "english", "difficulty": "quick", "explanation": "pig 是猪，cat 是猫，duck 是鸭。"}, {"id": "low-english-b2-005", "band": "low", "answer": "b", "prompt": "晚上睡觉前对家人说哪句最合适？", "choices": [{"id": "a", "text": "Hello"}, {"id": "b", "text": "Good night"}, {"id": "c", "text": "Good morning"}], "subject": "english", "difficulty": "quick", "explanation": "Good night 是晚安，Good morning 是早上好。"}, {"id": "low-english-b2-006", "band": "low", "answer": "b", "prompt": "“book”是什么意思？", "choices": [{"id": "a", "text": "包"}, {"id": "b", "text": "书"}, {"id": "c", "text": "笔"}], "subject": "english", "difficulty": "quick", "explanation": "book 是书本，pen 是笔，bag 是包。"}, {"id": "low-english-b2-007", "band": "low", "answer": "b", "prompt": "数字“6”用英语怎么说？", "choices": [{"id": "a", "text": "eight"}, {"id": "b", "text": "six"}, {"id": "c", "text": "seven"}], "subject": "english", "difficulty": "quick", "explanation": "6 是 six，7 是 seven，8 是 eight。"}, {"id": "low-english-b2-008", "band": "low", "answer": "a", "prompt": "粉红色用英语怎么说？", "choices": [{"id": "a", "text": "pink"}, {"id": "b", "text": "green"}, {"id": "c", "text": "blue"}], "subject": "english", "difficulty": "quick", "explanation": "pink 是粉红色，blue 是蓝色，green 是绿色。"}, {"id": "low-english-b2-009", "band": "low", "answer": "b", "prompt": "“鸭子”用英语怎么说？", "choices": [{"id": "a", "text": "bird"}, {"id": "b", "text": "duck"}, {"id": "c", "text": "dog"}], "subject": "english", "difficulty": "quick", "explanation": "duck 是鸭子，dog 是狗，bird 是鸟。"}, {"id": "low-english-b2-010", "band": "low", "answer": "a", "prompt": "字母 E 前面是哪个字母？", "choices": [{"id": "a", "text": "D"}, {"id": "b", "text": "G"}, {"id": "c", "text": "F"}], "subject": "english", "difficulty": "quick", "explanation": "字母表顺序 C D E F，E 前面是 D。"}, {"id": "low-english-b2-011", "band": "low", "answer": "b", "prompt": "“tree”是什么意思？", "choices": [{"id": "a", "text": "草"}, {"id": "b", "text": "树"}, {"id": "c", "text": "花"}], "subject": "english", "difficulty": "quick", "explanation": "tree 是树，flower 是花，grass 是草。"}, {"id": "low-english-b2-012", "band": "low", "answer": "a", "prompt": "数字“7”用英语怎么说？", "choices": [{"id": "a", "text": "seven"}, {"id": "b", "text": "nine"}, {"id": "c", "text": "six"}], "subject": "english", "difficulty": "quick", "explanation": "7 是 seven，6 是 six，9 是 nine。"}, {"id": "low-english-b2-013", "band": "low", "answer": "c", "prompt": "“手”用英语怎么说？（拍手的部位）", "choices": [{"id": "a", "text": "foot"}, {"id": "b", "text": "head"}, {"id": "c", "text": "hand"}], "subject": "english", "difficulty": "quick", "explanation": "hand 是手，foot 是脚，head 是头。"}, {"id": "low-english-b2-014", "band": "low", "answer": "c", "prompt": "早上见到老师说哪句最好？", "choices": [{"id": "a", "text": "Good night"}, {"id": "b", "text": "Goodbye"}, {"id": "c", "text": "Good morning"}], "subject": "english", "difficulty": "quick", "explanation": "Good morning 是早上好，Good night 是晚安。"}, {"id": "low-english-b2-015", "band": "low", "answer": "c", "prompt": "“milk”是什么？", "choices": [{"id": "a", "text": "果汁"}, {"id": "b", "text": "水"}, {"id": "c", "text": "牛奶"}], "subject": "english", "difficulty": "quick", "explanation": "milk 是牛奶，water 是水，juice 是果汁。"}, {"id": "low-english-b2-016", "band": "low", "answer": "a", "prompt": "棕色（小熊的颜色）用英语怎么说？", "choices": [{"id": "a", "text": "brown"}, {"id": "b", "text": "black"}, {"id": "c", "text": "white"}], "subject": "english", "difficulty": "quick", "explanation": "brown 是棕色，black 是黑色，white 是白色。"}, {"id": "low-english-b2-017", "band": "low", "answer": "c", "prompt": "“rabbit”是什么动物？", "choices": [{"id": "a", "text": "老虎"}, {"id": "b", "text": "猴子"}, {"id": "c", "text": "兔子"}], "subject": "english", "difficulty": "quick", "explanation": "rabbit 是兔子，tiger 是老虎，monkey 是猴子。"}, {"id": "low-english-b2-018", "band": "low", "answer": "b", "prompt": "数字“8”用英语怎么说？", "choices": [{"id": "a", "text": "nine"}, {"id": "b", "text": "eight"}, {"id": "c", "text": "ten"}], "subject": "english", "difficulty": "deep", "explanation": "8 是 eight，9 是 nine，10 是 ten。"}, {"id": "low-english-b2-019", "band": "low", "answer": "a", "prompt": "“nose”是身体的哪个部位？", "choices": [{"id": "a", "text": "鼻子"}, {"id": "b", "text": "眼睛"}, {"id": "c", "text": "耳朵"}], "subject": "english", "difficulty": "quick", "explanation": "nose 是鼻子，ear 是耳朵，eye 是眼睛。"}, {"id": "low-english-b2-020", "band": "low", "answer": "c", "prompt": "和别人说“再见”用英语说哪个？", "choices": [{"id": "a", "text": "Sorry"}, {"id": "b", "text": "Hello"}, {"id": "c", "text": "Goodbye"}], "subject": "english", "difficulty": "quick", "explanation": "Goodbye 是再见，Hello 是你好，Sorry 是对不起。"}, {"id": "low-english-b2-021", "band": "low", "answer": "c", "prompt": "“egg”是什么？", "choices": [{"id": "a", "text": "米饭"}, {"id": "b", "text": "面包"}, {"id": "c", "text": "鸡蛋"}], "subject": "english", "difficulty": "quick", "explanation": "egg 是鸡蛋，bread 是面包，rice 是米饭。"}, {"id": "low-english-b2-022", "band": "low", "answer": "a", "prompt": "数字“10”用英语怎么说？", "choices": [{"id": "a", "text": "ten"}, {"id": "b", "text": "two"}, {"id": "c", "text": "nine"}], "subject": "english", "difficulty": "quick", "explanation": "10 是 ten，2 是 two，9 是 nine。"}, {"id": "low-english-b2-023", "band": "low", "answer": "a", "prompt": "“flower”是什么意思？", "choices": [{"id": "a", "text": "花"}, {"id": "b", "text": "树"}, {"id": "c", "text": "鸟"}], "subject": "english", "difficulty": "quick", "explanation": "flower 是花，tree 是树，bird 是鸟。"}, {"id": "low-english-b2-024", "band": "low", "answer": "a", "prompt": "橙色（像橘子的颜色）用英语怎么说？", "choices": [{"id": "a", "text": "orange"}, {"id": "b", "text": "pink"}, {"id": "c", "text": "purple"}], "subject": "english", "difficulty": "deep", "explanation": "orange 既是橙子也是橙色，purple 是紫色。"}, {"id": "low-english-b2-025", "band": "low", "answer": "a", "prompt": "“foot”是身体哪个部位？", "choices": [{"id": "a", "text": "脚"}, {"id": "b", "text": "手"}, {"id": "c", "text": "嘴"}], "subject": "english", "difficulty": "quick", "explanation": "foot 是脚，hand 是手，mouth 是嘴。"}, {"id": "high-english-b2-001", "band": "high", "answer": "a", "prompt": "一个 box（盒子）的复数怎么写？", "choices": [{"id": "a", "text": "boxes"}, {"id": "b", "text": "boxs"}, {"id": "c", "text": "box"}], "subject": "english", "difficulty": "deep", "explanation": "以 x 结尾的名词复数加 -es，写作 boxes。"}, {"id": "high-english-b2-002", "band": "high", "answer": "c", "prompt": "“They ___ playing in the park now.” 横线填哪个？", "choices": [{"id": "a", "text": "am"}, {"id": "b", "text": "is"}, {"id": "c", "text": "are"}], "subject": "english", "difficulty": "deep", "explanation": "主语 They 是复数，be 动词用 are。"}, {"id": "high-english-b2-003", "band": "high", "answer": "a", "prompt": "“usually”是什么意思？", "choices": [{"id": "a", "text": "通常、经常"}, {"id": "b", "text": "昨天"}, {"id": "c", "text": "从不"}], "subject": "english", "difficulty": "quick", "explanation": "usually 表示通常、经常，never 是从不。"}, {"id": "high-english-b2-004", "band": "high", "answer": "b", "prompt": "“eat”的过去式是哪个？", "choices": [{"id": "a", "text": "eats"}, {"id": "b", "text": "ate"}, {"id": "c", "text": "eated"}], "subject": "english", "difficulty": "deep", "explanation": "eat 是不规则动词，过去式是 ate。"}, {"id": "high-english-b2-005", "band": "high", "answer": "a", "prompt": "“因为”（because）下面哪个拼写是对的？", "choices": [{"id": "a", "text": "because"}, {"id": "b", "text": "becouse"}, {"id": "c", "text": "becuase"}], "subject": "english", "difficulty": "deep", "explanation": "正确拼写是 because。"}, {"id": "high-english-b2-006", "band": "high", "answer": "a", "prompt": "“small”的反义词是哪个？", "choices": [{"id": "a", "text": "big"}, {"id": "b", "text": "slow"}, {"id": "c", "text": "short"}], "subject": "english", "difficulty": "quick", "explanation": "small（小）的反义词是 big（大）。"}, {"id": "high-english-b2-007", "band": "high", "answer": "c", "prompt": "一个 child（小孩）的复数怎么写？", "choices": [{"id": "a", "text": "childes"}, {"id": "b", "text": "childs"}, {"id": "c", "text": "children"}], "subject": "english", "difficulty": "deep", "explanation": "child 的复数是不规则形式 children。"}, {"id": "high-english-b2-008", "band": "high", "answer": "a", "prompt": "“We ___ to the zoo yesterday.” 填哪个？", "choices": [{"id": "a", "text": "went"}, {"id": "b", "text": "goes"}, {"id": "c", "text": "go"}], "subject": "english", "difficulty": "deep", "explanation": "yesterday 表示过去，go 的过去式是 went。"}, {"id": "high-english-b2-009", "band": "high", "answer": "c", "prompt": "“December”是几月？", "choices": [{"id": "a", "text": "九月"}, {"id": "b", "text": "十月"}, {"id": "c", "text": "十二月"}], "subject": "english", "difficulty": "quick", "explanation": "December 是十二月，October 是十月。"}, {"id": "high-english-b2-010", "band": "high", "answer": "a", "prompt": "“vegetable”是什么意思？", "choices": [{"id": "a", "text": "蔬菜"}, {"id": "b", "text": "水果"}, {"id": "c", "text": "肉"}], "subject": "english", "difficulty": "quick", "explanation": "vegetable 是蔬菜，fruit 是水果，meat 是肉。"}, {"id": "high-english-b2-011", "band": "high", "answer": "c", "prompt": "“This pencil is ___ than that one.” 填哪个（更长）？", "choices": [{"id": "a", "text": "longest"}, {"id": "b", "text": "long"}, {"id": "c", "text": "longer"}], "subject": "english", "difficulty": "deep", "explanation": "两者比较用比较级 longer。"}, {"id": "high-english-b2-012", "band": "high", "answer": "c", "prompt": "“He ___ like coffee.” 填哪个（否定）？", "choices": [{"id": "a", "text": "don't"}, {"id": "b", "text": "isn't"}, {"id": "c", "text": "doesn't"}], "subject": "english", "difficulty": "deep", "explanation": "He 是第三人称单数，否定用 doesn't。"}, {"id": "high-english-b2-013", "band": "high", "answer": "a", "prompt": "想表达“我有一些朋友”，下面哪句对？", "choices": [{"id": "a", "text": "I have some friends."}, {"id": "b", "text": "I has some friend."}, {"id": "c", "text": "I have a friends."}], "subject": "english", "difficulty": "deep", "explanation": "some 修饰复数 friends，主语 I 用 have。"}, {"id": "high-english-b2-014", "band": "high", "answer": "c", "prompt": "“dangerous”是什么意思？", "choices": [{"id": "a", "text": "美丽的"}, {"id": "b", "text": "安全的"}, {"id": "c", "text": "危险的"}], "subject": "english", "difficulty": "quick", "explanation": "dangerous 是危险的，safe 是安全的。"}, {"id": "high-english-b2-015", "band": "high", "answer": "a", "prompt": "一个 woman（女人）的复数怎么写？", "choices": [{"id": "a", "text": "women"}, {"id": "b", "text": "womens"}, {"id": "c", "text": "womans"}], "subject": "english", "difficulty": "deep", "explanation": "woman 的复数是不规则形式 women。"}, {"id": "high-english-b2-016", "band": "high", "answer": "b", "prompt": "“What time is it?”问的是什么？", "choices": [{"id": "a", "text": "今天星期几"}, {"id": "b", "text": "现在几点"}, {"id": "c", "text": "什么天气"}], "subject": "english", "difficulty": "quick", "explanation": "What time is it 是问现在几点了。"}, {"id": "high-english-b2-017", "band": "high", "answer": "a", "prompt": "“Look! The baby ___ now.” 填哪个（正在睡）？", "choices": [{"id": "a", "text": "is sleeping"}, {"id": "b", "text": "sleep"}, {"id": "c", "text": "sleeps"}], "subject": "english", "difficulty": "deep", "explanation": "Look 和 now 表示现在进行，用 is sleeping。"}, {"id": "high-english-b2-018", "band": "high", "answer": "a", "prompt": "中译英“一本有趣的书”，下面哪个对？", "choices": [{"id": "a", "text": "an interesting book"}, {"id": "b", "text": "a interesting book"}, {"id": "c", "text": "an interest book"}], "subject": "english", "difficulty": "deep", "explanation": "interesting 以元音开头，前面用 an；interesting 才是“有趣的”。"}, {"id": "high-english-b2-019", "band": "high", "answer": "c", "prompt": "“heavy”的反义词是哪个？", "choices": [{"id": "a", "text": "hard"}, {"id": "b", "text": "high"}, {"id": "c", "text": "light"}], "subject": "english", "difficulty": "quick", "explanation": "heavy（重）的反义词是 light（轻）。"}, {"id": "high-english-b2-020", "band": "high", "answer": "b", "prompt": "“Friday”是星期几？", "choices": [{"id": "a", "text": "星期四"}, {"id": "b", "text": "星期五"}, {"id": "c", "text": "星期六"}], "subject": "english", "difficulty": "quick", "explanation": "Friday 是星期五，Thursday 是星期四。"}, {"id": "high-english-b2-021", "band": "high", "answer": "a", "prompt": "“There ___ a book and two pens on the desk.” 填哪个？", "choices": [{"id": "a", "text": "is"}, {"id": "b", "text": "am"}, {"id": "c", "text": "are"}], "subject": "english", "difficulty": "deep", "explanation": "there be 句型就近原则，靠近的 a book 是单数，用 is。"}, {"id": "high-english-b2-022", "band": "high", "answer": "a", "prompt": "“play”加 ing 怎么写？", "choices": [{"id": "a", "text": "playing"}, {"id": "b", "text": "plaing"}, {"id": "c", "text": "playying"}], "subject": "english", "difficulty": "deep", "explanation": "play 以元音字母 y 结尾，直接加 ing，写作 playing。"}, {"id": "high-english-b2-023", "band": "high", "answer": "b", "prompt": "“quickly”是什么意思？", "choices": [{"id": "a", "text": "安静地"}, {"id": "b", "text": "快地、迅速地"}, {"id": "c", "text": "小心地"}], "subject": "english", "difficulty": "quick", "explanation": "quickly 是快地，quietly 是安静地，carefully 是小心地。"}, {"id": "high-english-b2-024", "band": "high", "answer": "c", "prompt": "“These are my ___.” 填哪个（书的复数）？", "choices": [{"id": "a", "text": "book"}, {"id": "b", "text": "bookes"}, {"id": "c", "text": "books"}], "subject": "english", "difficulty": "quick", "explanation": "These 是复数，book 的复数加 s 是 books。"}, {"id": "high-english-b2-025", "band": "high", "answer": "c", "prompt": "想约朋友“放学后一起踢球”，哪句最自然？", "choices": [{"id": "a", "text": "Let we play football after school."}, {"id": "b", "text": "Let's playing football after school."}, {"id": "c", "text": "Let's play football after school."}], "subject": "english", "difficulty": "deep", "explanation": "Let's 后接动词原形，正确说法是 Let's play football。"}, {"id": "low-science-b2-001", "band": "low", "answer": "b", "prompt": "小鸟的身体上长满了什么，帮它保暖又能飞？", "choices": [{"id": "a", "text": "毛皮"}, {"id": "b", "text": "羽毛"}, {"id": "c", "text": "鱼鳞"}], "subject": "science", "difficulty": "quick", "explanation": "小鸟身上长羽毛，又轻又暖还能帮助飞翔。"}, {"id": "low-science-b2-002", "band": "low", "answer": "b", "prompt": "我们用身体的哪个部位来尝出甜和酸？", "choices": [{"id": "a", "text": "耳朵"}, {"id": "b", "text": "舌头"}, {"id": "c", "text": "鼻子"}], "subject": "science", "difficulty": "quick", "explanation": "舌头上有味觉，能尝出酸甜苦辣。"}, {"id": "low-science-b2-003", "band": "low", "answer": "c", "prompt": "夏天的中午，太阳照在身上感觉怎么样？", "choices": [{"id": "a", "text": "会下雪"}, {"id": "b", "text": "很冷"}, {"id": "c", "text": "很热"}], "subject": "science", "difficulty": "quick", "explanation": "夏天太阳很强，照在身上暖暖的、很热。"}, {"id": "low-science-b2-004", "band": "low", "answer": "a", "prompt": "下面哪种动物会在水里游泳，还会在岸上跳？", "choices": [{"id": "a", "text": "青蛙"}, {"id": "b", "text": "小鸟"}, {"id": "c", "text": "蝴蝶"}], "subject": "science", "difficulty": "quick", "explanation": "青蛙既能在水里游，又能在岸上跳。"}, {"id": "low-science-b2-005", "band": "low", "answer": "c", "prompt": "我们的眼睛累了，应该怎么做对眼睛好？", "choices": [{"id": "a", "text": "盯着太阳看"}, {"id": "b", "text": "用力揉很久"}, {"id": "c", "text": "闭上休息一会儿"}], "subject": "science", "difficulty": "quick", "explanation": "眼睛累了要闭眼休息，不能盯太阳看，也不要使劲揉。"}, {"id": "low-science-b2-006", "band": "low", "answer": "a", "prompt": "种小花的种子，最先需要把种子种在哪里？", "choices": [{"id": "a", "text": "泥土里"}, {"id": "b", "text": "水盆里漂着"}, {"id": "c", "text": "石头上"}], "subject": "science", "difficulty": "quick", "explanation": "种子要种在泥土里，才能扎根发芽。"}, {"id": "low-science-b2-007", "band": "low", "answer": "a", "prompt": "刮风的时候，我们看不见风，但能怎么知道有风？", "choices": [{"id": "a", "text": "看到树叶在动"}, {"id": "b", "text": "用手抓住风"}, {"id": "c", "text": "闻到风的味道"}], "subject": "science", "difficulty": "deep", "explanation": "风看不见，但树叶飘动、旗子飞扬就说明有风。"}, {"id": "low-science-b2-008", "band": "low", "answer": "b", "prompt": "一年里最热的是哪个季节？", "choices": [{"id": "a", "text": "春天"}, {"id": "b", "text": "夏天"}, {"id": "c", "text": "冬天"}], "subject": "science", "difficulty": "quick", "explanation": "一年四季里夏天最热，冬天最冷。"}, {"id": "low-science-b2-009", "band": "low", "answer": "a", "prompt": "小蜜蜂、小蝴蝶飞到花上，对花有什么好处？", "choices": [{"id": "a", "text": "帮花传播花粉"}, {"id": "b", "text": "把花吃掉"}, {"id": "c", "text": "把花踩坏"}], "subject": "science", "difficulty": "deep", "explanation": "蜜蜂蝴蝶采蜜时帮花传播花粉，花才能结果。"}, {"id": "low-science-b2-010", "band": "low", "answer": "c", "prompt": "白天能看见太阳，那晚上天上常能看见什么？", "choices": [{"id": "a", "text": "太阳"}, {"id": "b", "text": "彩虹"}, {"id": "c", "text": "月亮和星星"}], "subject": "science", "difficulty": "quick", "explanation": "晚上天黑了，天上常能看到月亮和星星。"}, {"id": "low-science-b2-011", "band": "low", "answer": "c", "prompt": "水结成了冰，再放到很热的地方，冰会怎么样？", "choices": [{"id": "a", "text": "变得更硬"}, {"id": "b", "text": "变成石头"}, {"id": "c", "text": "化成水"}], "subject": "science", "difficulty": "quick", "explanation": "冰遇热会融化，重新变回水。"}, {"id": "low-science-b2-012", "band": "low", "answer": "a", "prompt": "我们饿了肚子咕咕叫，吃饱了感觉怎么样？", "choices": [{"id": "a", "text": "有力气、不饿了"}, {"id": "b", "text": "想睡一整天"}, {"id": "c", "text": "会变矮"}], "subject": "science", "difficulty": "quick", "explanation": "吃饭给身体能量，吃饱了就有力气活动。"}, {"id": "low-science-b2-013", "band": "low", "answer": "c", "prompt": "下面哪样是植物，会从土里长出来？", "choices": [{"id": "a", "text": "石头"}, {"id": "b", "text": "小狗"}, {"id": "c", "text": "小草"}], "subject": "science", "difficulty": "quick", "explanation": "小草是植物，会从土里长出来；小狗是动物，石头不是生物。"}, {"id": "low-science-b2-014", "band": "low", "answer": "b", "prompt": "天上下雪的时候，外面一般是什么季节？", "choices": [{"id": "a", "text": "秋天最热的时候"}, {"id": "b", "text": "冬天"}, {"id": "c", "text": "夏天"}], "subject": "science", "difficulty": "quick", "explanation": "天气很冷才会下雪，所以下雪一般在冬天。"}, {"id": "low-science-b2-015", "band": "low", "answer": "b", "prompt": "我们用耳朵来做什么？", "choices": [{"id": "a", "text": "看东西"}, {"id": "b", "text": "听声音"}, {"id": "c", "text": "闻味道"}], "subject": "science", "difficulty": "quick", "explanation": "耳朵是用来听声音的，眼睛看东西，鼻子闻味道。"}, {"id": "low-science-b2-016", "band": "low", "answer": "c", "prompt": "小猫、小狗身上软软暖暖的一层叫什么？", "choices": [{"id": "a", "text": "羽毛"}, {"id": "b", "text": "鳞片"}, {"id": "c", "text": "毛"}], "subject": "science", "difficulty": "deep", "explanation": "猫狗身上是毛，鸟身上是羽毛，鱼身上是鳞片。"}, {"id": "low-science-b2-017", "band": "low", "answer": "b", "prompt": "想让小花长得好，除了浇水，还很需要什么？", "choices": [{"id": "a", "text": "放在黑屋子里"}, {"id": "b", "text": "晒太阳"}, {"id": "c", "text": "天天摇晃它"}], "subject": "science", "difficulty": "deep", "explanation": "植物长大需要水、阳光和泥土，缺了阳光会长不好。"}, {"id": "low-science-b2-018", "band": "low", "answer": "c", "prompt": "早上太阳升起，天会怎么样？", "choices": [{"id": "a", "text": "下起雪"}, {"id": "b", "text": "越来越黑"}, {"id": "c", "text": "慢慢变亮"}], "subject": "science", "difficulty": "quick", "explanation": "太阳升起，天就从黑慢慢变亮，变成白天。"}, {"id": "low-science-b2-019", "band": "low", "answer": "b", "prompt": "下面哪种是会飞的小昆虫？", "choices": [{"id": "a", "text": "蜗牛"}, {"id": "b", "text": "蝴蝶"}, {"id": "c", "text": "金鱼"}], "subject": "science", "difficulty": "quick", "explanation": "蝴蝶会飞，蜗牛慢慢爬，金鱼在水里游。"}, {"id": "low-science-b2-020", "band": "low", "answer": "a", "prompt": "我们手很脏的时候，应该怎么做？", "choices": [{"id": "a", "text": "用肥皂和水洗手"}, {"id": "b", "text": "不管它"}, {"id": "c", "text": "在衣服上擦擦"}], "subject": "science", "difficulty": "quick", "explanation": "用肥皂和清水洗手，才能把脏东西和细菌洗掉。"}, {"id": "low-science-b2-021", "band": "low", "answer": "b", "prompt": "鱼一直生活在水里，它身上滑滑的覆盖着什么？", "choices": [{"id": "a", "text": "绒毛"}, {"id": "b", "text": "鱼鳞"}, {"id": "c", "text": "羽毛"}], "subject": "science", "difficulty": "quick", "explanation": "鱼身上是一片片的鱼鳞，又滑又能保护身体。"}, {"id": "low-science-b2-022", "band": "low", "answer": "c", "prompt": "我们用鼻子除了闻味道，还用来做什么？", "choices": [{"id": "a", "text": "听声音"}, {"id": "b", "text": "尝味道"}, {"id": "c", "text": "呼吸空气"}], "subject": "science", "difficulty": "deep", "explanation": "鼻子既能闻味道，也是我们呼吸空气的地方。"}, {"id": "low-science-b2-023", "band": "low", "answer": "c", "prompt": "下雨过后，天上有时会出现弯弯的、五颜六色的是什么？", "choices": [{"id": "a", "text": "雪花"}, {"id": "b", "text": "星星"}, {"id": "c", "text": "彩虹"}], "subject": "science", "difficulty": "quick", "explanation": "雨后阳光照在小水珠上，就会出现弯弯的彩虹。"}, {"id": "low-science-b2-024", "band": "low", "answer": "a", "prompt": "小朋友每天要好好睡觉，睡觉对身体有什么好处？", "choices": [{"id": "a", "text": "让身体休息、长得高"}, {"id": "b", "text": "什么用都没有"}, {"id": "c", "text": "让身体变小"}], "subject": "science", "difficulty": "deep", "explanation": "睡觉时身体在休息和生长，睡好了才有精神、长得高。"}, {"id": "low-science-b2-025", "band": "low", "answer": "c", "prompt": "秋天到了，许多大树的叶子会怎么样？", "choices": [{"id": "a", "text": "开出很多花"}, {"id": "b", "text": "变得更绿"}, {"id": "c", "text": "变黄掉落"}], "subject": "science", "difficulty": "quick", "explanation": "秋天天气变凉，很多树叶变黄、变红，然后落下来。"}, {"id": "high-science-b2-001", "band": "high", "answer": "a", "prompt": "植物进行光合作用，主要在身体的哪个部分进行？", "choices": [{"id": "a", "text": "叶子"}, {"id": "b", "text": "根"}, {"id": "c", "text": "花"}], "subject": "science", "difficulty": "deep", "explanation": "叶子里有叶绿体，是光合作用的主要场所；根主要吸水。"}, {"id": "high-science-b2-002", "band": "high", "answer": "a", "prompt": "人体里负责消化食物、吸收营养最主要的器官是哪个？", "choices": [{"id": "a", "text": "小肠"}, {"id": "b", "text": "肺"}, {"id": "c", "text": "心脏"}], "subject": "science", "difficulty": "deep", "explanation": "小肠是消化和吸收营养的主要场所，心脏管血液，肺管呼吸。"}, {"id": "high-science-b2-003", "band": "high", "answer": "c", "prompt": "鲸鱼、蝙蝠、鸽子里，哪一种不属于哺乳动物？", "choices": [{"id": "a", "text": "蝙蝠"}, {"id": "b", "text": "鲸鱼"}, {"id": "c", "text": "鸽子"}], "subject": "science", "difficulty": "deep", "explanation": "鸽子是鸟类；鲸鱼和蝙蝠虽然样子特别，却是哺乳动物，会喂奶。"}, {"id": "high-science-b2-004", "band": "high", "answer": "a", "prompt": "我们用手推门，门被推开了，这说明力可以改变物体的什么？", "choices": [{"id": "a", "text": "运动状态"}, {"id": "b", "text": "颜色"}, {"id": "c", "text": "气味"}], "subject": "science", "difficulty": "deep", "explanation": "力能让静止的物体动起来，改变物体的运动状态。"}, {"id": "high-science-b2-005", "band": "high", "answer": "b", "prompt": "把糖块放进热水里，糖不见了、水变甜，这个过程叫什么？", "choices": [{"id": "a", "text": "燃烧"}, {"id": "b", "text": "溶解"}, {"id": "c", "text": "凝固"}], "subject": "science", "difficulty": "quick", "explanation": "糖均匀分散到水里看不见，这叫溶解；热水能让糖溶解得更快。"}, {"id": "high-science-b2-006", "band": "high", "answer": "a", "prompt": "在太阳系里，我们居住的地球排在离太阳第几近？", "choices": [{"id": "a", "text": "第三颗"}, {"id": "b", "text": "第一颗"}, {"id": "c", "text": "第五颗"}], "subject": "science", "difficulty": "deep", "explanation": "从太阳数起是水星、金星、地球，地球排第三。"}, {"id": "high-science-b2-007", "band": "high", "answer": "c", "prompt": "晚上从黑暗的地方走进亮房间，瞳孔会怎么变化？", "choices": [{"id": "a", "text": "不变"}, {"id": "b", "text": "变大"}, {"id": "c", "text": "变小"}], "subject": "science", "difficulty": "deep", "explanation": "光线强时瞳孔缩小，减少进光量保护眼睛；光线暗时瞳孔放大。"}, {"id": "high-science-b2-008", "band": "high", "answer": "b", "prompt": "下面哪种做法是为了保护环境、减少污染？", "choices": [{"id": "a", "text": "长时间开着没人用的灯"}, {"id": "b", "text": "垃圾分类回收"}, {"id": "c", "text": "随手乱扔废电池"}], "subject": "science", "difficulty": "quick", "explanation": "垃圾分类回收能节约资源、减少污染；乱扔电池和浪费电都有害环境。"}, {"id": "high-science-b2-009", "band": "high", "answer": "b", "prompt": "把木块放进水里会浮起来，把铁钉放进去会下沉，这跟什么有关？", "choices": [{"id": "a", "text": "物体的颜色"}, {"id": "b", "text": "物体的密度（轻重和体积）"}, {"id": "c", "text": "水的多少"}], "subject": "science", "difficulty": "deep", "explanation": "比同体积水轻的物体会浮，比水重的会沉，这与密度有关。"}, {"id": "high-science-b2-010", "band": "high", "answer": "b", "prompt": "声音是怎么产生的？", "choices": [{"id": "a", "text": "物体发光产生的"}, {"id": "b", "text": "物体振动产生的"}, {"id": "c", "text": "物体变热产生的"}], "subject": "science", "difficulty": "deep", "explanation": "声音是由物体振动产生的，振动停止声音也停止。"}, {"id": "high-science-b2-011", "band": "high", "answer": "a", "prompt": "下面哪种是可再生能源？", "choices": [{"id": "a", "text": "太阳能"}, {"id": "b", "text": "煤"}, {"id": "c", "text": "石油"}], "subject": "science", "difficulty": "quick", "explanation": "太阳能用之不竭，是可再生能源；煤和石油用完就没了，是不可再生的。"}, {"id": "high-science-b2-012", "band": "high", "answer": "b", "prompt": "磁铁有两个磁极，同名磁极（如 N 对 N）靠近时会怎样？", "choices": [{"id": "a", "text": "互相吸引"}, {"id": "b", "text": "互相排斥"}, {"id": "c", "text": "没有反应"}], "subject": "science", "difficulty": "deep", "explanation": "磁铁同名磁极相斥，异名磁极相吸。"}, {"id": "high-science-b2-013", "band": "high", "answer": "b", "prompt": "夏天柏油马路上看起来有“水”，走近却没有，这其实是什么？", "choices": [{"id": "a", "text": "路面在流汗"}, {"id": "b", "text": "光的折射造成的错觉（海市蜃楼）"}, {"id": "c", "text": "真的有水"}], "subject": "science", "difficulty": "deep", "explanation": "热空气密度不均，光线折射形成像水的错觉，类似海市蜃楼。"}, {"id": "high-science-b2-014", "band": "high", "answer": "a", "prompt": "蜡烛燃烧时，下面哪种说法对？", "choices": [{"id": "a", "text": "燃烧需要氧气，盖上杯子火会灭"}, {"id": "b", "text": "盖上杯子火会越烧越旺"}, {"id": "c", "text": "燃烧不需要任何气体"}], "subject": "science", "difficulty": "deep", "explanation": "燃烧需要氧气，用杯子罩住蜡烛，氧气耗尽后火就熄灭。"}, {"id": "high-science-b2-015", "band": "high", "answer": "b", "prompt": "人体的呼吸系统中，进行气体交换、把氧气送进血液的器官是哪个？", "choices": [{"id": "a", "text": "胃"}, {"id": "b", "text": "肺"}, {"id": "c", "text": "肾"}], "subject": "science", "difficulty": "deep", "explanation": "肺是呼吸系统的核心，氧气在肺里进入血液，二氧化碳被排出。"}, {"id": "high-science-b2-016", "band": "high", "answer": "b", "prompt": "我们把电池、导线和小灯泡连成一圈，灯泡亮了，这一圈叫什么？", "choices": [{"id": "a", "text": "磁场"}, {"id": "b", "text": "电路（闭合回路）"}, {"id": "c", "text": "光圈"}], "subject": "science", "difficulty": "quick", "explanation": "电流要在闭合的电路里才能流动，灯泡才会亮。"}, {"id": "high-science-b2-017", "band": "high", "answer": "a", "prompt": "下面哪种动物属于昆虫？", "choices": [{"id": "a", "text": "蚂蚁"}, {"id": "b", "text": "蜘蛛"}, {"id": "c", "text": "蜈蚣"}], "subject": "science", "difficulty": "deep", "explanation": "昆虫身体分头、胸、腹三部分，有六条腿，蚂蚁是昆虫；蜘蛛有八条腿，不是昆虫。"}, {"id": "high-science-b2-018", "band": "high", "answer": "b", "prompt": "白天和黑夜交替出现，主要是因为地球在做什么？", "choices": [{"id": "a", "text": "绕太阳公转"}, {"id": "b", "text": "自转（绕自己的轴转）"}, {"id": "c", "text": "绕月亮转"}], "subject": "science", "difficulty": "deep", "explanation": "地球自转一圈约一天，朝向太阳的一面是白天，背面是黑夜。"}, {"id": "high-science-b2-019", "band": "high", "answer": "a", "prompt": "把两种颜色的橡皮泥揉在一起变成一种新颜色，这属于什么变化？", "choices": [{"id": "a", "text": "物理变化（没有产生新物质）"}, {"id": "b", "text": "化学变化"}, {"id": "c", "text": "燃烧"}], "subject": "science", "difficulty": "deep", "explanation": "只是混合在一起、没有生成新物质，属于物理变化。"}, {"id": "high-science-b2-020", "band": "high", "answer": "a", "prompt": "我们看到物体，是因为光怎么进入了眼睛？", "choices": [{"id": "a", "text": "物体反射的光进入眼睛"}, {"id": "b", "text": "物体自己钻进眼睛里"}, {"id": "c", "text": "眼睛发出光照到物体上"}], "subject": "science", "difficulty": "deep", "explanation": "大多数物体不发光，是它们反射的光进入眼睛，我们才看得见。"}, {"id": "high-science-b2-021", "band": "high", "answer": "a", "prompt": "水有固态、液态、气态三种状态，冬天的霜属于哪一态？", "choices": [{"id": "a", "text": "固态"}, {"id": "b", "text": "气态"}, {"id": "c", "text": "液态"}], "subject": "science", "difficulty": "deep", "explanation": "霜是水蒸气在冷物体表面直接凝结成的小冰晶，属于固态。"}, {"id": "high-science-b2-022", "band": "high", "answer": "b", "prompt": "下面哪条食物链的方向是对的？", "choices": [{"id": "a", "text": "兔子 → 草 → 老鹰"}, {"id": "b", "text": "草 → 兔子 → 老鹰"}, {"id": "c", "text": "老鹰 → 兔子 → 草"}], "subject": "science", "difficulty": "deep", "explanation": "食物链从被吃的指向吃它的：草被兔子吃，兔子被老鹰吃。"}, {"id": "high-science-b2-023", "band": "high", "answer": "b", "prompt": "把同样多的力压在面积更小的地方，产生的压强会怎样？", "choices": [{"id": "a", "text": "不变"}, {"id": "b", "text": "变大"}, {"id": "c", "text": "变小"}], "subject": "science", "difficulty": "deep", "explanation": "压力相同，受力面积越小压强越大，这就是图钉做得很尖的原因。"}, {"id": "high-science-b2-024", "band": "high", "answer": "b", "prompt": "植物的根除了固定植株，最主要的作用是什么？", "choices": [{"id": "a", "text": "开花结果"}, {"id": "b", "text": "从土里吸收水分和养分"}, {"id": "c", "text": "进行光合作用造氧气"}], "subject": "science", "difficulty": "deep", "explanation": "根负责吸收土壤里的水分和无机盐，光合作用主要在叶子里进行。"}, {"id": "high-science-b2-025", "band": "high", "answer": "b", "prompt": "下面哪种食物含有丰富的蛋白质，能帮我们长身体？", "choices": [{"id": "a", "text": "食用油"}, {"id": "b", "text": "鸡蛋"}, {"id": "c", "text": "白糖"}], "subject": "science", "difficulty": "quick", "explanation": "鸡蛋、瘦肉、牛奶富含蛋白质；白糖主要是糖类，油主要是脂肪。"}, {"id": "low-sports-b2-001", "band": "low", "answer": "b", "prompt": "上体育课时，听到老师吹哨子集合，小朋友应该怎么做？", "choices": [{"id": "a", "text": "继续自己玩不理会"}, {"id": "b", "text": "快步跑回队伍站好"}, {"id": "c", "text": "躲到一边藏起来"}], "subject": "sports", "difficulty": "quick", "explanation": "听到集合哨声要赶快归队站好，这样才安全又守纪律。"}, {"id": "low-sports-b2-002", "band": "low", "answer": "a", "prompt": "下面哪种球是圆圆的、可以用脚踢的？", "choices": [{"id": "a", "text": "足球"}, {"id": "b", "text": "橄榄球（尖尖的）"}, {"id": "c", "text": "羽毛球"}], "subject": "sports", "difficulty": "quick", "explanation": "足球是圆圆的，主要用脚踢，是小朋友常玩的球类。"}, {"id": "low-sports-b2-003", "band": "low", "answer": "a", "prompt": "小朋友学游泳，第一次下水最好怎么做？", "choices": [{"id": "a", "text": "在大人陪同下，在浅水区慢慢练习"}, {"id": "b", "text": "不用大人看着随便玩"}, {"id": "c", "text": "一个人偷偷跳进深水里"}], "subject": "sports", "difficulty": "deep", "explanation": "学游泳一定要有大人陪着，在浅水区练习才安全。"}, {"id": "low-sports-b2-004", "band": "low", "answer": "c", "prompt": "经常运动对我们的身体有什么好处？", "choices": [{"id": "a", "text": "对身体没有任何好处"}, {"id": "b", "text": "让我们变得很懒"}, {"id": "c", "text": "让身体更强壮、不容易生病"}], "subject": "sports", "difficulty": "quick", "explanation": "坚持运动能让身体更结实、更健康，少生病。"}, {"id": "low-sports-b2-005", "band": "low", "answer": "b", "prompt": "打乒乓球的时候，白色的小球叫什么？", "choices": [{"id": "a", "text": "皮球"}, {"id": "b", "text": "乒乓球"}, {"id": "c", "text": "铅球"}], "subject": "sports", "difficulty": "quick", "explanation": "乒乓球又小又轻，用球拍来打，是大家爱玩的运动。"}, {"id": "low-sports-b2-006", "band": "low", "answer": "a", "prompt": "跳高的时候，我们要做什么？", "choices": [{"id": "a", "text": "跳起来越过横杆"}, {"id": "b", "text": "看谁力气大"}, {"id": "c", "text": "看谁跑得快"}], "subject": "sports", "difficulty": "quick", "explanation": "跳高是比谁跳得更高、能越过更高的横杆。"}, {"id": "low-sports-b2-007", "band": "low", "answer": "c", "prompt": "做运动之前，为什么要先喝一点水、别喝太多？", "choices": [{"id": "a", "text": "喝水会让人跑得更慢"}, {"id": "b", "text": "运动前完全不能喝水"}, {"id": "c", "text": "喝太多水运动时肚子会不舒服"}], "subject": "sports", "difficulty": "deep", "explanation": "运动前可以少量喝水，喝太多肚子会胀、跑动时不舒服。"}, {"id": "low-sports-b2-008", "band": "low", "answer": "c", "prompt": "在体育馆里玩，看到地上有水，应该怎么办？", "choices": [{"id": "a", "text": "在水上跑来跑去"}, {"id": "b", "text": "故意踩水玩"}, {"id": "c", "text": "小心绕开，告诉老师来擦干"}], "subject": "sports", "difficulty": "deep", "explanation": "地上有水很滑容易摔倒，要绕开并告诉老师处理。"}, {"id": "low-sports-b2-009", "band": "low", "answer": "b", "prompt": "下面哪一项是用手投篮的运动？", "choices": [{"id": "a", "text": "游泳"}, {"id": "b", "text": "篮球"}, {"id": "c", "text": "足球"}], "subject": "sports", "difficulty": "quick", "explanation": "篮球是用手运球、投篮的运动。"}, {"id": "low-sports-b2-010", "band": "low", "answer": "a", "prompt": "我们身体里负责让我们跑跳的，是哪个部位？", "choices": [{"id": "a", "text": "腿和脚"}, {"id": "b", "text": "耳朵"}, {"id": "c", "text": "鼻子"}], "subject": "sports", "difficulty": "quick", "explanation": "我们靠腿和脚的力量来跑步、跳跃。"}, {"id": "low-sports-b2-011", "band": "low", "answer": "a", "prompt": "小朋友玩接力赛，把接力棒交给下一个人时，要注意什么？", "choices": [{"id": "a", "text": "稳稳地把棒交到队友手里"}, {"id": "b", "text": "自己拿着棒不给队友"}, {"id": "c", "text": "用力把棒扔出去"}], "subject": "sports", "difficulty": "deep", "explanation": "接力时要稳稳把棒交给队友，扔出去容易掉、犯规。"}, {"id": "low-sports-b2-012", "band": "low", "answer": "a", "prompt": "夏天在太阳下运动，戴什么能保护头不被晒？", "choices": [{"id": "a", "text": "遮阳帽"}, {"id": "b", "text": "围巾"}, {"id": "c", "text": "棉手套"}], "subject": "sports", "difficulty": "quick", "explanation": "夏天运动戴遮阳帽能挡太阳，保护头和眼睛。"}, {"id": "low-sports-b2-013", "band": "low", "answer": "a", "prompt": "踢球时不小心把球踢到了马路上，应该怎么办？", "choices": [{"id": "a", "text": "请大人帮忙，不能自己冲到马路上捡"}, {"id": "b", "text": "马上跑到马路中间去捡"}, {"id": "c", "text": "不看车直接冲过去"}], "subject": "sports", "difficulty": "deep", "explanation": "马路上有车很危险，要请大人帮忙，绝不能自己冲过去。"}, {"id": "low-sports-b2-014", "band": "low", "answer": "a", "prompt": "做体操时，跟着音乐一起动，主要是为了什么？", "choices": [{"id": "a", "text": "活动身体、让身体更灵活"}, {"id": "b", "text": "为了不上课"}, {"id": "c", "text": "比谁声音大"}], "subject": "sports", "difficulty": "quick", "explanation": "做体操能活动全身、舒展筋骨，让身体更灵活健康。"}, {"id": "low-sports-b2-015", "band": "low", "answer": "a", "prompt": "下面哪样是踢毽子最常用的部位？", "choices": [{"id": "a", "text": "脚的内侧"}, {"id": "b", "text": "头顶"}, {"id": "c", "text": "手心"}], "subject": "sports", "difficulty": "quick", "explanation": "踢毽子常用脚的内侧，又稳又好控制。"}, {"id": "low-sports-b2-016", "band": "low", "answer": "c", "prompt": "和小伙伴一起做游戏时，下面哪种做法最好？", "choices": [{"id": "a", "text": "耍赖不守规则"}, {"id": "b", "text": "输了就发脾气"}, {"id": "c", "text": "遵守规则、互相谦让"}], "subject": "sports", "difficulty": "deep", "explanation": "一起玩要守规则、互相谦让，这样大家都开心。"}, {"id": "low-sports-b2-017", "band": "low", "answer": "b", "prompt": "跑步快到终点时摔倒了，旁边的小朋友应该怎么做？", "choices": [{"id": "a", "text": "假装没看见"}, {"id": "b", "text": "过去扶他、问他疼不疼"}, {"id": "c", "text": "在旁边笑话他"}], "subject": "sports", "difficulty": "deep", "explanation": "同学摔倒了要关心他、扶他起来，做个有爱心的好伙伴。"}, {"id": "low-sports-b2-018", "band": "low", "answer": "c", "prompt": "下面哪样运动是在冰上滑行的？", "choices": [{"id": "a", "text": "打乒乓球"}, {"id": "b", "text": "跳绳"}, {"id": "c", "text": "滑冰"}], "subject": "sports", "difficulty": "quick", "explanation": "滑冰是穿着冰鞋在冰面上滑行的运动。"}, {"id": "low-sports-b2-019", "band": "low", "answer": "a", "prompt": "上体育课穿衣服，下面哪样最合适？", "choices": [{"id": "a", "text": "宽松舒服的运动服"}, {"id": "b", "text": "很紧的小皮鞋"}, {"id": "c", "text": "长长的连衣裙"}], "subject": "sports", "difficulty": "quick", "explanation": "运动时穿宽松的运动服，活动起来才方便、不容易受伤。"}, {"id": "low-sports-b2-020", "band": "low", "answer": "a", "prompt": "小朋友每天蹦蹦跳跳、多运动，晚上会怎么样？", "choices": [{"id": "a", "text": "睡得更香、长得更好"}, {"id": "b", "text": "一直睡不着"}, {"id": "c", "text": "变得不爱吃饭"}], "subject": "sports", "difficulty": "deep", "explanation": "白天多运动，晚上睡得香，对长身体很有帮助。"}, {"id": "high-sports-b2-001", "band": "high", "answer": "b", "prompt": "篮球比赛中，在罚球线投进一个罚球能得几分？", "choices": [{"id": "a", "text": "3分"}, {"id": "b", "text": "1分"}, {"id": "c", "text": "2分"}], "subject": "sports", "difficulty": "quick", "explanation": "罚球命中得1分，三分线内投篮得2分，三分线外得3分。"}, {"id": "high-sports-b2-002", "band": "high", "answer": "c", "prompt": "足球比赛中，一名队员严重犯规被罚下场，裁判出示的是？", "choices": [{"id": "a", "text": "绿牌"}, {"id": "b", "text": "黄牌"}, {"id": "c", "text": "红牌"}], "subject": "sports", "difficulty": "quick", "explanation": "红牌表示罚出场，黄牌是警告，两张黄牌也会变成红牌罚下。"}, {"id": "high-sports-b2-003", "band": "high", "answer": "a", "prompt": "现代奥运会几年举办一届夏季奥运会？", "choices": [{"id": "a", "text": "4年"}, {"id": "b", "text": "2年"}, {"id": "c", "text": "6年"}], "subject": "sports", "difficulty": "quick", "explanation": "夏季奥运会每4年举办一届，是全世界最重要的综合运动会。"}, {"id": "high-sports-b2-004", "band": "high", "answer": "b", "prompt": "长跑或运动后立刻大量喝冰水，可能带来什么问题？", "choices": [{"id": "a", "text": "对身体完全没影响"}, {"id": "b", "text": "刺激肠胃，引起不舒服"}, {"id": "c", "text": "让人跑得更快"}], "subject": "sports", "difficulty": "deep", "explanation": "剧烈运动后身体很热，猛灌冰水会刺激肠胃，应小口喝温水。"}, {"id": "high-sports-b2-005", "band": "high", "answer": "c", "prompt": "跳绳时为了保护膝盖，落地应该怎么做？", "choices": [{"id": "a", "text": "用脚后跟重重地砸地"}, {"id": "b", "text": "双腿完全伸直硬落地"}, {"id": "c", "text": "用前脚掌轻轻落地、膝盖微屈缓冲"}], "subject": "sports", "difficulty": "deep", "explanation": "前脚掌落地、膝盖微屈能缓冲，减少对膝关节的冲击。"}, {"id": "high-sports-b2-006", "band": "high", "answer": "b", "prompt": "乒乓球比赛中，每人轮流发球几个后交换发球权？", "choices": [{"id": "a", "text": "1个"}, {"id": "b", "text": "2个"}, {"id": "c", "text": "5个"}], "subject": "sports", "difficulty": "deep", "explanation": "现行规则下每人连发2个球后就交换发球权（10平后改为各发1个）。"}, {"id": "high-sports-b2-007", "band": "high", "answer": "a", "prompt": "参加体育比赛，比赛结束后正确的体育精神是？", "choices": [{"id": "a", "text": "无论输赢都和对手握手致意"}, {"id": "b", "text": "赢了就嘲笑对方"}, {"id": "c", "text": "输了就指责裁判"}], "subject": "sports", "difficulty": "quick", "explanation": "尊重对手、胜不骄败不馁，赛后握手致意是良好的体育精神。"}, {"id": "high-sports-b2-008", "band": "high", "answer": "b", "prompt": "跑步时小腿突然抽筋，下面哪种处理比较合适？", "choices": [{"id": "a", "text": "忍着痛继续快跑"}, {"id": "b", "text": "停下来轻轻拉伸、按摩抽筋的肌肉"}, {"id": "c", "text": "用力跺脚让它更紧"}], "subject": "sports", "difficulty": "deep", "explanation": "抽筋时应停下来，缓慢拉伸并按摩抽筋部位，帮助肌肉放松。"}, {"id": "high-sports-b2-009", "band": "high", "answer": "c", "prompt": "足球比赛中，球整个越过球门线进入球门，叫做？", "choices": [{"id": "a", "text": "角球"}, {"id": "b", "text": "越位"}, {"id": "c", "text": "进球得分"}], "subject": "sports", "difficulty": "quick", "explanation": "球整个越过门线进入球门即进球得分，每球计1分。"}, {"id": "high-sports-b2-010", "band": "high", "answer": "c", "prompt": "标准田径场最内圈跑道跑一圈是多少米？", "choices": [{"id": "a", "text": "100米"}, {"id": "b", "text": "1000米"}, {"id": "c", "text": "400米"}], "subject": "sports", "difficulty": "quick", "explanation": "标准田径场内圈一圈是400米，所以跑800米要跑两圈。"}, {"id": "high-sports-b2-011", "band": "high", "answer": "b", "prompt": "为了身体健康，世界卫生组织建议儿童每天至少运动多久？", "choices": [{"id": "a", "text": "5分钟就足够了"}, {"id": "b", "text": "60分钟左右的中等以上强度运动"}, {"id": "c", "text": "完全不需要专门运动"}], "subject": "sports", "difficulty": "deep", "explanation": "建议儿童青少年每天累计约60分钟中高强度身体活动，有益成长。"}, {"id": "high-sports-b2-012", "band": "high", "answer": "a", "prompt": "打篮球时不小心崴了脚、脚踝肿起来，正确处理是？", "choices": [{"id": "a", "text": "先停止运动，冷敷、抬高患处并及时就医"}, {"id": "b", "text": "马上用热水使劲泡"}, {"id": "c", "text": "忍着继续打完比赛"}], "subject": "sports", "difficulty": "deep", "explanation": "急性扭伤早期应停止活动、冷敷消肿、抬高患处，严重时就医。"}, {"id": "high-sports-b2-013", "band": "high", "answer": "a", "prompt": "排球比赛中，每队场上有几名队员？", "choices": [{"id": "a", "text": "6名"}, {"id": "b", "text": "5名"}, {"id": "c", "text": "11名"}], "subject": "sports", "difficulty": "quick", "explanation": "排球每队场上6名队员，篮球5名，足球11名。"}, {"id": "high-sports-b2-014", "band": "high", "answer": "c", "prompt": "运动前做热身的主要作用是什么？", "choices": [{"id": "a", "text": "纯粹是浪费时间"}, {"id": "b", "text": "消耗体力让比赛更累"}, {"id": "c", "text": "让身体逐渐进入状态、减少受伤"}], "subject": "sports", "difficulty": "quick", "explanation": "热身能升高体温、活动关节肌肉，降低运动损伤的风险。"}, {"id": "high-sports-b2-015", "band": "high", "answer": "c", "prompt": "乒乓球被誉为中国的什么？", "choices": [{"id": "a", "text": "国旗"}, {"id": "b", "text": "国歌"}, {"id": "c", "text": "国球"}], "subject": "sports", "difficulty": "quick", "explanation": "乒乓球在中国普及度高、成绩辉煌，被称为“国球”。"}, {"id": "high-sports-b2-016", "band": "high", "answer": "a", "prompt": "短跑起跑时，发令枪还没响就提前起跑，叫做？", "choices": [{"id": "a", "text": "抢跑（犯规）"}, {"id": "b", "text": "冲刺"}, {"id": "c", "text": "加速"}], "subject": "sports", "difficulty": "quick", "explanation": "枪响前起跑叫抢跑，属于犯规，可能被判罚。"}, {"id": "high-sports-b2-017", "band": "high", "answer": "a", "prompt": "长时间在烈日下剧烈运动，可能发生中暑，预防办法是？", "choices": [{"id": "a", "text": "避开正午高温、适当休息并及时补水"}, {"id": "b", "text": "穿厚衣服多出汗"}, {"id": "c", "text": "不喝水一直运动"}], "subject": "sports", "difficulty": "deep", "explanation": "高温天应避开正午、注意补水和休息，感到不适要立即停下。"}, {"id": "high-sports-b2-018", "band": "high", "answer": "c", "prompt": "足球比赛中，下半场和上半场各通常踢多少分钟？", "choices": [{"id": "a", "text": "各90分钟"}, {"id": "b", "text": "各15分钟"}, {"id": "c", "text": "各45分钟"}], "subject": "sports", "difficulty": "deep", "explanation": "标准足球比赛上下半场各45分钟，全场90分钟（不含补时）。"}, {"id": "high-sports-b2-019", "band": "high", "answer": "b", "prompt": "队友在比赛中表现失误导致丢分，作为同伴最好怎么做？", "choices": [{"id": "a", "text": "当场大声责怪他"}, {"id": "b", "text": "鼓励他、一起想办法追回来"}, {"id": "c", "text": "赌气不再传球给他"}], "subject": "sports", "difficulty": "quick", "explanation": "团队比赛靠配合，鼓励队友、共同面对，才能凝聚力量。"}, {"id": "high-sports-b2-020", "band": "high", "answer": "b", "prompt": "想提高耐力，下面哪种运动最合适长期坚持？", "choices": [{"id": "a", "text": "只做一次性的大力气比赛"}, {"id": "b", "text": "慢跑、游泳等有氧运动"}, {"id": "c", "text": "长时间坐着不动"}], "subject": "sports", "difficulty": "deep", "explanation": "慢跑、游泳等有氧运动能有效增强心肺功能和耐力。"}, {"id": "low-life-b2-001", "band": "low", "answer": "a", "prompt": "早上起床后，我们应该先做什么来保护牙齿？", "choices": [{"id": "a", "text": "刷牙"}, {"id": "b", "text": "什么都不做"}, {"id": "c", "text": "吃糖"}], "subject": "life", "difficulty": "quick", "explanation": "早晚刷牙能清除食物残渣、保护牙齿，预防蛀牙。"}, {"id": "low-life-b2-002", "band": "low", "answer": "a", "prompt": "吃饭前，我们的手应该怎么样？", "choices": [{"id": "a", "text": "用肥皂把手洗干净"}, {"id": "b", "text": "直接用脏手拿东西吃"}, {"id": "c", "text": "在衣服上擦两下就行"}], "subject": "life", "difficulty": "quick", "explanation": "饭前用肥皂洗手能洗掉细菌，吃得更卫生、不容易生病。"}, {"id": "low-life-b2-003", "band": "low", "answer": "a", "prompt": "在学校见到老师，有礼貌的做法是？", "choices": [{"id": "a", "text": "主动问“老师好”"}, {"id": "b", "text": "做个鬼脸跑开"}, {"id": "c", "text": "假装没看见"}], "subject": "life", "difficulty": "quick", "explanation": "主动向老师问好是有礼貌的表现，会让人觉得你很懂事。"}, {"id": "low-life-b2-004", "band": "low", "answer": "b", "prompt": "看到家里着火了，应该拨打哪个电话？", "choices": [{"id": "a", "text": "120"}, {"id": "b", "text": "119"}, {"id": "c", "text": "110"}], "subject": "life", "difficulty": "quick", "explanation": "119是火警电话；120是急救，110是报警，要记清楚。"}, {"id": "low-life-b2-005", "band": "low", "answer": "c", "prompt": "有人受了重伤需要救护车，应该拨打哪个电话？", "choices": [{"id": "a", "text": "119"}, {"id": "b", "text": "114"}, {"id": "c", "text": "120"}], "subject": "life", "difficulty": "quick", "explanation": "120是急救电话，可以叫来救护车；火警是119。"}, {"id": "low-life-b2-006", "band": "low", "answer": "a", "prompt": "玩具玩完之后，应该怎么做？", "choices": [{"id": "a", "text": "收好放回原来的地方"}, {"id": "b", "text": "藏到看不见的角落"}, {"id": "c", "text": "扔在地上不管"}], "subject": "life", "difficulty": "quick", "explanation": "玩完把玩具收回原位，房间整洁，下次也好找。"}, {"id": "low-life-b2-007", "band": "low", "answer": "a", "prompt": "过马路时，下面哪种做法最安全？", "choices": [{"id": "a", "text": "走斑马线、看红绿灯"}, {"id": "b", "text": "边走边低头玩手机"}, {"id": "c", "text": "从车流中间穿过去"}], "subject": "life", "difficulty": "quick", "explanation": "过马路要走斑马线、看红绿灯，绿灯亮再走才安全。"}, {"id": "low-life-b2-008", "band": "low", "answer": "c", "prompt": "喝完的塑料瓶应该放进哪个颜色的垃圾桶？", "choices": [{"id": "a", "text": "红色（有害垃圾）"}, {"id": "b", "text": "随便哪个都行"}, {"id": "c", "text": "蓝色（可回收物）"}], "subject": "life", "difficulty": "deep", "explanation": "塑料瓶是可回收物，要放进蓝色垃圾桶循环利用。"}, {"id": "low-life-b2-009", "band": "low", "answer": "a", "prompt": "刷牙的时候，牙膏用多少最合适？", "choices": [{"id": "a", "text": "挤黄豆粒那么一点点就够了"}, {"id": "b", "text": "挤满整个牙刷"}, {"id": "c", "text": "越多越好，挤一大堆"}], "subject": "life", "difficulty": "deep", "explanation": "小朋友刷牙用黄豆大小的牙膏就够了，不必挤很多。"}, {"id": "low-life-b2-010", "band": "low", "answer": "b", "prompt": "打喷嚏或咳嗽的时候，应该怎么做才不传染别人？", "choices": [{"id": "a", "text": "对着别人大声喷"}, {"id": "b", "text": "用纸巾或手肘捂住口鼻"}, {"id": "c", "text": "什么都不挡"}], "subject": "life", "difficulty": "deep", "explanation": "用纸巾或手肘挡住口鼻，能挡住飞沫，不把病菌传给别人。"}, {"id": "low-life-b2-011", "band": "low", "answer": "a", "prompt": "想请别人帮忙时，先说哪个词最有礼貌？", "choices": [{"id": "a", "text": "请"}, {"id": "b", "text": "快点"}, {"id": "c", "text": "喂"}], "subject": "life", "difficulty": "quick", "explanation": "请别人帮忙先说“请”，是有礼貌的好习惯。"}, {"id": "low-life-b2-012", "band": "low", "answer": "a", "prompt": "吃饭时，下面哪种做法是对的？", "choices": [{"id": "a", "text": "细嚼慢咽、不浪费饭菜"}, {"id": "b", "text": "把不爱吃的偷偷扔掉"}, {"id": "c", "text": "边吃边大声说笑乱跑"}], "subject": "life", "difficulty": "quick", "explanation": "吃饭要细嚼慢咽、不挑食、不浪费，这样身体才健康。"}, {"id": "low-life-b2-013", "band": "low", "answer": "c", "prompt": "在家里看到桌上的热水壶，应该怎么做？", "choices": [{"id": "a", "text": "用手去摸壶身"}, {"id": "b", "text": "把壶推来推去玩"}, {"id": "c", "text": "不去碰它，以免烫伤"}], "subject": "life", "difficulty": "deep", "explanation": "热水壶很烫，碰了会烫伤，要远离不去乱碰。"}, {"id": "low-life-b2-014", "band": "low", "answer": "b", "prompt": "睡觉前应该做什么，对牙齿和身体好？", "choices": [{"id": "a", "text": "吃很多甜食再睡"}, {"id": "b", "text": "刷牙、洗脸、按时上床"}, {"id": "c", "text": "一直玩到很晚"}], "subject": "life", "difficulty": "quick", "explanation": "睡前刷牙洗脸、早点休息，第二天才有精神。"}, {"id": "low-life-b2-015", "band": "low", "answer": "b", "prompt": "陌生人在路上要带你走，说带你去找妈妈，你应该？", "choices": [{"id": "a", "text": "高高兴兴跟他走"}, {"id": "b", "text": "不跟他走，赶快找老师或警察"}, {"id": "c", "text": "他给糖就跟着去"}], "subject": "life", "difficulty": "deep", "explanation": "不能跟陌生人走，要找老师、警察等可信任的大人帮忙。"}, {"id": "low-life-b2-016", "band": "low", "answer": "a", "prompt": "洗手要洗多久，才能洗得比较干净？", "choices": [{"id": "a", "text": "认真搓洗约二十秒"}, {"id": "b", "text": "只洗手心不洗手背"}, {"id": "c", "text": "用水冲一下就好"}], "subject": "life", "difficulty": "deep", "explanation": "用肥皂认真搓洗约二十秒，手心手背指缝都要洗到才干净。"}, {"id": "low-life-b2-017", "band": "low", "answer": "b", "prompt": "用过的纸巾应该怎么处理？", "choices": [{"id": "a", "text": "塞进口袋一直放着"}, {"id": "b", "text": "扔进垃圾桶"}, {"id": "c", "text": "随手丢在地上"}], "subject": "life", "difficulty": "quick", "explanation": "用过的纸巾要扔进垃圾桶，乱扔会让环境变脏。"}, {"id": "low-life-b2-018", "band": "low", "answer": "a", "prompt": "离开房间时，为了节约用电，应该？", "choices": [{"id": "a", "text": "随手关灯"}, {"id": "b", "text": "把灯开得更亮"}, {"id": "c", "text": "灯一直开着"}], "subject": "life", "difficulty": "quick", "explanation": "离开房间随手关灯，节约用电也保护环境。"}, {"id": "low-life-b2-019", "band": "low", "answer": "a", "prompt": "不小心把水洒在地上，应该怎么做？", "choices": [{"id": "a", "text": "用抹布擦干净，防止别人滑倒"}, {"id": "b", "text": "装作没看见走开"}, {"id": "c", "text": "再多倒点水玩"}], "subject": "life", "difficulty": "deep", "explanation": "水洒了要及时擦干，地上湿滑别人容易摔倒。"}, {"id": "low-life-b2-020", "band": "low", "answer": "a", "prompt": "剩下没吃完的果皮、菜叶，属于哪种垃圾？", "choices": [{"id": "a", "text": "厨余垃圾（湿垃圾）"}, {"id": "b", "text": "有害垃圾"}, {"id": "c", "text": "可回收物"}], "subject": "life", "difficulty": "deep", "explanation": "果皮菜叶等是厨余垃圾，要分类投放才环保。"}, {"id": "low-life-b2-021", "band": "low", "answer": "b", "prompt": "天气很冷出门，下面哪样穿戴最保暖？", "choices": [{"id": "a", "text": "只穿一件短袖"}, {"id": "b", "text": "棉袄加上帽子手套"}, {"id": "c", "text": "光着脚穿凉鞋"}], "subject": "life", "difficulty": "quick", "explanation": "冷天要穿厚棉袄、戴帽子手套，注意保暖才不会感冒。"}, {"id": "low-life-b2-022", "band": "low", "answer": "c", "prompt": "书包里的课本应该怎么放才整齐？", "choices": [{"id": "a", "text": "随便乱塞一团"}, {"id": "b", "text": "全部揉皱挤进去"}, {"id": "c", "text": "按大小分类、立着摆好"}], "subject": "life", "difficulty": "deep", "explanation": "课本按大小分类立着放，整齐又好找，也不容易折坏。"}, {"id": "low-life-b2-023", "band": "low", "answer": "b", "prompt": "在家里玩，闻到一股像臭鸡蛋的气味（可能是燃气漏了），应该？", "choices": [{"id": "a", "text": "不理它继续玩"}, {"id": "b", "text": "赶快开窗、告诉大人，不开火不开灯"}, {"id": "c", "text": "赶快打开打火机看看"}], "subject": "life", "difficulty": "deep", "explanation": "闻到燃气味要开窗通风、告诉大人，绝不能点火，避免危险。"}, {"id": "low-life-b2-024", "band": "low", "answer": "b", "prompt": "看电视或看书时，眼睛离屏幕、书本太近会怎样？", "choices": [{"id": "a", "text": "看得更清楚更好"}, {"id": "b", "text": "伤害眼睛，容易近视"}, {"id": "c", "text": "对眼睛没有影响"}], "subject": "life", "difficulty": "deep", "explanation": "离太近会让眼睛疲劳、容易近视，要保持适当的距离。"}, {"id": "low-life-b2-025", "band": "low", "answer": "c", "prompt": "想吃得健康，下面哪样吃多了对身体不好？", "choices": [{"id": "a", "text": "新鲜蔬菜"}, {"id": "b", "text": "水果"}, {"id": "c", "text": "很多糖果和油炸食品"}], "subject": "life", "difficulty": "deep", "explanation": "糖果和油炸食品吃多了对身体不好，要多吃蔬菜水果。"}, {"id": "low-life-b2-026", "band": "low", "answer": "a", "prompt": "在楼梯上，下面哪种做法最安全？", "choices": [{"id": "a", "text": "扶着扶手、一步一步慢慢走"}, {"id": "b", "text": "从扶手上滑下来"}, {"id": "c", "text": "一次跳好几级"}], "subject": "life", "difficulty": "deep", "explanation": "上下楼梯要扶扶手、慢慢走，蹦跳或滑扶手都很危险。"}, {"id": "low-life-b2-027", "band": "low", "answer": "c", "prompt": "妈妈在做饭，厨房的火和刀都很危险，小朋友应该？", "choices": [{"id": "a", "text": "自己拿刀切东西"}, {"id": "b", "text": "去玩灶台上的火"}, {"id": "c", "text": "不乱碰火和刀，需要时请大人帮忙"}], "subject": "life", "difficulty": "deep", "explanation": "火和刀很危险，小朋友不能乱碰，要请大人帮忙。"}, {"id": "low-life-b2-028", "band": "low", "answer": "c", "prompt": "在公共场所和大人走散了，应该怎么办？", "choices": [{"id": "a", "text": "自己到处乱跑去找"}, {"id": "b", "text": "跟着陌生人走"}, {"id": "c", "text": "待在原地，或找工作人员、警察帮忙"}], "subject": "life", "difficulty": "deep", "explanation": "走散了最好待在原地，或找穿制服的工作人员、警察帮忙。"}, {"id": "low-life-b2-029", "band": "low", "answer": "c", "prompt": "吃水果之前，应该先做什么？", "choices": [{"id": "a", "text": "直接放进嘴里"}, {"id": "b", "text": "在衣服上蹭一蹭"}, {"id": "c", "text": "把水果洗干净"}], "subject": "life", "difficulty": "quick", "explanation": "水果表面有灰尘和细菌，吃前要洗干净更卫生。"}, {"id": "low-life-b2-030", "band": "low", "answer": "b", "prompt": "看到地上有别人掉的钱包，正确的做法是？", "choices": [{"id": "a", "text": "自己偷偷拿走"}, {"id": "b", "text": "交给老师或警察"}, {"id": "c", "text": "踢到一边不管"}], "subject": "life", "difficulty": "deep", "explanation": "捡到东西要交给老师或警察，做个诚实的好孩子。"}, {"id": "high-life-b2-001", "band": "high", "answer": "a", "prompt": "为了营养均衡，每天的饮食最好怎么搭配？", "choices": [{"id": "a", "text": "主食、蔬菜、蛋白质、水果都吃一些"}, {"id": "b", "text": "只吃零食不吃正餐"}, {"id": "c", "text": "只吃自己爱吃的肉"}], "subject": "life", "difficulty": "deep", "explanation": "均衡饮食要荤素搭配、品种多样，身体才能获得全面的营养。"}, {"id": "high-life-b2-002", "band": "high", "answer": "b", "prompt": "做作业时总想玩手机，下面哪种时间管理方法更好？", "choices": [{"id": "a", "text": "边写边刷手机"}, {"id": "b", "text": "先专心写完作业，再安排时间玩"}, {"id": "c", "text": "一直玩，等很晚再赶作业"}], "subject": "life", "difficulty": "deep", "explanation": "先完成重要的事再娱乐，专注做事效率更高、也更轻松。"}, {"id": "high-life-b2-003", "band": "high", "answer": "c", "prompt": "每个月有一些零花钱，下面哪种用法更聪明？", "choices": [{"id": "a", "text": "一拿到就立刻全部花光"}, {"id": "b", "text": "向同学借钱去买想要的东西"}, {"id": "c", "text": "计划着花，存下一部分以备需要"}], "subject": "life", "difficulty": "deep", "explanation": "学会计划花钱、留一些储蓄，是很重要的理财好习惯。"}, {"id": "high-life-b2-004", "band": "high", "answer": "a", "prompt": "网上有陌生网友想约你单独见面，你应该？", "choices": [{"id": "a", "text": "拒绝，并告诉家长这件事"}, {"id": "b", "text": "把家庭住址告诉对方"}, {"id": "c", "text": "瞒着家长自己偷偷去"}], "subject": "life", "difficulty": "deep", "explanation": "网络上身份难辨，绝不私自约见网友，要及时告诉家长。"}, {"id": "high-life-b2-005", "band": "high", "answer": "a", "prompt": "手被开水或热油烫伤了，第一步应该怎么处理？", "choices": [{"id": "a", "text": "立刻用流动的冷水冲烫伤处十几分钟"}, {"id": "b", "text": "赶快涂上牙膏或酱油"}, {"id": "c", "text": "用手使劲揉搓"}], "subject": "life", "difficulty": "deep", "explanation": "烫伤后第一时间用流动冷水持续冲洗降温，再视情况就医，别乱涂东西。"}, {"id": "high-life-b2-006", "band": "high", "answer": "b", "prompt": "一个人在外面迷路了，下面哪种做法最稳妥？", "choices": [{"id": "a", "text": "随便上一个陌生人的车"}, {"id": "b", "text": "原地等候或向商店、警察求助，联系家人"}, {"id": "c", "text": "慌张地到处乱跑"}], "subject": "life", "difficulty": "deep", "explanation": "迷路时保持冷静，向可信的工作人员、警察求助并联系家人。"}, {"id": "high-life-b2-007", "band": "high", "answer": "a", "prompt": "在家想帮忙做家务，下面哪件适合你独立完成？", "choices": [{"id": "a", "text": "整理自己的房间、叠衣服、扫地"}, {"id": "b", "text": "独自使用煤气灶炒菜"}, {"id": "c", "text": "独自修理插座电线"}], "subject": "life", "difficulty": "deep", "explanation": "叠衣扫地等力所能及，明火和电器维修有危险，要大人来做。"}, {"id": "high-life-b2-008", "band": "high", "answer": "a", "prompt": "接待来家里做客的客人，比较得体的做法是？", "choices": [{"id": "a", "text": "主动问好、请客人坐、倒杯水"}, {"id": "b", "text": "嫌客人麻烦躲进房间"}, {"id": "c", "text": "不理客人继续打游戏"}], "subject": "life", "difficulty": "quick", "explanation": "待客有礼，主动问好、招呼客人入座、奉上茶水，让人感到温暖。"}, {"id": "high-life-b2-009", "band": "high", "answer": "b", "prompt": "为了保护环境，下面哪种做法最值得提倡？", "choices": [{"id": "a", "text": "垃圾随手乱丢"}, {"id": "b", "text": "自带水杯、少用一次性用品"}, {"id": "c", "text": "经常用大量一次性塑料制品"}], "subject": "life", "difficulty": "quick", "explanation": "减少一次性用品、做好垃圾分类，从小事做起就能保护环境。"}, {"id": "high-life-b2-010", "band": "high", "answer": "a", "prompt": "晚上想保证充足睡眠、第二天精神好，下面哪种习惯最好？", "choices": [{"id": "a", "text": "按时上床，睡前不长时间看电子屏幕"}, {"id": "b", "text": "睡前喝很多含糖饮料"}, {"id": "c", "text": "熬夜刷视频到深夜"}], "subject": "life", "difficulty": "deep", "explanation": "规律作息、睡前少看屏幕，能提高睡眠质量，白天更有精神。"}, {"id": "high-life-b2-011", "band": "high", "answer": "c", "prompt": "下面哪种早餐搭配更有营养？", "choices": [{"id": "a", "text": "只喝一杯含糖饮料"}, {"id": "b", "text": "一大包薯片"}, {"id": "c", "text": "鸡蛋、牛奶加全麦面包"}], "subject": "life", "difficulty": "deep", "explanation": "鸡蛋牛奶提供蛋白质，全麦面包提供能量，营养更全面。"}, {"id": "high-life-b2-012", "band": "high", "answer": "c", "prompt": "收到一条短信说你中了大奖，要先交手续费才能领，你应该？", "choices": [{"id": "a", "text": "赶快按要求把钱转过去"}, {"id": "b", "text": "把银行卡号发给对方"}, {"id": "c", "text": "不理会，这多半是诈骗，告诉家长"}], "subject": "life", "difficulty": "deep", "explanation": "先交钱再领奖几乎都是诈骗，不要转账、不泄露信息，告诉家长。"}, {"id": "high-life-b2-013", "band": "high", "answer": "b", "prompt": "做菜时油锅突然起火，下面哪种做法最危险、绝不能做？", "choices": [{"id": "a", "text": "盖上锅盖隔绝空气"}, {"id": "b", "text": "往锅里泼水灭火"}, {"id": "c", "text": "关掉燃气阀门"}], "subject": "life", "difficulty": "deep", "explanation": "油锅起火往里泼水会让火势爆燃，应盖锅盖隔氧、关火。"}, {"id": "high-life-b2-014", "band": "high", "answer": "c", "prompt": "想做好每天的时间安排，下面哪种方法最有帮助？", "choices": [{"id": "a", "text": "把所有时间都用来玩"}, {"id": "b", "text": "想到哪做到哪、毫无计划"}, {"id": "c", "text": "列一个计划清单，分清轻重缓急"}], "subject": "life", "difficulty": "deep", "explanation": "列计划、分清主次能让一天更有条理，事情完成得更高效。"}, {"id": "high-life-b2-015", "band": "high", "answer": "a", "prompt": "买包装食品时，下面哪个信息一定要注意查看？", "choices": [{"id": "a", "text": "生产日期和保质期"}, {"id": "b", "text": "包装的颜色好不好看"}, {"id": "c", "text": "包装上的卡通图案"}], "subject": "life", "difficulty": "quick", "explanation": "查看生产日期和保质期，避免吃到过期食品，保障健康。"}, {"id": "high-life-b2-016", "band": "high", "answer": "a", "prompt": "在公交车或地铁上，遇到老人、孕妇上车，比较有礼貌的做法是？", "choices": [{"id": "a", "text": "主动让座"}, {"id": "b", "text": "占着两个座位"}, {"id": "c", "text": "假装睡着不让座"}], "subject": "life", "difficulty": "quick", "explanation": "主动给老人、孕妇等有需要的人让座，是文明有爱心的表现。"}, {"id": "high-life-b2-017", "band": "high", "answer": "c", "prompt": "和别人意见不同发生争论时，下面哪种做法更成熟？", "choices": [{"id": "a", "text": "大声吵、谁声音大谁有理"}, {"id": "b", "text": "骂对方一顿"}, {"id": "c", "text": "心平气和地表达，并认真听对方说"}], "subject": "life", "difficulty": "deep", "explanation": "沟通讲道理、互相倾听，比争吵更能解决问题、维护关系。"}, {"id": "high-life-b2-018", "band": "high", "answer": "b", "prompt": "在网上发言或聊天时，下面哪种做法是文明的？", "choices": [{"id": "a", "text": "随意转发没核实的消息"}, {"id": "b", "text": "友善礼貌，不骂人、不传谣"}, {"id": "c", "text": "用脏话攻击别人"}], "subject": "life", "difficulty": "quick", "explanation": "网络也要讲文明，友善表达、不造谣传谣，做个文明上网的人。"}, {"id": "high-life-b2-019", "band": "high", "answer": "c", "prompt": "为了节约用水，下面哪种做法最好？", "choices": [{"id": "a", "text": "洗手时把水开到最大"}, {"id": "b", "text": "让水龙头一直开着流水"}, {"id": "c", "text": "刷牙时关掉水龙头，用水盆接水"}], "subject": "life", "difficulty": "quick", "explanation": "刷牙关水龙头、循环用水，点滴节约就能省下很多水。"}, {"id": "high-life-b2-020", "band": "high", "answer": "a", "prompt": "看到有同学在背后说别人坏话、起外号，你应该？", "choices": [{"id": "a", "text": "不参与，并劝大家友善相处"}, {"id": "b", "text": "跟着一起说"}, {"id": "c", "text": "把听到的添油加醋传出去"}], "subject": "life", "difficulty": "deep", "explanation": "不参与背后议论，劝大家友善待人，是有正义感的表现。"}, {"id": "high-life-b2-021", "band": "high", "answer": "b", "prompt": "流鼻血时，下面哪种处理方法是正确的？", "choices": [{"id": "a", "text": "把头使劲往后仰"}, {"id": "b", "text": "头微微前倾，捏住鼻翼按压几分钟"}, {"id": "c", "text": "用纸把鼻孔塞得很深"}], "subject": "life", "difficulty": "deep", "explanation": "流鼻血应头微前倾、捏住鼻翼按压止血，仰头会让血流进喉咙。"}, {"id": "high-life-b2-022", "band": "high", "answer": "b", "prompt": "答应了同学的事，后来发现自己做不到，最负责的做法是？", "choices": [{"id": "a", "text": "一直拖着不理"}, {"id": "b", "text": "及时坦诚说明，并道歉、想办法补救"}, {"id": "c", "text": "假装忘了这件事"}], "subject": "life", "difficulty": "deep", "explanation": "做不到要及时说明并道歉，诚实守信、勇于补救才让人信任。"}, {"id": "high-life-b2-023", "band": "high", "answer": "a", "prompt": "洗碗、洗菜的水可以怎样再利用，更环保？", "choices": [{"id": "a", "text": "收集起来用来冲厕所、浇花"}, {"id": "b", "text": "开着水龙头一直冲"}, {"id": "c", "text": "直接全部倒掉"}], "subject": "life", "difficulty": "deep", "explanation": "把淘米水、洗菜水收集起来浇花、冲厕，能节约不少水。"}, {"id": "high-life-b2-024", "band": "high", "answer": "c", "prompt": "长时间用电脑或手机后，为了保护视力应该怎么做？", "choices": [{"id": "a", "text": "接着再玩好几个小时"}, {"id": "b", "text": "在黑暗里继续看屏幕"}, {"id": "c", "text": "休息一会儿，远眺放松眼睛"}], "subject": "life", "difficulty": "quick", "explanation": "用眼一段时间要远眺、休息，劳逸结合才能保护视力。"}, {"id": "high-life-b2-025", "band": "high", "answer": "a", "prompt": "在图书馆、电影院等公共场所，比较文明的做法是？", "choices": [{"id": "a", "text": "保持安静，手机调静音"}, {"id": "b", "text": "大声打电话、聊天"}, {"id": "c", "text": "把脚搭在前排椅背上"}], "subject": "life", "difficulty": "quick", "explanation": "公共场所保持安静、不打扰他人，是基本的文明素养。"}, {"id": "high-life-b2-026", "band": "high", "answer": "c", "prompt": "独自在家时陌生人敲门，自称是修理工，你应该？", "choices": [{"id": "a", "text": "告诉他家里只有你一个人"}, {"id": "b", "text": "立刻开门让他进来"}, {"id": "c", "text": "不开门，先打电话问父母确认"}], "subject": "life", "difficulty": "deep", "explanation": "独自在家不要随便给陌生人开门，先联系父母确认更安全。"}, {"id": "high-life-b2-027", "band": "high", "answer": "b", "prompt": "妈妈让你帮忙买东西，找回的零钱应该怎么办？", "choices": [{"id": "a", "text": "随便花掉不告诉妈妈"}, {"id": "b", "text": "如数交还，并说清买了什么、花了多少"}, {"id": "c", "text": "偷偷留下一部分自己用"}], "subject": "life", "difficulty": "quick", "explanation": "帮忙买东西要把零钱如数交还、说明开支，做个诚实的孩子。"}, {"id": "high-life-b2-028", "band": "high", "answer": "a", "prompt": "和同学约好周末一起复习，可是临时有事去不了，最妥当的做法是？", "choices": [{"id": "a", "text": "提前告诉对方并道歉，另约时间"}, {"id": "b", "text": "不打招呼就放对方鸽子"}, {"id": "c", "text": "等对方等了很久才说"}], "subject": "life", "difficulty": "deep", "explanation": "有约在先若变动，应尽早通知并道歉、重新约定，这是守信和尊重。"}, {"id": "high-life-b2-029", "band": "high", "answer": "a", "prompt": "夏天吃剩的饭菜想留到下一顿，正确的做法是？", "choices": [{"id": "a", "text": "放凉后盖好放进冰箱冷藏，再吃前热透"}, {"id": "b", "text": "一直放在桌上常温保存"}, {"id": "c", "text": "放凉后直接吃，不再加热"}], "subject": "life", "difficulty": "deep", "explanation": "剩菜应及时冷藏防变质，再次食用前要彻底加热，避免吃坏肚子。"}, {"id": "high-life-b2-030", "band": "high", "answer": "b", "prompt": "想增强身体免疫力、少生病，下面哪种生活方式最好？", "choices": [{"id": "a", "text": "长期不运动、挑食偏食"}, {"id": "b", "text": "均衡饮食、规律作息、坚持运动"}, {"id": "c", "text": "经常熬夜、爱吃零食"}], "subject": "life", "difficulty": "deep", "explanation": "健康的免疫力来自均衡营养、充足睡眠和规律运动，需要长期坚持。"}, {"id": "low-social-b2-001", "band": "low", "answer": "b", "prompt": "上美术课，你的水彩笔不小心滚到了后桌同学脚边，他帮你捡了起来递给你。你应该说什么？", "choices": [{"id": "a", "text": "快给我。"}, {"id": "b", "text": "谢谢你！"}, {"id": "c", "text": "本来就该捡。"}], "subject": "social", "difficulty": "quick", "explanation": "别人帮了你，真诚说声“谢谢”最有礼貌，也会让对方开心。"}, {"id": "low-social-b2-002", "band": "low", "answer": "a", "prompt": "课间你正在玩拼图，一个同学走过来说“我也想玩”。怎么做最友好？", "choices": [{"id": "a", "text": "说“一起拼吧”，分他几块。"}, {"id": "b", "text": "把拼图全抱走。"}, {"id": "c", "text": "假装没听见。"}], "subject": "social", "difficulty": "quick", "explanation": "一起玩比一个人玩更有趣，邀请同学加入是交朋友的好办法。"}, {"id": "low-social-b2-003", "band": "low", "answer": "b", "prompt": "你和同学都想当游戏里的“队长”，谁也不让谁。最好的办法是？", "choices": [{"id": "a", "text": "不玩了，生气走开。"}, {"id": "b", "text": "用石头剪刀布决定，轮流当。"}, {"id": "c", "text": "谁声音大谁当。"}], "subject": "social", "difficulty": "quick", "explanation": "用公平的办法决定，再轮流来，大家都开心，游戏才能继续。"}, {"id": "low-social-b2-004", "band": "low", "answer": "b", "prompt": "同学今天忘记带蜡笔，急得快哭了。你的盒子里有很多支。你会？", "choices": [{"id": "a", "text": "把盒子藏起来。"}, {"id": "b", "text": "借给他几支一起用。"}, {"id": "c", "text": "笑他真粗心。"}], "subject": "social", "difficulty": "quick", "explanation": "在别人有困难时帮一把，是善良的小朋友，下次你忘带他也会帮你。"}, {"id": "low-social-b2-005", "band": "low", "answer": "c", "prompt": "你不小心把同学搭好的积木碰倒了。最好怎么做？", "choices": [{"id": "a", "text": "赶紧跑开当没看见。"}, {"id": "b", "text": "说“是你放得不稳”。"}, {"id": "c", "text": "说“对不起”，帮他一起重新搭。"}], "subject": "social", "difficulty": "quick", "explanation": "做错了大方道歉，再帮忙补救，同学就不会生气啦。"}, {"id": "low-social-b2-006", "band": "low", "answer": "b", "prompt": "排队做操，后面的同学轻轻拍你说“你站到我的位置啦”。你发现真的站错了，应该？", "choices": [{"id": "a", "text": "不理他，就站这儿。"}, {"id": "b", "text": "说“不好意思”，回到自己的位置。"}, {"id": "c", "text": "推他一下。"}], "subject": "social", "difficulty": "quick", "explanation": "站错了大方说声抱歉、回到自己位置，是讲道理的好孩子。"}, {"id": "low-social-b2-007", "band": "low", "answer": "a", "prompt": "同桌画了一只小兔子，特别喜欢，问你“好看吗”。你觉得有点歪，但他很认真。怎么回最暖？", "choices": [{"id": "a", "text": "你画得很用心，耳朵真可爱！"}, {"id": "b", "text": "难看死了。"}, {"id": "c", "text": "还不如我画的。"}], "subject": "social", "difficulty": "deep", "explanation": "夸夸他用心和画得好的地方，既真诚又让人开心。"}, {"id": "low-social-b2-008", "band": "low", "answer": "a", "prompt": "做游戏时，一个同学总是输，开始有点想哭。你是赢的那一方，怎么做最好？", "choices": [{"id": "a", "text": "鼓励他“再来一次，你会越来越棒”。"}, {"id": "b", "text": "哈哈大笑说“你太菜了”。"}, {"id": "c", "text": "炫耀自己赢了好多次。"}], "subject": "social", "difficulty": "deep", "explanation": "赢了不嘲笑、还鼓励对方，是真正有风度的小朋友。"}, {"id": "low-social-b2-009", "band": "low", "answer": "b", "prompt": "你和好朋友因为抢着滑滑梯吵了一架，现在心里有点后悔。怎么和好最好？", "choices": [{"id": "a", "text": "再也不理他。"}, {"id": "b", "text": "主动说“刚才我也有不对，我们一起玩吧”。"}, {"id": "c", "text": "一直等他先来找你。"}], "subject": "social", "difficulty": "deep", "explanation": "主动迈出第一步、承认自己也有不对，朋友很快就会和好。"}, {"id": "low-social-b2-010", "band": "low", "answer": "c", "prompt": "上课老师在讲故事，你突然想到一件好玩的事很想说。应该？", "choices": [{"id": "a", "text": "马上大声说出来。"}, {"id": "b", "text": "拍旁边同学讲给他听。"}, {"id": "c", "text": "先举手，等老师叫你再说。"}], "subject": "social", "difficulty": "quick", "explanation": "想发言先举手、等老师同意，这样不会打断课堂，大家都能听清楚。"}, {"id": "low-social-b2-011", "band": "low", "answer": "b", "prompt": "分零食的时候，你拿到一块大的，同桌拿到一块小的，他有点失落。你可以？", "choices": [{"id": "a", "text": "说“谁让你手慢”。"}, {"id": "b", "text": "说“我俩换一下，或者掰一半给你”。"}, {"id": "c", "text": "快点吃掉怕他要。"}], "subject": "social", "difficulty": "quick", "explanation": "主动分享、让别人也开心，是大方又善良的做法。"}, {"id": "low-social-b2-012", "band": "low", "answer": "b", "prompt": "一个同学说话有点口吃，有些人笑他。你应该怎么做？", "choices": [{"id": "a", "text": "跟着一起笑。"}, {"id": "b", "text": "耐心听他说完，不催也不笑。"}, {"id": "c", "text": "学他说话的样子。"}], "subject": "social", "difficulty": "deep", "explanation": "每个人都不一样，耐心又尊重地对待同学，才是真正友善。"}, {"id": "low-social-b2-013", "band": "low", "answer": "a", "prompt": "你借了同学的故事书看，看完了应该？", "choices": [{"id": "a", "text": "完好地还给他，并说声谢谢。"}, {"id": "b", "text": "放进自己书包带回家。"}, {"id": "c", "text": "忘在抽屉里不管了。"}], "subject": "social", "difficulty": "quick", "explanation": "借来的东西要爱护好、按时归还，同学才会乐意再借给你。"}, {"id": "low-social-b2-014", "band": "low", "answer": "a", "prompt": "下课了，你看到一个新同学一个人坐着，谁也不认识。你能做的最暖的事是？", "choices": [{"id": "a", "text": "走过去问“你想一起玩吗”。"}, {"id": "b", "text": "小声跟别人议论他。"}, {"id": "c", "text": "装作没看到。"}], "subject": "social", "difficulty": "quick", "explanation": "主动邀请新同学一起玩，会让他感到温暖，你也多了个朋友。"}, {"id": "low-social-b2-015", "band": "low", "answer": "b", "prompt": "做手工时桌上只有一瓶胶水，你和同桌都想先用。怎么办最好？", "choices": [{"id": "a", "text": "一把抢过来。"}, {"id": "b", "text": "说“你先用，用完给我”，轮流来。"}, {"id": "c", "text": "谁也别想用，我藏起来。"}], "subject": "social", "difficulty": "quick", "explanation": "东西只有一个时，商量好轮流用，两个人都能完成手工。"}, {"id": "low-social-b2-016", "band": "low", "answer": "c", "prompt": "你看到两个同学因为一支铅笔争来争去，快吵起来了。你能帮的好办法是？", "choices": [{"id": "a", "text": "也跟着喊，看谁声音大。"}, {"id": "b", "text": "赶快躲远点别管。"}, {"id": "c", "text": "过去说“别急，咱们问问到底是谁的”。"}], "subject": "social", "difficulty": "deep", "explanation": "冷静地帮他们想办法弄清楚，比一起吵闹更能解决问题。"}, {"id": "low-social-b2-017", "band": "low", "answer": "a", "prompt": "同学约你下课跳皮筋，可你今天就想安安静静看会儿书。怎么说最好？", "choices": [{"id": "a", "text": "说“今天我想看书，明天一起跳好吗”。"}, {"id": "b", "text": "不耐烦地说“别烦我”。"}, {"id": "c", "text": "勉强去玩，心里很不开心。"}], "subject": "social", "difficulty": "deep", "explanation": "温和地说明自己的想法、约下次，既照顾了自己也尊重了朋友。"}, {"id": "low-social-b2-018", "band": "low", "answer": "b", "prompt": "值日时你扫完地了，发现同学的窗台还没擦完。你会？", "choices": [{"id": "a", "text": "扔下抹布自己先走。"}, {"id": "b", "text": "说“我帮你一起擦吧”。"}, {"id": "c", "text": "催他“快点，就等你了”。"}], "subject": "social", "difficulty": "quick", "explanation": "做完自己的活儿还帮同学一把，是热心又有团队精神的好孩子。"}, {"id": "low-social-b2-019", "band": "low", "answer": "b", "prompt": "同学送你一颗他舍不得吃的糖，你应该怎么回应？", "choices": [{"id": "a", "text": "一把拿走转身就走。"}, {"id": "b", "text": "接过来说“谢谢你”，然后开心地分他一半。"}, {"id": "c", "text": "嫌弃地说“我不爱吃这个”。"}], "subject": "social", "difficulty": "quick", "explanation": "礼貌地道谢、再分享一点回去，这样的友谊会越来越好。"}, {"id": "low-social-b2-020", "band": "low", "answer": "b", "prompt": "你不小心说错了话，惹同桌生气了。你该怎么办？", "choices": [{"id": "a", "text": "坚持说自己没错。"}, {"id": "b", "text": "真诚地说“对不起，我不是故意的”。"}, {"id": "c", "text": "假装什么都没发生。"}], "subject": "social", "difficulty": "quick", "explanation": "说错话就大方道歉，承认错误的孩子最让人喜欢。"}, {"id": "low-social-b2-021", "band": "low", "answer": "a", "prompt": "小组一起画大海报，每个人画一部分。你画得很快，怎样做最好？", "choices": [{"id": "a", "text": "看看还能帮谁，让海报更漂亮。"}, {"id": "b", "text": "嫌别人画得慢，催个不停。"}, {"id": "c", "text": "自己画完就玩别的。"}], "subject": "social", "difficulty": "deep", "explanation": "团队合作时主动帮忙，大家一起把事情做好，比一个人快更重要。"}, {"id": "low-social-b2-022", "band": "low", "answer": "b", "prompt": "同学不小心踩到你的脚，马上说“对不起”。你怎么回最大方？", "choices": [{"id": "a", "text": "也故意踩他一脚。"}, {"id": "b", "text": "说“没关系，我没事”。"}, {"id": "c", "text": "哼一声不理他。"}], "subject": "social", "difficulty": "quick", "explanation": "别人真心道歉了，大方说“没关系”，事情就过去啦，谁都不难受。"}, {"id": "low-social-b2-023", "band": "low", "answer": "b", "prompt": "你想加入同学们正在玩的游戏，怎么开口最好？", "choices": [{"id": "a", "text": "站旁边生闷气。"}, {"id": "b", "text": "礼貌地问“我可以一起玩吗”。"}, {"id": "c", "text": "直接挤进去打乱他们。"}], "subject": "social", "difficulty": "quick", "explanation": "礼貌地问一句，大家通常都会欢迎你加入。"}, {"id": "low-social-b2-024", "band": "low", "answer": "a", "prompt": "班里要选小组长，你很想当，但好朋友也想当。最好怎么做？", "choices": [{"id": "a", "text": "大大方方一起参选，谁当上都为对方高兴。"}, {"id": "b", "text": "偷偷说朋友的坏话。"}, {"id": "c", "text": "威胁朋友不许参加。"}], "subject": "social", "difficulty": "deep", "explanation": "公平竞争、为朋友的成功高兴，是真正的好朋友。"}, {"id": "low-social-b2-025", "band": "low", "answer": "c", "prompt": "同学把秘密悄悄告诉了你，让你别说出去。你应该？", "choices": [{"id": "a", "text": "用秘密换好处。"}, {"id": "b", "text": "赶紧告诉全班。"}, {"id": "c", "text": "替他保守秘密，不到处说。"}], "subject": "social", "difficulty": "deep", "explanation": "答应了帮人保守秘密就要做到，这样同学才会信任你。"}, {"id": "low-social-b2-026", "band": "low", "answer": "b", "prompt": "操场上你看到一个小同学摔倒了，膝盖有点疼。你会？", "choices": [{"id": "a", "text": "绕开继续跑。"}, {"id": "b", "text": "过去扶他起来，问他要不要找老师。"}, {"id": "c", "text": "笑他走路不看路。"}], "subject": "social", "difficulty": "quick", "explanation": "看到有人受伤主动帮忙、必要时找老师，是关心别人的好孩子。"}, {"id": "low-social-b2-027", "band": "low", "answer": "b", "prompt": "你和同桌都喜欢同一个橡皮，正好商店只剩一个。比较好的做法是？", "choices": [{"id": "a", "text": "吵到老师那里去。"}, {"id": "b", "text": "商量一下，让更需要的人买，或者一起想别的办法。"}, {"id": "c", "text": "抢着去买，谁慢谁没有。"}], "subject": "social", "difficulty": "deep", "explanation": "遇到都想要的东西，好好商量比争抢更能让两个人都满意。"}, {"id": "low-social-b2-028", "band": "low", "answer": "b", "prompt": "上课分到一组的同学你不太熟，有点不好意思说话。怎么做最好？", "choices": [{"id": "a", "text": "一直低头不出声。"}, {"id": "b", "text": "笑着说“你好，我们一起加油吧”。"}, {"id": "c", "text": "要求换组。"}], "subject": "social", "difficulty": "quick", "explanation": "主动打个招呼，陌生的同学也会慢慢变成朋友。"}, {"id": "low-social-b2-029", "band": "low", "answer": "c", "prompt": "你不小心弄脏了同学的本子，他很难过。最好怎么做？", "choices": [{"id": "a", "text": "偷偷把本子塞回去。"}, {"id": "b", "text": "说“又不是故意的，有什么大不了”。"}, {"id": "c", "text": "道歉，并帮他把脏的地方擦干净或一起想办法补救。"}], "subject": "social", "difficulty": "deep", "explanation": "先道歉再帮忙补救，比找借口更能让同学原谅你。"}, {"id": "low-social-b2-030", "band": "low", "answer": "b", "prompt": "班里大扫除，老师让大家分工。你最该怎么做？", "choices": [{"id": "a", "text": "躲到一边玩。"}, {"id": "b", "text": "主动认领一份，认真把自己的活儿做好。"}, {"id": "c", "text": "挑最轻松的，重活让别人干。"}], "subject": "social", "difficulty": "quick", "explanation": "集体的事大家一起出力，认真做好自己那份，班级才会又干净又团结。"}, {"id": "high-social-b2-001", "band": "high", "answer": "c", "prompt": "你发现要好的朋友最近总和别的同学一起玩，冷落了你，心里有点酸。最成熟的做法是？", "choices": [{"id": "a", "text": "赌气也去交别的朋友，再也不理他。"}, {"id": "b", "text": "在背后说那个新朋友的坏话。"}, {"id": "c", "text": "找机会真诚地说说自己的感受，也理解朋友可以有别的朋友。"}], "subject": "social", "difficulty": "deep", "explanation": "坦诚表达感受、同时尊重朋友交往的自由，友谊才能长久；占有欲只会推远对方。"}, {"id": "high-social-b2-002", "band": "high", "answer": "c", "prompt": "小组作业里有个同学几乎没出力，但展示时却抢着说“都是我做的”。比较聪明的处理是？", "choices": [{"id": "a", "text": "忍气吞声，以后再也不和他一组。"}, {"id": "b", "text": "当场翻脸骂他不要脸。"}, {"id": "c", "text": "事后心平气和地和他谈，也可以让老师了解真实的分工。"}], "subject": "social", "difficulty": "deep", "explanation": "既要维护公平，也要讲方式：私下沟通加上让老师了解事实，比当众爆发更体面有效。"}, {"id": "high-social-b2-003", "band": "high", "answer": "b", "prompt": "你无意中听到两个同学在议论你“有点小气”。你心里很不舒服，最好的态度是？", "choices": [{"id": "a", "text": "立刻冲过去质问他们。"}, {"id": "b", "text": "先冷静想想是否真有值得改的地方，也可以找合适机会问问他们。"}, {"id": "c", "text": "从此把他们当敌人。"}], "subject": "social", "difficulty": "deep", "explanation": "听到不中听的话先别炸，理性地分辨是误会还是提醒，反而能让自己成长。"}, {"id": "high-social-b2-004", "band": "high", "answer": "c", "prompt": "朋友考试没考好，跑来跟你哭。这时最贴心的回应是？", "choices": [{"id": "a", "text": "说“这有什么好哭的，下次努力就行了”。"}, {"id": "b", "text": "赶紧讲一堆大道理让他别难过。"}, {"id": "c", "text": "先安静地陪着、认真听他说，再轻声安慰和鼓励。"}], "subject": "social", "difficulty": "deep", "explanation": "难过的人最需要被倾听和接纳，先共情再鼓励，比急着讲道理更能安慰人。"}, {"id": "high-social-b2-005", "band": "high", "answer": "a", "prompt": "同学开玩笑给你起了个不太好听的外号，叫得你越来越烦。怎么处理最得体？", "choices": [{"id": "a", "text": "认真地告诉他“这个外号我不喜欢，请不要再叫了”。"}, {"id": "b", "text": "也给他起个更难听的外号还击。"}, {"id": "c", "text": "什么都不说，自己生闷气。"}], "subject": "social", "difficulty": "deep", "explanation": "清楚而坚定地表达自己的边界，比报复或憋着更有效，也让对方知道你的底线。"}, {"id": "high-social-b2-006", "band": "high", "answer": "a", "prompt": "你答应了帮同学带一本书，结果忘在家里了，他今天正好要用。最负责的做法是？", "choices": [{"id": "a", "text": "诚恳道歉，说明情况，并想办法补救（比如明天一定带来或帮他借）。"}, {"id": "b", "text": "找个借口说书找不到了。"}, {"id": "c", "text": "假装忘了这回事。"}], "subject": "social", "difficulty": "deep", "explanation": "没做到承诺时，诚实道歉加上积极补救，才能维护别人对你的信任。"}, {"id": "high-social-b2-007", "band": "high", "answer": "b", "prompt": "班里有个同学常被大家孤立，没人愿意和他同组。你能做的最有意义的事是？", "choices": [{"id": "a", "text": "假装关心，背地里还是嫌弃。"}, {"id": "b", "text": "主动接纳他、和他说说话，看看能不能化解大家的偏见。"}, {"id": "c", "text": "也跟着大家一起远离他。"}], "subject": "social", "difficulty": "deep", "explanation": "敢于善待被孤立的人，需要勇气，也最能体现一个人的善良和领导力。"}, {"id": "high-social-b2-008", "band": "high", "answer": "b", "prompt": "两个好朋友因为一场误会闹翻了，都来找你诉苦、希望你站在自己一边。你最该做的是？", "choices": [{"id": "a", "text": "果断站队，帮一个去对付另一个。"}, {"id": "b", "text": "两边都耐心听，帮他们把误会说清楚，而不是评判谁对谁错。"}, {"id": "c", "text": "把两人说的话互相转告，火上浇油。"}], "subject": "social", "difficulty": "deep", "explanation": "夹在中间不轻易站队，做沟通的桥梁帮双方化解误会，才是真正帮了他们。"}, {"id": "high-social-b2-009", "band": "high", "answer": "c", "prompt": "小组讨论时你的方案没被采纳，大家选了别人的。比较成熟的反应是？", "choices": [{"id": "a", "text": "赌气说“那你们爱怎样怎样”，不再参与。"}, {"id": "b", "text": "暗中希望这个方案失败。"}, {"id": "c", "text": "接受结果，认真把选定的方案做好，下次再争取。"}], "subject": "social", "difficulty": "deep", "explanation": "想法没被采纳是常事，顾全大局、继续投入，比闹情绪更显成熟和担当。"}, {"id": "high-social-b2-010", "band": "high", "answer": "c", "prompt": "考试时同桌悄悄递纸条让你给他看答案，你不想这么做又怕伤感情。最好的回应是？", "choices": [{"id": "a", "text": "假装没看见，让他干着急。"}, {"id": "b", "text": "勉强给他看，下不为例。"}, {"id": "c", "text": "小声而坚定地拒绝，课后可以约他一起复习。"}], "subject": "social", "difficulty": "deep", "explanation": "作弊既害自己也害对方，坚定拒绝再提出正当的帮助，才是真正为朋友好。"}, {"id": "high-social-b2-011", "band": "high", "answer": "b", "prompt": "你想夸一个同学，但又怕显得假。下面哪句夸奖最真诚？", "choices": [{"id": "a", "text": "你真厉害，什么都会。"}, {"id": "b", "text": "你刚才讲题的思路特别清楚，我一下就听懂了。"}, {"id": "c", "text": "你比别人强多了。"}], "subject": "social", "difficulty": "deep", "explanation": "具体地说出对方好在哪里，比空泛的“你真棒”更真诚，也更让人受用。"}, {"id": "high-social-b2-012", "band": "high", "answer": "b", "prompt": "网上有人匿名说了一些很伤人的话攻击你。更明智的做法是？", "choices": [{"id": "a", "text": "反复看那些话，越想越难受。"}, {"id": "b", "text": "不被牵着走，必要时截图保存、告诉家长或老师。"}, {"id": "c", "text": "用更狠的话骂回去。"}], "subject": "social", "difficulty": "deep", "explanation": "对网络恶意不必硬碰硬，保留证据、寻求大人帮助，比对骂更能保护自己。"}, {"id": "high-social-b2-013", "band": "high", "answer": "c", "prompt": "你和同学约好一起完成手抄报，他却临时说不来了，你一个人忙不过来。比较好的做法是？", "choices": [{"id": "a", "text": "故意把他那部分做得很差。"}, {"id": "b", "text": "以后再也不和他合作，也不告诉他你的不满。"}, {"id": "c", "text": "先把手头的做完，再找机会让他知道你的难处，约下次提前说。"}], "subject": "social", "difficulty": "deep", "explanation": "先把事情扛下来，再坦诚沟通而不是冷暴力，才能既完成任务又改善关系。"}, {"id": "high-social-b2-014", "band": "high", "answer": "b", "prompt": "和同学讨论问题时，你发现自己之前的看法其实是错的。最有风度的做法是？", "choices": [{"id": "a", "text": "嘴硬到底，绝不认输。"}, {"id": "b", "text": "大方承认“你说得对，是我刚才想错了”。"}, {"id": "c", "text": "转移话题，假装没这回事。"}], "subject": "social", "difficulty": "deep", "explanation": "敢于承认自己错了，不是丢脸，反而会让别人更尊重你。"}, {"id": "high-social-b2-015", "band": "high", "answer": "c", "prompt": "集体活动时，有同学提议的玩法你觉得不太安全。怎么表达最合适？", "choices": [{"id": "a", "text": "直接说“这主意太蠢了”。"}, {"id": "b", "text": "不说话，但偷偷不参加。"}, {"id": "c", "text": "说出你的担心，并提一个更安全的替代办法。"}], "subject": "social", "difficulty": "deep", "explanation": "反对别人时对事不对人，提出担忧加上更好的建议，既被人接受又解决了问题。"}, {"id": "high-social-b2-016", "band": "high", "answer": "a", "prompt": "你借了同学的笔记，约好周一还，可周一你忘带了。当他来问时，你最该？", "choices": [{"id": "a", "text": "诚恳道歉，明确告诉他明天一定带来。"}, {"id": "b", "text": "反过来怪他催得太急。"}, {"id": "c", "text": "不耐烦地说“等我想起来再说”。"}], "subject": "social", "difficulty": "quick", "explanation": "没按约定办事，态度诚恳并给出明确的解决时间，才能让人放心继续信任你。"}, {"id": "high-social-b2-017", "band": "high", "answer": "c", "prompt": "班级活动需要有人负责一件没人愿意干的杂事。你正好有空，最有担当的做法是？", "choices": [{"id": "a", "text": "也跟着低头，假装没听见。"}, {"id": "b", "text": "等老师点名才勉强答应。"}, {"id": "c", "text": "主动站出来说“我来吧”。"}], "subject": "social", "difficulty": "quick", "explanation": "在大家都退缩时主动承担，是责任心和集体精神的体现，也会赢得信任。"}, {"id": "high-social-b2-018", "band": "high", "answer": "c", "prompt": "你发现自己冤枉了一个同学，以为是他弄坏了你的东西，其实不是。该怎么办？", "choices": [{"id": "a", "text": "找别的理由证明自己没错。"}, {"id": "b", "text": "反正没人知道，就不提了。"}, {"id": "c", "text": "主动向他道歉，把误会说清楚。"}], "subject": "social", "difficulty": "deep", "explanation": "冤枉了人就要主动澄清和道歉，这样既还了对方清白，也维护了你的信誉。"}, {"id": "high-social-b2-019", "band": "high", "answer": "a", "prompt": "和想法跟你很不一样的同学相处时，最重要的是什么？", "choices": [{"id": "a", "text": "尊重彼此的不同，求同存异。"}, {"id": "b", "text": "想方设法让他同意你。"}, {"id": "c", "text": "觉得他和你不一样就疏远他。"}], "subject": "social", "difficulty": "deep", "explanation": "人和人本来就不同，懂得尊重差异、求同存异，才能交到各种各样的朋友。"}, {"id": "high-social-b2-020", "band": "high", "answer": "b", "prompt": "在公共场合，你的手机响了。比较得体的接电话方式是？", "choices": [{"id": "a", "text": "一直响着不管，让它吵。"}, {"id": "b", "text": "走到不打扰别人的地方，小声接。"}, {"id": "c", "text": "就地大声接，旁若无人。"}], "subject": "social", "difficulty": "quick", "explanation": "在公共场合接电话时顾及周围人，是有教养的表现。"}, {"id": "high-social-b2-021", "band": "high", "answer": "b", "prompt": "同学请你帮一个忙，但你确实做不到。怎么回应最好？", "choices": [{"id": "a", "text": "找借口拖着，不给明确答复。"}, {"id": "b", "text": "坦诚说明自己为什么帮不了，并尽量给他别的建议。"}, {"id": "c", "text": "硬着头皮答应，最后办砸。"}], "subject": "social", "difficulty": "deep", "explanation": "帮不了就如实说，并尽力指条别的路，比勉强答应或含糊其辞更可靠。"}, {"id": "high-social-b2-022", "band": "high", "answer": "a", "prompt": "别人正认真和你说话，你想让对方感到你在用心听。下面哪种做法最好？", "choices": [{"id": "a", "text": "看着对方，适时点头或回应，不随便打断。"}, {"id": "b", "text": "一边玩手机一边“嗯嗯”。"}, {"id": "c", "text": "还没听完就急着说自己的事。"}], "subject": "social", "difficulty": "quick", "explanation": "专注地看着对方、适当回应、不打断，是倾听最基本也最重要的尊重。"}, {"id": "high-social-b2-023", "band": "high", "answer": "b", "prompt": "你和好朋友因为一点小事冷战了好几天，其实都想和好。最勇敢的一步是？", "choices": [{"id": "a", "text": "故意在他面前和别人玩得很开心。"}, {"id": "b", "text": "主动找他说“那天的事我也有不对，我们别冷战了”。"}, {"id": "c", "text": "继续憋着，等对方先低头。"}], "subject": "social", "difficulty": "deep", "explanation": "主动打破僵局、先认下自己的不对，需要勇气，却是修复友谊最快的办法。"}, {"id": "high-social-b2-024", "band": "high", "answer": "a", "prompt": "同学之间起了争执，对方情绪很激动、说话也冲。比较冷静的做法是？", "choices": [{"id": "a", "text": "先让自己冷静，等对方气消一点再好好谈。"}, {"id": "b", "text": "立刻喊来一群人帮自己。"}, {"id": "c", "text": "用同样冲的语气顶回去。"}], "subject": "social", "difficulty": "deep", "explanation": "对方在气头上时火上浇油只会更糟，先稳住情绪再沟通，更容易解决问题。"}, {"id": "high-social-b2-025", "band": "high", "answer": "c", "prompt": "你发现班上有同学在偷偷传别人的谣言。你该怎么做最合适？", "choices": [{"id": "a", "text": "假装不知道，反正不关自己事。"}, {"id": "b", "text": "跟着一起传，觉得很有意思。"}, {"id": "c", "text": "不参与，并提醒大家“没核实的话别乱传”。"}], "subject": "social", "difficulty": "deep", "explanation": "不传谣、并劝阻别人传谣，是保护同学、维护班级氛围的正确做法。"}, {"id": "high-social-b2-026", "band": "high", "answer": "c", "prompt": "老师当众表扬了一个同学，而你做了同样的事却没被提到，有点失落。成熟的想法是？", "choices": [{"id": "a", "text": "去跟老师抱怨为什么没夸自己。"}, {"id": "b", "text": "觉得老师偏心，从此不努力了。"}, {"id": "c", "text": "为同学高兴，相信自己的努力终会被看见。"}], "subject": "social", "difficulty": "deep", "explanation": "不必事事都要被表扬，真心为别人高兴、踏实做事，心态更健康也更受欢迎。"}, {"id": "high-social-b2-027", "band": "high", "answer": "b", "prompt": "朋友向你倾诉了一件让他很难为情的私事，并嘱咐你保密。你应该？", "choices": [{"id": "a", "text": "当成八卦讲给别人听。"}, {"id": "b", "text": "替他守口如瓶，不向任何人提起。"}, {"id": "c", "text": "看心情决定要不要说。"}], "subject": "social", "difficulty": "deep", "explanation": "被信任地托付秘密时守住承诺，是一个值得深交的人最重要的品质。"}, {"id": "high-social-b2-028", "band": "high", "answer": "a", "prompt": "你和同学合作时，他的做法和你不同，但其实也能完成任务。比较好的态度是？", "choices": [{"id": "a", "text": "尊重他的方式，只要能把事做好就行。"}, {"id": "b", "text": "私下抱怨他不听话。"}, {"id": "c", "text": "非要他按你的方法来不可。"}], "subject": "social", "difficulty": "deep", "explanation": "合作不是要求别人完全照自己来，包容不同的做法，团队才更顺畅。"}, {"id": "high-social-b2-029", "band": "high", "answer": "a", "prompt": "同学因为一次失误自责得很厉害，觉得自己很差劲。你想安慰他，哪句最好？", "choices": [{"id": "a", "text": "谁都会犯错，这一次不代表你这个人不好。"}, {"id": "b", "text": "早跟你说过会出问题吧。"}, {"id": "c", "text": "是啊，你这次确实搞砸了。"}], "subject": "social", "difficulty": "deep", "explanation": "把“这件事没做好”和“这个人不好”分开，能帮朋友走出自责、重拾信心。"}, {"id": "high-social-b2-030", "band": "high", "answer": "c", "prompt": "你在群里看到大家都在嘲笑某个同学发的照片。你不想伤害他，最好怎么做？", "choices": [{"id": "a", "text": "跟着发几个嘲笑的表情。"}, {"id": "b", "text": "把照片转给更多人看热闹。"}, {"id": "c", "text": "不附和，私下问问那位同学还好吗。"}], "subject": "social", "difficulty": "deep", "explanation": "不随大流嘲笑、私下给予关心，是在网络上也守住善良的表现。"}, {"id": "low-interest-b2-001", "band": "low", "answer": "c", "prompt": "小熊猫宝宝刚出生的时候，身上几乎没有黑白花纹，颜色主要是什么样的？", "choices": [{"id": "a", "text": "一身绿色。"}, {"id": "b", "text": "全身黑白分明。"}, {"id": "c", "text": "几乎是粉粉的，毛很少。"}], "subject": "interest", "difficulty": "quick", "explanation": "刚出生的大熊猫宝宝是粉红色的、毛很稀，过一段时间才慢慢长出黑白花纹。"}, {"id": "low-interest-b2-002", "band": "low", "answer": "a", "prompt": "长颈鹿的脖子那么长，它睡觉的时候大多是怎么睡的？", "choices": [{"id": "a", "text": "站着打个盹儿，睡得很少。"}, {"id": "b", "text": "挂在树上睡。"}, {"id": "c", "text": "躺平睡一整天。"}], "subject": "interest", "difficulty": "quick", "explanation": "长颈鹿在野外很警惕，常常站着打盹，每天睡的时间很短。"}, {"id": "low-interest-b2-003", "band": "low", "answer": "a", "prompt": "蜜蜂回到蜂巢，会用一种特别的方式告诉同伴花在哪里。它靠的是什么？", "choices": [{"id": "a", "text": "跳一种“舞蹈”。"}, {"id": "b", "text": "画一张地图。"}, {"id": "c", "text": "大声喊话。"}], "subject": "interest", "difficulty": "deep", "explanation": "蜜蜂会用“摇摆舞”告诉同伴花蜜的方向和远近，真神奇！"}, {"id": "low-interest-b2-004", "band": "low", "answer": "a", "prompt": "星星看起来一闪一闪的，可天上有一颗特别大、白天我们能感觉到它的“星星”，它是？", "choices": [{"id": "a", "text": "太阳。"}, {"id": "b", "text": "月亮。"}, {"id": "c", "text": "路灯。"}], "subject": "interest", "difficulty": "quick", "explanation": "太阳其实也是一颗恒星，是离我们最近的一颗，白天给我们光和温暖。"}, {"id": "low-interest-b2-005", "band": "low", "answer": "a", "prompt": "大大的恐龙里，有一种脖子特别长、专门吃高处树叶的，它最可能吃什么？", "choices": [{"id": "a", "text": "高高的树叶。"}, {"id": "b", "text": "石头。"}, {"id": "c", "text": "小动物的肉。"}], "subject": "interest", "difficulty": "quick", "explanation": "像长颈一样的恐龙脖子很长，正好够到高高的树叶来吃。"}, {"id": "low-interest-b2-006", "band": "low", "answer": "c", "prompt": "海里的章鱼遇到危险时，常常会喷出一种东西然后逃走。那是什么？", "choices": [{"id": "a", "text": "泡泡糖。"}, {"id": "b", "text": "小石头。"}, {"id": "c", "text": "黑黑的墨汁。"}], "subject": "interest", "difficulty": "quick", "explanation": "章鱼会喷出黑墨汁，把水弄黑，趁敌人看不清就赶紧逃跑。"}, {"id": "low-interest-b2-007", "band": "low", "answer": "a", "prompt": "向日葵有个有趣的本领，白天它的大花盘会怎么动？", "choices": [{"id": "a", "text": "一直朝着太阳转。"}, {"id": "b", "text": "转圈圈跳舞。"}, {"id": "c", "text": "一直朝下看。"}], "subject": "interest", "difficulty": "quick", "explanation": "向日葵的花盘在生长时会跟着太阳转，所以才叫“向日葵”。"}, {"id": "low-interest-b2-008", "band": "low", "answer": "a", "prompt": "敲鼓的时候，鼓为什么会发出“咚咚”的声音？", "choices": [{"id": "a", "text": "因为鼓面在抖动。"}, {"id": "b", "text": "因为鼓里有小人在喊。"}, {"id": "c", "text": "因为鼓饿了。"}], "subject": "interest", "difficulty": "deep", "explanation": "敲鼓时鼓面会快速振动，振动让空气也跟着动，我们就听到了声音。"}, {"id": "low-interest-b2-009", "band": "low", "answer": "a", "prompt": "把蓝色和黄色的颜料调在一起，会变成什么颜色？", "choices": [{"id": "a", "text": "绿色。"}, {"id": "b", "text": "黑色。"}, {"id": "c", "text": "白色。"}], "subject": "interest", "difficulty": "quick", "explanation": "蓝加黄会变成绿色，就像春天的小草一样，颜色真奇妙。"}, {"id": "low-interest-b2-010", "band": "low", "answer": "c", "prompt": "世界上最大的动物，住在海里，比好几头大象还重，它是？", "choices": [{"id": "a", "text": "小金鱼。"}, {"id": "b", "text": "海星。"}, {"id": "c", "text": "蓝鲸。"}], "subject": "interest", "difficulty": "quick", "explanation": "蓝鲸是地球上最大的动物，光是它的心脏就比小朋友还大呢。"}, {"id": "low-interest-b2-011", "band": "low", "answer": "c", "prompt": "下雨过后，天上有时会出现一座七彩的“桥”，它叫什么？", "choices": [{"id": "a", "text": "烟花。"}, {"id": "b", "text": "云朵。"}, {"id": "c", "text": "彩虹。"}], "subject": "interest", "difficulty": "quick", "explanation": "雨后阳光照在小水珠上，就会出现漂亮的彩虹。"}, {"id": "low-interest-b2-012", "band": "low", "answer": "a", "prompt": "萤火虫在夜里一闪一闪发光，它发光主要是为了？", "choices": [{"id": "a", "text": "找小伙伴、交朋友。"}, {"id": "b", "text": "给我们照路。"}, {"id": "c", "text": "取暖。"}], "subject": "interest", "difficulty": "deep", "explanation": "萤火虫尾巴会发光，主要是用闪光来吸引同伴，找到自己的好朋友。"}, {"id": "low-interest-b2-013", "band": "low", "answer": "b", "prompt": "小猫的胡子可不是用来好看的，它最大的用处是？", "choices": [{"id": "a", "text": "当吸管喝水。"}, {"id": "b", "text": "帮它感觉东西、量缝隙宽不宽。"}, {"id": "c", "text": "用来扫地。"}], "subject": "interest", "difficulty": "deep", "explanation": "猫的胡子很灵敏，能帮它感知周围，判断能不能钻过一个缝。"}, {"id": "low-interest-b2-014", "band": "low", "answer": "a", "prompt": "蜗牛走过的地方，常常会留下一条亮亮的痕迹，那是什么？", "choices": [{"id": "a", "text": "它分泌的黏液。"}, {"id": "b", "text": "颜料。"}, {"id": "c", "text": "小水洼。"}], "subject": "interest", "difficulty": "quick", "explanation": "蜗牛爬行时会分泌黏液，帮自己滑动，留下一条亮亮的“路”。"}, {"id": "low-interest-b2-015", "band": "low", "answer": "b", "prompt": "小鸟会飞，是因为它身上有什么帮了大忙？", "choices": [{"id": "a", "text": "很重的石头。"}, {"id": "b", "text": "轻轻的羽毛和翅膀。"}, {"id": "c", "text": "长长的尾巴。"}], "subject": "interest", "difficulty": "quick", "explanation": "小鸟的身体很轻，加上有翅膀和羽毛，所以能飞上天空。"}, {"id": "low-interest-b2-016", "band": "low", "answer": "a", "prompt": "小朋友吹的肥皂泡泡，为什么看起来花花的、有好多颜色？", "choices": [{"id": "a", "text": "因为薄薄的泡泡膜把光变出了颜色。"}, {"id": "b", "text": "因为它生气了。"}, {"id": "c", "text": "因为里面装了颜料。"}], "subject": "interest", "difficulty": "deep", "explanation": "泡泡膜薄薄的，阳光照上去会反出五颜六色，所以特别好看。"}, {"id": "low-interest-b2-017", "band": "low", "answer": "b", "prompt": "大象的长鼻子本领可大了，下面哪件事它做不到？", "choices": [{"id": "a", "text": "用鼻子喝水、卷东西。"}, {"id": "b", "text": "用鼻子写字。"}, {"id": "c", "text": "用鼻子闻味道。"}], "subject": "interest", "difficulty": "quick", "explanation": "大象的鼻子能喝水、卷东西、闻味道，但可不会写字哦。"}, {"id": "low-interest-b2-018", "band": "low", "answer": "a", "prompt": "在很黑的洞里，蝙蝠也能飞来飞去不撞墙，它靠的是什么？", "choices": [{"id": "a", "text": "发出声音，听回声找路。"}, {"id": "b", "text": "打开手电筒。"}, {"id": "c", "text": "闭着眼睛乱飞。"}], "subject": "interest", "difficulty": "deep", "explanation": "蝙蝠会发出我们听不见的声音，靠回声判断哪里有障碍，真聪明！"}, {"id": "low-interest-b2-019", "band": "low", "answer": "b", "prompt": "种子要发芽长成小苗，下面哪样东西它最需要？", "choices": [{"id": "a", "text": "巧克力。"}, {"id": "b", "text": "水和阳光。"}, {"id": "c", "text": "玩具。"}], "subject": "interest", "difficulty": "quick", "explanation": "种子有了水、阳光和泥土，就能发芽长大，变成绿绿的小苗。"}, {"id": "low-interest-b2-020", "band": "low", "answer": "c", "prompt": "小鸭子刚下水就会游泳，它脚上的什么帮了大忙？", "choices": [{"id": "a", "text": "脚是方形的。"}, {"id": "b", "text": "脚上穿了游泳圈。"}, {"id": "c", "text": "脚趾间有“蹼”，像小船桨。"}], "subject": "interest", "difficulty": "deep", "explanation": "鸭子脚上有蹼，像小桨一样划水，所以游得又快又稳。"}, {"id": "low-interest-b2-021", "band": "low", "answer": "a", "prompt": "世界上跑得最快的陆地动物，奔跑时像一道闪电，它是？", "choices": [{"id": "a", "text": "猎豹。"}, {"id": "b", "text": "蜗牛。"}, {"id": "c", "text": "乌龟。"}], "subject": "interest", "difficulty": "quick", "explanation": "猎豹是陆地上跑得最快的动物，冲刺起来快得像箭一样。"}, {"id": "low-interest-b2-022", "band": "low", "answer": "c", "prompt": "画画时想画出晚上的天空，涂什么颜色最合适？", "choices": [{"id": "a", "text": "亮黄色。"}, {"id": "b", "text": "大红色。"}, {"id": "c", "text": "深蓝色或黑色。"}], "subject": "interest", "difficulty": "quick", "explanation": "夜晚的天空又深又暗，用深蓝或黑色来涂，再点上小星星就更像啦。"}, {"id": "low-interest-b2-023", "band": "low", "answer": "a", "prompt": "刺猬遇到危险的时候，会做出什么动作来保护自己？", "choices": [{"id": "a", "text": "缩成一个带刺的小球。"}, {"id": "b", "text": "钻进水里游走。"}, {"id": "c", "text": "飞到天上去。"}], "subject": "interest", "difficulty": "quick", "explanation": "刺猬会把身体缩成一团，浑身的刺朝外，敌人就不敢碰它了。"}, {"id": "low-interest-b2-024", "band": "low", "answer": "a", "prompt": "我们脚下的地球，它一直在做一件事，所以才有了白天和黑夜。它在？", "choices": [{"id": "a", "text": "不停地自己转圈。"}, {"id": "b", "text": "待着不动。"}, {"id": "c", "text": "上下蹦。"}], "subject": "interest", "difficulty": "deep", "explanation": "地球一直在自己转动，转到太阳照到的一面是白天，背着太阳的一面是黑夜。"}, {"id": "low-interest-b2-025", "band": "low", "answer": "a", "prompt": "小螃蟹走路有个很特别的地方，它是怎么走的？", "choices": [{"id": "a", "text": "横着走。"}, {"id": "b", "text": "飞着走。"}, {"id": "c", "text": "倒着跳。"}], "subject": "interest", "difficulty": "quick", "explanation": "螃蟹的腿长在身体两边，所以它走起路来是横着走的。"}, {"id": "low-interest-b2-026", "band": "low", "answer": "a", "prompt": "钢琴上有一排黑白相间的，我们用手按它就会发出声音，那叫什么？", "choices": [{"id": "a", "text": "琴键。"}, {"id": "b", "text": "门把手。"}, {"id": "c", "text": "积木。"}], "subject": "interest", "difficulty": "quick", "explanation": "钢琴上黑白的小条叫琴键，按下去就能弹出好听的音乐。"}, {"id": "low-interest-b2-027", "band": "low", "answer": "b", "prompt": "小松鼠在秋天会做一件很勤快的事，为冬天做准备。它在？", "choices": [{"id": "a", "text": "盖房子。"}, {"id": "b", "text": "把松果、坚果藏起来当存粮。"}, {"id": "c", "text": "织毛衣。"}], "subject": "interest", "difficulty": "deep", "explanation": "松鼠会把坚果藏在很多地方，等冬天没吃的时候再挖出来。"}, {"id": "low-interest-b2-028", "band": "low", "answer": "c", "prompt": "红色和白色的颜料调在一起，会变成什么颜色？", "choices": [{"id": "a", "text": "黑色。"}, {"id": "b", "text": "蓝色。"}, {"id": "c", "text": "粉红色。"}], "subject": "interest", "difficulty": "quick", "explanation": "红色里加上白色，就会变成甜甜的粉红色，像棉花糖一样。"}, {"id": "low-interest-b2-029", "band": "low", "answer": "b", "prompt": "青蛙的舌头有个厉害的本领，它是怎么抓虫子的？", "choices": [{"id": "a", "text": "等虫子自己飞进嘴里。"}, {"id": "b", "text": "舌头又长又黏，一下子弹出去粘住虫子。"}, {"id": "c", "text": "用手去抓。"}], "subject": "interest", "difficulty": "deep", "explanation": "青蛙的舌头又长又黏，能快速弹出去把小虫子粘回嘴里。"}, {"id": "low-interest-b2-030", "band": "low", "answer": "c", "prompt": "我们看到的雪是白白的，可一片片小雪花其实是什么形状的？", "choices": [{"id": "a", "text": "方方的盒子。"}, {"id": "b", "text": "圆圆的球。"}, {"id": "c", "text": "六个角的小花朵形状。"}], "subject": "interest", "difficulty": "deep", "explanation": "每一片雪花都是六个角的，像小小的花，而且几乎没有完全一样的。"}, {"id": "high-interest-b2-001", "band": "high", "answer": "a", "prompt": "章鱼的血液是什么颜色的？这和我们人类很不一样。", "choices": [{"id": "a", "text": "蓝色的。"}, {"id": "b", "text": "和我们一样是红色的。"}, {"id": "c", "text": "绿色的。"}], "subject": "interest", "difficulty": "deep", "explanation": "章鱼血液靠含铜的“血蓝蛋白”运输氧气，所以是蓝色的，而人类靠含铁的血红蛋白，是红色的。"}, {"id": "high-interest-b2-002", "band": "high", "answer": "a", "prompt": "我们看到的太阳光其实“迟到”了一会儿。阳光从太阳到地球大约要走多久？", "choices": [{"id": "a", "text": "差不多8分钟。"}, {"id": "b", "text": "不到1秒。"}, {"id": "c", "text": "整整一天。"}], "subject": "interest", "difficulty": "deep", "explanation": "光速很快，但太阳离我们约1.5亿公里，阳光也要走大约8分钟才到地球。"}, {"id": "high-interest-b2-003", "band": "high", "answer": "c", "prompt": "很多人以为霸王龙最大，其实有更大的食肉恐龙。下面哪种说法更准确？", "choices": [{"id": "a", "text": "所有恐龙都吃肉。"}, {"id": "b", "text": "霸王龙是历史上唯一的食肉恐龙。"}, {"id": "c", "text": "还有像棘龙这样体型可能更大的食肉恐龙。"}], "subject": "interest", "difficulty": "deep", "explanation": "棘龙等一些食肉恐龙体型可能比霸王龙还大，恐龙世界里食肉、食草的种类都很多。"}, {"id": "high-interest-b2-004", "band": "high", "answer": "c", "prompt": "深海里漆黑一片，有些鱼却能自己“发光”。这种本领叫什么？", "choices": [{"id": "a", "text": "夜视眼镜。"}, {"id": "b", "text": "反光板。"}, {"id": "c", "text": "生物发光。"}], "subject": "interest", "difficulty": "deep", "explanation": "很多深海生物能通过体内的化学反应发光，叫“生物发光”，用来诱捕猎物或交流。"}, {"id": "high-interest-b2-005", "band": "high", "answer": "a", "prompt": "蜂蜜放很多年也很难变质，这主要是因为什么？", "choices": [{"id": "a", "text": "含糖极高、水分极少，细菌很难存活。"}, {"id": "b", "text": "蜂蜜里有防腐剂。"}, {"id": "c", "text": "蜂蜜冻成了冰。"}], "subject": "interest", "difficulty": "deep", "explanation": "蜂蜜含糖高、水分少，环境让细菌难以繁殖，所以密封保存能放很久。"}, {"id": "high-interest-b2-006", "band": "high", "answer": "b", "prompt": "我们听到的雷声和闪电几乎同时发生，却总是先看到闪电。这是因为？", "choices": [{"id": "a", "text": "闪电先发生，雷声后发生。"}, {"id": "b", "text": "光跑得比声音快很多。"}, {"id": "c", "text": "我们的眼睛比耳朵灵。"}], "subject": "interest", "difficulty": "deep", "explanation": "光速远快于声速，所以同时发生的闪电和雷声，我们总是先看到光、后听到声。"}, {"id": "high-interest-b2-007", "band": "high", "answer": "b", "prompt": "小提琴、二胡都靠琴弦振动发声。让同一根弦发出更高的音，常用的办法是？", "choices": [{"id": "a", "text": "把弦弄得更松。"}, {"id": "b", "text": "按住琴弦，让振动的部分变短。"}, {"id": "c", "text": "把弦弄得更粗。"}], "subject": "interest", "difficulty": "deep", "explanation": "弦越短、越紧、越细，音就越高。按弦缩短振动长度，就能拉出更高的音。"}, {"id": "high-interest-b2-008", "band": "high", "answer": "c", "prompt": "画家说的“三原色”（颜料），指的是哪三种？用它们能调出很多颜色。", "choices": [{"id": "a", "text": "黑、白、灰。"}, {"id": "b", "text": "金、银、铜。"}, {"id": "c", "text": "红、黄、蓝。"}], "subject": "interest", "difficulty": "quick", "explanation": "颜料的三原色是红、黄、蓝，两两相调能得到橙、绿、紫等丰富的颜色。"}, {"id": "high-interest-b2-009", "band": "high", "answer": "a", "prompt": "世界上最高的山峰珠穆朗玛峰，它的高度大约是多少？", "choices": [{"id": "a", "text": "约8800多米。"}, {"id": "b", "text": "约88000米。"}, {"id": "c", "text": "约800米。"}], "subject": "interest", "difficulty": "quick", "explanation": "珠穆朗玛峰高约8848米，是地球陆地上的最高峰。"}, {"id": "high-interest-b2-010", "band": "high", "answer": "a", "prompt": "变色龙会变色，很多人以为只是为了“隐身”。其实它变色还有一个重要作用是？", "choices": [{"id": "a", "text": "表达情绪、和同类“交流”。"}, {"id": "b", "text": "为了飞起来。"}, {"id": "c", "text": "为了发电。"}], "subject": "interest", "difficulty": "deep", "explanation": "变色龙变色不只是伪装，还和体温调节、表达情绪、向同类传递信号有关。"}, {"id": "high-interest-b2-011", "band": "high", "answer": "c", "prompt": "我们看到的月亮自己并不发光，那它的“光”是哪里来的？", "choices": [{"id": "a", "text": "月亮上有大灯。"}, {"id": "b", "text": "月亮内部在燃烧。"}, {"id": "c", "text": "反射太阳的光。"}], "subject": "interest", "difficulty": "quick", "explanation": "月亮本身不发光，我们看到的月光其实是它反射的太阳光。"}, {"id": "high-interest-b2-012", "band": "high", "answer": "a", "prompt": "乐谱上常见的“do re mi fa sol la si”，这一组叫什么？", "choices": [{"id": "a", "text": "音阶（七个基本唱名）。"}, {"id": "b", "text": "节拍。"}, {"id": "c", "text": "和弦。"}], "subject": "interest", "difficulty": "quick", "explanation": "do re mi fa sol la si 是七个基本唱名，组成一个音阶，是音乐的基础。"}, {"id": "high-interest-b2-013", "band": "high", "answer": "a", "prompt": "鸵鸟是世界上最大的鸟，但它有个“缺点”，下面哪个说法对？", "choices": [{"id": "a", "text": "虽然不会飞，但跑得非常快。"}, {"id": "b", "text": "它住在海里。"}, {"id": "c", "text": "它能飞得比老鹰还高。"}], "subject": "interest", "difficulty": "quick", "explanation": "鸵鸟太重不能飞，但腿很有力，奔跑时速可达约70公里，是跑步高手。"}, {"id": "high-interest-b2-014", "band": "high", "answer": "a", "prompt": "水在结冰时有个很特别的现象，和大多数东西相反。它会？", "choices": [{"id": "a", "text": "体积变大，所以冰能浮在水面上。"}, {"id": "b", "text": "完全不变。"}, {"id": "c", "text": "体积变小，沉到水底。"}], "subject": "interest", "difficulty": "deep", "explanation": "水结冰时体积变大、密度变小，所以冰会浮在水上，湖面才会从上往下结冰。"}, {"id": "high-interest-b2-015", "band": "high", "answer": "b", "prompt": "指南针总能指向南北，这是因为地球本身像一块巨大的什么？", "choices": [{"id": "a", "text": "电池。"}, {"id": "b", "text": "磁铁。"}, {"id": "c", "text": "镜子。"}], "subject": "interest", "difficulty": "deep", "explanation": "地球有磁场，像一块大磁铁，所以指南针的磁针会被它吸引、指向南北。"}, {"id": "high-interest-b2-016", "band": "high", "answer": "b", "prompt": "画画想表现“近处大、远处小”的真实感，用到的是什么道理？", "choices": [{"id": "a", "text": "把画纸折起来。"}, {"id": "b", "text": "近大远小的透视。"}, {"id": "c", "text": "颜色越多越好。"}], "subject": "interest", "difficulty": "deep", "explanation": "近大远小是透视的基本规律，按它来画，画面就有了空间和立体感。"}, {"id": "high-interest-b2-017", "band": "high", "answer": "c", "prompt": "蜻蜓的眼睛由成千上万只小眼组成，这种眼睛叫什么？", "choices": [{"id": "a", "text": "近视眼。"}, {"id": "b", "text": "独眼。"}, {"id": "c", "text": "复眼。"}], "subject": "interest", "difficulty": "deep", "explanation": "蜻蜓有“复眼”，由上万只小眼拼成，几乎能看到四面八方，捕食特别厉害。"}, {"id": "high-interest-b2-018", "band": "high", "answer": "b", "prompt": "在我们的太阳系里，体积最大的行星是哪一颗？", "choices": [{"id": "a", "text": "水星。"}, {"id": "b", "text": "木星。"}, {"id": "c", "text": "地球。"}], "subject": "interest", "difficulty": "quick", "explanation": "木星是太阳系里体积最大的行星，大到能装下一千多个地球。"}, {"id": "high-interest-b2-019", "band": "high", "answer": "c", "prompt": "乐器一般分成几大类。下面哪一组都属于“吹奏乐器”？", "choices": [{"id": "a", "text": "鼓、锣。"}, {"id": "b", "text": "钢琴、小提琴。"}, {"id": "c", "text": "笛子、唢呐、长号。"}], "subject": "interest", "difficulty": "deep", "explanation": "靠吹气让空气振动发声的是吹奏乐器，如笛子、唢呐、长号；钢琴属键盘、鼓属打击乐。"}, {"id": "high-interest-b2-020", "band": "high", "answer": "b", "prompt": "骆驼能在沙漠里好几天不喝水，它背上的“驼峰”里主要存的是？", "choices": [{"id": "a", "text": "水。"}, {"id": "b", "text": "脂肪。"}, {"id": "c", "text": "沙子。"}], "subject": "interest", "difficulty": "deep", "explanation": "驼峰里存的主要是脂肪，需要时能转化成能量，并不是直接装水。"}, {"id": "high-interest-b2-021", "band": "high", "answer": "b", "prompt": "我们常说彩虹有七种颜色，按顺序排，最外圈（最上面）通常是哪种颜色？", "choices": [{"id": "a", "text": "绿色。"}, {"id": "b", "text": "红色。"}, {"id": "c", "text": "紫色。"}], "subject": "interest", "difficulty": "deep", "explanation": "彩虹颜色按红橙黄绿蓝靛紫排列，红色在最外圈、紫色在最里圈。"}, {"id": "high-interest-b2-022", "band": "high", "answer": "a", "prompt": "植物白天能自己“做饭”，把阳光变成养分。这个神奇的过程叫什么？", "choices": [{"id": "a", "text": "光合作用。"}, {"id": "b", "text": "呼吸作用。"}, {"id": "c", "text": "蒸发。"}], "subject": "interest", "difficulty": "quick", "explanation": "绿色植物靠光合作用，利用阳光把水和二氧化碳变成养分，还放出氧气。"}, {"id": "high-interest-b2-023", "band": "high", "answer": "b", "prompt": "水母全身大部分是水，没有心脏也没有大脑。它在水里前进靠的是？", "choices": [{"id": "a", "text": "装了小马达。"}, {"id": "b", "text": "伞状身体一张一缩，把水往后喷。"}, {"id": "c", "text": "长长的鳍划水。"}], "subject": "interest", "difficulty": "deep", "explanation": "水母靠伞状身体收缩、把水向后喷出来产生反作用力，从而向前移动。"}, {"id": "high-interest-b2-024", "band": "high", "answer": "b", "prompt": "五线谱上记录的主要是什么？它是世界通用的“音乐文字”。", "choices": [{"id": "a", "text": "乐器的价格。"}, {"id": "b", "text": "音的高低和长短等。"}, {"id": "c", "text": "歌词的意思。"}], "subject": "interest", "difficulty": "deep", "explanation": "五线谱用音符在五条线上的位置和形状，记录音的高低、长短等信息。"}, {"id": "high-interest-b2-025", "band": "high", "answer": "a", "prompt": "被称为“活化石”的银杏树，下面哪个说法是对的？", "choices": [{"id": "a", "text": "它存在的历史极其久远，和恐龙时代就有的种类很接近。"}, {"id": "b", "text": "它其实是一种动物。"}, {"id": "c", "text": "它是最近几十年才出现的新植物。"}], "subject": "interest", "difficulty": "deep", "explanation": "银杏出现得非常早，和远古时代的种类很相似，几乎没怎么变，所以被称为“活化石”。"}, {"id": "high-interest-b2-026", "band": "high", "answer": "c", "prompt": "声音在不同地方传播速度不一样。下面哪种环境里声音根本传不过去？", "choices": [{"id": "a", "text": "空气里。"}, {"id": "b", "text": "水里。"}, {"id": "c", "text": "没有空气的太空真空里。"}], "subject": "interest", "difficulty": "deep", "explanation": "声音要靠物质振动来传播，真空里没有介质，所以太空中其实是寂静无声的。"}, {"id": "high-interest-b2-027", "band": "high", "answer": "c", "prompt": "水滴形成的露珠、肥皂泡都接近圆球形，这背后有个力在起作用，它叫？", "choices": [{"id": "a", "text": "摩擦力。"}, {"id": "b", "text": "重力。"}, {"id": "c", "text": "表面张力。"}], "subject": "interest", "difficulty": "deep", "explanation": "液体表面张力会让水尽量收缩成表面积最小的形状，所以小水滴接近圆球。"}, {"id": "high-interest-b2-028", "band": "high", "answer": "b", "prompt": "用红色和蓝色颜料调在一起，会得到什么颜色？", "choices": [{"id": "a", "text": "绿色。"}, {"id": "b", "text": "紫色。"}, {"id": "c", "text": "白色。"}], "subject": "interest", "difficulty": "quick", "explanation": "红加蓝得到紫色，这是三原色两两相调出的间色之一。"}, {"id": "high-interest-b2-029", "band": "high", "answer": "c", "prompt": "被誉为“世界屋脊”的高原是哪一个？它平均海拔特别高。", "choices": [{"id": "a", "text": "黄土高原。"}, {"id": "b", "text": "内蒙古高原。"}, {"id": "c", "text": "青藏高原。"}], "subject": "interest", "difficulty": "deep", "explanation": "青藏高原平均海拔在4000米以上，是世界上海拔最高的高原，被称为“世界屋脊”。"}, {"id": "high-interest-b2-030", "band": "high", "answer": "b", "prompt": "陆地上跑得最快的动物是猎豹，那天空中飞得最快的鸟是哪种？", "choices": [{"id": "a", "text": "麻雀。"}, {"id": "b", "text": "游隼，俯冲时时速可超300公里。"}, {"id": "c", "text": "企鹅。"}], "subject": "interest", "difficulty": "quick", "explanation": "游隼俯冲捕猎时速度极快，可超过每小时300公里，是已知飞得最快的鸟。"}, {"id": "low-funny-b2-001", "band": "low", "answer": "a", "prompt": "什么动物走到哪里都背着自己的房子？", "choices": [{"id": "a", "text": "蜗牛"}, {"id": "b", "text": "小狗"}, {"id": "c", "text": "大象"}], "subject": "funny", "difficulty": "quick", "explanation": "蜗牛背上的壳就是它随身的小房子，搬家也不用打包啦。"}, {"id": "low-funny-b2-002", "band": "low", "answer": "c", "prompt": "什么东西早上戴在头上，晚上才摘下来，自己却看不见？", "choices": [{"id": "a", "text": "帽子"}, {"id": "b", "text": "耳朵"}, {"id": "c", "text": "自己头上的头发"}], "subject": "funny", "difficulty": "quick", "explanation": "头发天天在头上，可你怎么扭头都看不全，得照镜子才行。"}, {"id": "low-funny-b2-003", "band": "low", "answer": "a", "prompt": "小兔子参加跑步比赛，可它一定要先带上橡皮，为什么？", "choices": [{"id": "a", "text": "哈哈这是脑筋急转弯，其实兔子跑步根本用不着橡皮，它腿快得很"}, {"id": "b", "text": "因为它怕跑错路要擦掉脚印"}, {"id": "c", "text": "因为它跑累了想坐下来吃橡皮"}], "subject": "funny", "difficulty": "quick", "explanation": "一本正经地问，答案却是\"压根用不着\"，反差就好笑啦。"}, {"id": "low-funny-b2-004", "band": "low", "answer": "c", "prompt": "什么东西妈妈做饭时离不开，可它从来不下锅？", "choices": [{"id": "a", "text": "青菜"}, {"id": "b", "text": "盐"}, {"id": "c", "text": "锅铲"}], "subject": "funny", "difficulty": "quick", "explanation": "锅铲一直在炒菜，但它自己可不会被炒进菜里吃掉。"}, {"id": "low-funny-b2-005", "band": "low", "answer": "b", "prompt": "小熊冬眠睡了一整个冬天，醒来第一句话最可能说什么？", "choices": [{"id": "a", "text": "\"今天作业写完了吗？\""}, {"id": "b", "text": "\"我饿了，早饭呢？\""}, {"id": "c", "text": "\"我要去上学。\""}], "subject": "funny", "difficulty": "quick", "explanation": "冬眠那么久，醒来当然最惦记吃的，可爱又好笑。"}, {"id": "low-funny-b2-006", "band": "low", "answer": "c", "prompt": "什么球永远不会往地上掉？", "choices": [{"id": "a", "text": "皮球"}, {"id": "b", "text": "乒乓球"}, {"id": "c", "text": "地球"}], "subject": "funny", "difficulty": "quick", "explanation": "我们都站在地球上，它托着大家，自己可不会往下掉。"}, {"id": "low-funny-b2-007", "band": "low", "answer": "a", "prompt": "一只小鸡过马路，走到一半为什么停下来了？", "choices": [{"id": "a", "text": "因为它看见红灯，乖乖站着等绿灯"}, {"id": "b", "text": "因为它想在马路上下个蛋"}, {"id": "c", "text": "因为它走累了"}], "subject": "funny", "difficulty": "quick", "explanation": "小鸡也懂交通规则，红灯停绿灯行，又乖又好笑。"}, {"id": "low-funny-b2-008", "band": "low", "answer": "c", "prompt": "什么\"糖\"一点都不甜，吃进嘴里还会硌牙、呛得咳嗽？", "choices": [{"id": "a", "text": "水果糖"}, {"id": "b", "text": "棉花糖"}, {"id": "c", "text": "沙糖（其实是\"沙子\"，跟\"砂糖\"听着像）"}], "subject": "funny", "difficulty": "deep", "explanation": "\"砂\"和\"沙\"谐音，吃进沙子当然不甜还硌牙，这是个谐音玩笑。"}, {"id": "low-funny-b2-009", "band": "low", "answer": "a", "prompt": "什么东西你一抬头就能看见，可你永远摸不到它？", "choices": [{"id": "a", "text": "天上的太阳"}, {"id": "b", "text": "天花板"}, {"id": "c", "text": "自己的鼻子"}], "subject": "funny", "difficulty": "quick", "explanation": "太阳又高又远，抬头就看见，可手再长也够不着。"}, {"id": "low-funny-b2-010", "band": "low", "answer": "b", "prompt": "小猪刚洗完澡，为什么很快又变脏了？", "choices": [{"id": "a", "text": "因为它没用肥皂"}, {"id": "b", "text": "因为它喜欢在泥坑里打滚"}, {"id": "c", "text": "因为它的毛巾是脏的"}], "subject": "funny", "difficulty": "quick", "explanation": "小猪最爱泥坑，刚洗干净就扑进去，逗得人哈哈笑。"}, {"id": "low-funny-b2-011", "band": "low", "answer": "c", "prompt": "什么数字，把它倒过来反而变大了？", "choices": [{"id": "a", "text": "数字3"}, {"id": "b", "text": "数字1"}, {"id": "c", "text": "数字6，倒过来变成9，9比6大"}], "subject": "funny", "difficulty": "deep", "explanation": "数字6倒过来看就是9，9比6大，这是个数字小把戏。"}, {"id": "low-funny-b2-012", "band": "low", "answer": "b", "prompt": "小鸭子最不喜欢哪一种天气？", "choices": [{"id": "a", "text": "刮风天"}, {"id": "b", "text": "出大太阳，因为水坑都被晒干了，没地方玩水"}, {"id": "c", "text": "下雨天"}], "subject": "funny", "difficulty": "quick", "explanation": "鸭子爱玩水，大晴天把水坑晒干了，它才发愁呢。"}, {"id": "low-funny-b2-013", "band": "low", "answer": "b", "prompt": "什么东西越用越短，可你从来不会嫌它短？", "choices": [{"id": "a", "text": "绳子"}, {"id": "b", "text": "铅笔"}, {"id": "c", "text": "尺子"}], "subject": "funny", "difficulty": "quick", "explanation": "铅笔越写越短是正常的，写完了再换一支就好啦。"}, {"id": "low-funny-b2-014", "band": "low", "answer": "c", "prompt": "小猫钓鱼总是钓不到，最可能是因为什么？", "choices": [{"id": "a", "text": "鱼塘里没有鱼"}, {"id": "b", "text": "它的鱼竿太长了"}, {"id": "c", "text": "它一会儿捉蝴蝶一会儿捉蜻蜓，三心二意"}], "subject": "funny", "difficulty": "quick", "explanation": "经典小猫钓鱼故事，三心二意当然钓不到。"}, {"id": "low-funny-b2-015", "band": "low", "answer": "c", "prompt": "什么东西白天看不见，晚上一开灯它就出现，还跟着你动？", "choices": [{"id": "a", "text": "月亮"}, {"id": "b", "text": "星星"}, {"id": "c", "text": "你自己的影子"}], "subject": "funny", "difficulty": "quick", "explanation": "晚上开了灯，光照到你身上就投出影子来啦。"}, {"id": "low-funny-b2-016", "band": "low", "answer": "a", "prompt": "大公鸡为什么每天早上都要\"喔喔\"叫？", "choices": [{"id": "a", "text": "它在喊大家起床：天亮啦"}, {"id": "b", "text": "它在唱歌跳舞"}, {"id": "c", "text": "它在数自己有几根羽毛"}], "subject": "funny", "difficulty": "quick", "explanation": "公鸡打鸣是叫大家天亮起床，尽职的小闹钟。"}, {"id": "low-funny-b2-017", "band": "low", "answer": "b", "prompt": "什么东西，肚子越饿它叫得越响，吃饱了它就乖乖不出声了？", "choices": [{"id": "a", "text": "你的嘴巴"}, {"id": "b", "text": "你的肚子"}, {"id": "c", "text": "你的耳朵"}], "subject": "funny", "difficulty": "quick", "explanation": "饿的时候肚子咕咕直叫，吃饱了就安静了，真实又好笑。"}, {"id": "low-funny-b2-018", "band": "low", "answer": "c", "prompt": "大象的鼻子那么长，它喝水的时候用鼻子干什么？", "choices": [{"id": "a", "text": "用鼻子打个结"}, {"id": "b", "text": "用鼻子当雨伞"}, {"id": "c", "text": "用鼻子像吸管一样把水吸起来，再喷进嘴里"}], "subject": "funny", "difficulty": "quick", "explanation": "大象真的用长鼻子吸水送进嘴里，又实用又有趣。"}, {"id": "low-funny-b2-019", "band": "low", "answer": "b", "prompt": "什么东西闭上它反而看得更清楚？", "choices": [{"id": "a", "text": "嘴巴"}, {"id": "b", "text": "眼睛——闭上眼睛想象的时候，脑海里的画面可清楚啦"}, {"id": "c", "text": "窗帘"}], "subject": "funny", "difficulty": "deep", "explanation": "闭上眼睛，脑海里想的东西反而格外清楚，巧妙的转弯。"}, {"id": "low-funny-b2-020", "band": "low", "answer": "a", "prompt": "小狗为什么总是把骨头埋到土里？", "choices": [{"id": "a", "text": "它把骨头藏起来，留着以后再吃"}, {"id": "b", "text": "它在给骨头种出一棵骨头树"}, {"id": "c", "text": "它觉得骨头脏了要洗一洗"}], "subject": "funny", "difficulty": "quick", "explanation": "小狗喜欢藏好吃的留到以后，可不是种树哦。"}, {"id": "low-funny-b2-021", "band": "low", "answer": "c", "prompt": "什么东西你越用力拍它，它跳得越高？", "choices": [{"id": "a", "text": "小鸟"}, {"id": "b", "text": "枕头"}, {"id": "c", "text": "皮球"}], "subject": "funny", "difficulty": "quick", "explanation": "皮球拍得越用力弹得越高，玩起来真带劲。"}, {"id": "low-funny-b2-022", "band": "low", "answer": "a", "prompt": "什么\"帽子\"剥下来戴在脸前，会把人辣得直流眼泪？", "choices": [{"id": "a", "text": "洋葱皮（剥洋葱会辣得流眼泪）"}, {"id": "b", "text": "棉帽子"}, {"id": "c", "text": "草帽"}], "subject": "funny", "difficulty": "deep", "explanation": "剥洋葱辣眼睛会流泪，把洋葱皮想成帽子就成了好笑的谜底。"}, {"id": "low-funny-b2-023", "band": "low", "answer": "a", "prompt": "小鱼在水里游了一整天，为什么一点都不渴？", "choices": [{"id": "a", "text": "因为它一直泡在水里，身边全是水"}, {"id": "b", "text": "因为它带了水壶"}, {"id": "c", "text": "因为它喝了很多饮料"}], "subject": "funny", "difficulty": "quick", "explanation": "鱼整天在水里，周围都是水，当然不会渴啦。"}, {"id": "low-funny-b2-024", "band": "low", "answer": "c", "prompt": "什么时候，夜晚最长、白天最短？", "choices": [{"id": "a", "text": "夏天"}, {"id": "b", "text": "春天"}, {"id": "c", "text": "冬天（冬天黑得早天亮得晚，夜晚最长）"}], "subject": "funny", "difficulty": "deep", "explanation": "冬天夜长昼短，夏天昼长夜短，是个小常识转弯。"}, {"id": "low-funny-b2-025", "band": "low", "answer": "c", "prompt": "小猴子剥了香蕉，香蕉皮丢到哪里最好？", "choices": [{"id": "a", "text": "挂在树上当装饰"}, {"id": "b", "text": "随手扔地上"}, {"id": "c", "text": "扔进垃圾桶，免得有人踩到滑倒"}], "subject": "funny", "difficulty": "quick", "explanation": "香蕉皮要扔垃圾桶，既好玩又教孩子讲卫生。"}, {"id": "low-funny-b2-026", "band": "low", "answer": "c", "prompt": "什么东西明明是圆的，可它一年才最圆一次？", "choices": [{"id": "a", "text": "盘子"}, {"id": "b", "text": "皮球"}, {"id": "c", "text": "中秋节的月亮（最圆最亮的那一晚）"}], "subject": "funny", "difficulty": "quick", "explanation": "中秋的月亮又大又圆，一年一回，特别有意思。"}, {"id": "low-funny-b2-027", "band": "low", "answer": "c", "prompt": "小乌龟和小兔子赛跑，慢吞吞的小乌龟为什么赢了？", "choices": [{"id": "a", "text": "因为小兔子迷路了"}, {"id": "b", "text": "因为小乌龟会飞"}, {"id": "c", "text": "因为小兔子半路睡着了，小乌龟一直慢慢爬没停下"}], "subject": "funny", "difficulty": "quick", "explanation": "龟兔赛跑里兔子骄傲睡觉，乌龟坚持到底赢了。"}, {"id": "low-funny-b2-028", "band": "low", "answer": "c", "prompt": "什么东西，天气越热它越要\"流汗\"，一会儿就化成一摊水？", "choices": [{"id": "a", "text": "小狗"}, {"id": "b", "text": "石头"}, {"id": "c", "text": "冰激凌"}], "subject": "funny", "difficulty": "quick", "explanation": "冰激凌一热就化成水，像在\"流汗\"，把它拟人化就好笑啦。"}, {"id": "low-funny-b2-029", "band": "low", "answer": "a", "prompt": "小青蛙为什么\"呱呱\"叫，不\"汪汪\"叫？", "choices": [{"id": "a", "text": "因为\"呱呱\"才是青蛙的叫声，\"汪汪\"是小狗的"}, {"id": "b", "text": "因为它感冒了"}, {"id": "c", "text": "因为它在学小狗说话"}], "subject": "funny", "difficulty": "quick", "explanation": "每种动物有自己的叫声，青蛙呱呱、小狗汪汪，搞混就好笑。"}, {"id": "low-funny-b2-030", "band": "low", "answer": "c", "prompt": "什么东西，你睡着的时候它在跳，你醒着的时候它也在跳，从不休息？", "choices": [{"id": "a", "text": "你的眼睛"}, {"id": "b", "text": "你的脚"}, {"id": "c", "text": "你的心脏"}], "subject": "funny", "difficulty": "quick", "explanation": "心脏一刻不停地跳，日夜都在勤劳工作。"}, {"id": "low-funny-b2-031", "band": "low", "answer": "b", "prompt": "小蜜蜂一天到晚采蜜，它做出来的蜂蜜自己舍得吃吗？", "choices": [{"id": "a", "text": "不舍得，它一口都不吃"}, {"id": "b", "text": "舍得，它也要吃饱才有力气干活"}, {"id": "c", "text": "它根本不会做蜂蜜"}], "subject": "funny", "difficulty": "quick", "explanation": "小蜜蜂辛苦采蜜，自己当然也要吃点补充能量。"}, {"id": "low-funny-b2-032", "band": "low", "answer": "b", "prompt": "什么东西越擦越亮，越不擦越暗？", "choices": [{"id": "a", "text": "黑板"}, {"id": "b", "text": "镜子和玻璃"}, {"id": "c", "text": "石头"}], "subject": "funny", "difficulty": "quick", "explanation": "镜子和玻璃要常擦才干净发亮，不擦就蒙上一层灰。"}, {"id": "low-funny-b2-033", "band": "low", "answer": "c", "prompt": "小刺猬们抱在一起取暖，为什么要小心一点点？", "choices": [{"id": "a", "text": "因为它们打呼噜太响"}, {"id": "b", "text": "因为它们怕痒"}, {"id": "c", "text": "因为身上的刺会扎到对方，得保持一点点距离"}], "subject": "funny", "difficulty": "quick", "explanation": "刺猬浑身是刺，抱太紧会扎到，得讲究分寸，可爱又好笑。"}, {"id": "low-funny-b2-034", "band": "low", "answer": "b", "prompt": "什么东西，你一笑它也跟着笑，你一哭它也跟着哭，跟你一模一样？", "choices": [{"id": "a", "text": "小狗"}, {"id": "b", "text": "镜子里的你自己"}, {"id": "c", "text": "妈妈"}], "subject": "funny", "difficulty": "quick", "explanation": "镜子会照出你的表情，你笑它笑、你哭它哭，照得一模一样。"}, {"id": "low-funny-b2-035", "band": "low", "answer": "a", "prompt": "小狗、小猫、小鸭排队喝水，按规矩谁能最先喝到？", "choices": [{"id": "a", "text": "排在队伍最前面的那一个先喝"}, {"id": "b", "text": "个子最大的先喝"}, {"id": "c", "text": "谁最渴谁先喝"}], "subject": "funny", "difficulty": "deep", "explanation": "看似比谁渴，其实排队就得排到队头才轮到喝呢。"}, {"id": "high-funny-b2-001", "band": "high", "answer": "b", "prompt": "一个人买了只会说话的鹦鹉，店主拍胸脯保证\"这鸟会重复它听到的每句话\"，可买回家鹦鹉一个字都不说，店主却没骗人，为什么？", "choices": [{"id": "a", "text": "因为鹦鹉生病了"}, {"id": "b", "text": "因为这只鹦鹉是聋的——它确实\"会重复听到的话\"，可它根本听不见，自然没话可学"}, {"id": "c", "text": "因为主人说话太小声"}], "subject": "funny", "difficulty": "deep", "explanation": "店主的话句句属实却暗藏机关：鹦鹉聋了听不见，逻辑反转很妙。"}, {"id": "high-funny-b2-002", "band": "high", "answer": "b", "prompt": "什么东西，你越往里面装东西，它反而越轻、越往上飘？", "choices": [{"id": "a", "text": "口袋"}, {"id": "b", "text": "气球——往里装的是气，越鼓越轻飘飘往上飞"}, {"id": "c", "text": "书包"}], "subject": "funny", "difficulty": "deep", "explanation": "往气球里\"装\"的是空气，越鼓越往上飘，所以越装越轻。"}, {"id": "high-funny-b2-003", "band": "high", "answer": "c", "prompt": "小明的妈妈有四个孩子，分别叫\"一月\"\"二月\"\"三月\"，第四个孩子叫什么？", "choices": [{"id": "a", "text": "五月"}, {"id": "b", "text": "四月"}, {"id": "c", "text": "小明（题目第一句就说了\"小明的妈妈\"，小明正是第四个）"}], "subject": "funny", "difficulty": "deep", "explanation": "顺着一二三月念下去就掉坑了，答案其实藏在题目开头的\"小明\"。"}, {"id": "high-funny-b2-004", "band": "high", "answer": "b", "prompt": "什么东西，全世界的人天天都在用，可谁也没法借给别人？", "choices": [{"id": "a", "text": "太阳"}, {"id": "b", "text": "你的名字——人人都用自己的名字，却没法把它借给别人去当名字"}, {"id": "c", "text": "空气"}], "subject": "funny", "difficulty": "deep", "explanation": "名字人人都有、天天在用，却是专属自己的，借不出去，转得很巧。"}, {"id": "high-funny-b2-005", "band": "high", "answer": "b", "prompt": "一位画家画了幅特别逼真的玉米挂在田里，第二天乌鸦果然不敢靠近，他正得意，凑近一看却哭笑不得，为什么？", "choices": [{"id": "a", "text": "乌鸦把玉米都偷吃光了"}, {"id": "b", "text": "画框被乌鸦叼走了，只剩光秃秃的玉米——原来乌鸦不怕画，只是嫌画太丑，看上了那个框"}, {"id": "c", "text": "那天乌鸦根本不饿"}], "subject": "funny", "difficulty": "deep", "explanation": "经典\"画太逼真\"被反转成\"乌鸦只看上画框\"，自夸被狠狠拆台，好笑。"}, {"id": "high-funny-b2-006", "band": "high", "answer": "a", "prompt": "什么样的字，上下颠倒过来看，还是原来那个字？", "choices": [{"id": "a", "text": "\"日\"\"目\"\"口\"这类上下对称的字，倒过来看还是它自己"}, {"id": "b", "text": "\"中\"字"}, {"id": "c", "text": "\"个\"字"}], "subject": "funny", "difficulty": "deep", "explanation": "像\"日\"\"口\"这类对称字，翻来覆去都不变样，考的是观察力。"}, {"id": "high-funny-b2-007", "band": "high", "answer": "a", "prompt": "一个人对你说\"我说的每一句话都是假话\"，这句话本身到底是真是假？", "choices": [{"id": "a", "text": "这是个绕死人的逻辑圈套：当真就成了一句真话、自相矛盾，当假又说不通，根本没有简单答案"}, {"id": "b", "text": "肯定是假话"}, {"id": "c", "text": "肯定是真话"}], "subject": "funny", "difficulty": "deep", "explanation": "这是著名的\"说谎者悖论\"，无论当真当假都打架，正是它好玩的地方。"}, {"id": "high-funny-b2-008", "band": "high", "answer": "c", "prompt": "什么东西，天气越热它越往上跑，越冷它越往下缩，还从来不喊累？", "choices": [{"id": "a", "text": "电梯"}, {"id": "b", "text": "烟囱里的烟"}, {"id": "c", "text": "温度计里那截红色的液柱"}], "subject": "funny", "difficulty": "deep", "explanation": "温度计的液柱受热上升、遇冷下降，刚好对上\"热升冷降\"，巧妙。"}, {"id": "high-funny-b2-009", "band": "high", "answer": "c", "prompt": "考试只剩五分钟，监考老师说\"还有时间的同学请抓紧\"，全班瞬间紧张安静，这句话的好笑之处在哪？", "choices": [{"id": "a", "text": "因为大家都早写完了"}, {"id": "b", "text": "因为老师说错了话"}, {"id": "c", "text": "因为五分钟谁都觉得不够、谁都不敢说自己\"还有时间\"，结果这句客气话听着像在催每一个人，又紧张又好笑"}], "subject": "funny", "difficulty": "deep", "explanation": "\"还有时间的请抓紧\"听着客气，其实没人敢认领，反差产生喜感。"}, {"id": "high-funny-b2-010", "band": "high", "answer": "a", "prompt": "什么东西，从中间一切两半，每一半看上去还是一个完整的圆圈？", "choices": [{"id": "a", "text": "数字\"8\"——横着一切，上下各得一个完整的\"0\"圈"}, {"id": "b", "text": "苹果"}, {"id": "c", "text": "鸡蛋"}], "subject": "funny", "difficulty": "deep", "explanation": "数字8拦腰一切，上下各得一个完整的0圈，玩的是字形拆解。"}, {"id": "high-funny-b2-011", "band": "high", "answer": "a", "prompt": "推销员说\"我这把伞结实到下辈子都用不坏\"，顾客一听反而不买了，被绕进了哪个文字坑？", "choices": [{"id": "a", "text": "\"用不坏\"听着像得等到\"下辈子\"，顾客顺着想：这辈子根本碰不上几次下雨，伞放着也是放着，干脆不买了"}, {"id": "b", "text": "嫌伞太贵"}, {"id": "c", "text": "顾客已经有伞了"}], "subject": "funny", "difficulty": "deep", "explanation": "\"下辈子\"和\"用不坏\"被绕成一个时间词的玩笑，顾客被自己想岔了。"}, {"id": "high-funny-b2-012", "band": "high", "answer": "c", "prompt": "什么东西，它跑得比谁都快，可你一回头看它，它马上就停在你身后不动了？", "choices": [{"id": "a", "text": "风"}, {"id": "b", "text": "声音"}, {"id": "c", "text": "你的影子"}], "subject": "funny", "difficulty": "quick", "explanation": "影子总跟着你跑，你一回头它就乖乖停在身后，像在跟你玩。"}, {"id": "high-funny-b2-013", "band": "high", "answer": "a", "prompt": "什么东西，你在一个数后面不停地\"喂\"给它零，它就越变越大？", "choices": [{"id": "a", "text": "数字——后面不停添0，10、100、1000，越添越大"}, {"id": "b", "text": "存钱罐"}, {"id": "c", "text": "气球"}], "subject": "funny", "difficulty": "deep", "explanation": "数字后面添一个0就翻十倍，\"喂零\"越喂越大，是个数字小机灵。"}, {"id": "high-funny-b2-014", "band": "high", "answer": "b", "prompt": "一个人面朝正北站着，原地向左转、再向左转、再向左转，现在他面朝哪个方向？", "choices": [{"id": "a", "text": "正北"}, {"id": "b", "text": "正东（从北→西→南→东，连转三个九十度）"}, {"id": "c", "text": "正南"}], "subject": "funny", "difficulty": "deep", "explanation": "每次左转90度，三次共转270度，从北一路转到正东，考方向感。"}, {"id": "high-funny-b2-015", "band": "high", "answer": "a", "prompt": "什么东西，越想得开的人越乐意把它\"放下\"，越钻牛角尖的人却越攥得紧？", "choices": [{"id": "a", "text": "心里的烦恼——想得开就放下、轻装上阵，钻牛角尖就越攥越紧、越背越沉"}, {"id": "b", "text": "书包"}, {"id": "c", "text": "旧课本"}], "subject": "funny", "difficulty": "deep", "explanation": "把烦恼比作能放下也能攥紧的东西，越想得开越轻松，有点小哲理又好玩。"}, {"id": "high-funny-b2-016", "band": "high", "answer": "b", "prompt": "一只蚂蚁掉进一个\"倒满了的杯子\"，它却慢悠悠爬了出来，一点没被淹着，这怎么可能？", "choices": [{"id": "a", "text": "因为蚂蚁很会憋气"}, {"id": "b", "text": "因为题目只说\"倒满\"，没说倒的是水——这杯子里满满装的是空气，谁规定杯里非得是水呢"}, {"id": "c", "text": "因为蚂蚁会游泳"}], "subject": "funny", "difficulty": "deep", "explanation": "\"倒满一杯\"被默认成水才掉坑，跳出来想\"满杯空气\"就通了，破思维定式。"}, {"id": "high-funny-b2-017", "band": "high", "answer": "b", "prompt": "什么话，凑近耳朵小声说别人最爱听，可一旦写在纸上、念出声来就不灵了？", "choices": [{"id": "a", "text": "广播通知"}, {"id": "b", "text": "悄悄话"}, {"id": "c", "text": "绕口令"}], "subject": "funny", "difficulty": "deep", "explanation": "悄悄话靠\"凑近耳朵小声说\"才有意思，写下来念出来就没了那份私密味儿。"}, {"id": "high-funny-b2-018", "band": "high", "answer": "a", "prompt": "两位棋手坐下来下了一整盘棋，结束时两人都说自己赢了，而且谁也没撒谎，怎么回事？", "choices": [{"id": "a", "text": "因为他俩各自在跟\"别的对手\"下棋——根本没在跟对方下，所以各赢各的"}, {"id": "b", "text": "因为最后是平局"}, {"id": "c", "text": "因为棋盘坏了"}], "subject": "funny", "difficulty": "deep", "explanation": "\"两人都赢\"听着矛盾，揭晓\"他们不是互为对手\"就化解了，逻辑陷阱。"}, {"id": "high-funny-b2-019", "band": "high", "answer": "b", "prompt": "什么东西，你拥有它的时候几乎从不留意，一旦失去才天天想念，可它其实一直围在你身边？", "choices": [{"id": "a", "text": "新玩具"}, {"id": "b", "text": "空气——平时根本不会留意，憋一口气难受了才知道它多宝贵，可它一直围着你"}, {"id": "c", "text": "零花钱"}], "subject": "funny", "difficulty": "deep", "explanation": "空气太平常以致被忽略，缺了才珍惜，立意干净又有点小感悟。"}, {"id": "high-funny-b2-020", "band": "high", "answer": "b", "prompt": "什么东西，往左拧声音就停，往右拧声音就响，可它自己一步都没挪窝？", "choices": [{"id": "a", "text": "汽车方向盘"}, {"id": "b", "text": "音量旋钮——一拧声音忽大忽小，喇叭本体却原地没动"}, {"id": "c", "text": "自行车的车把"}], "subject": "funny", "difficulty": "deep", "explanation": "音量旋钮一拧，声音\"跑\"得忽大忽小，旋钮和喇叭却没挪窝，巧。"}, {"id": "high-funny-b2-021", "band": "high", "answer": "b", "prompt": "小李号称\"过目不忘\"，老师写串数字让他背，他看一眼就一字不差背出来，老师却说他记性差，为什么？", "choices": [{"id": "a", "text": "因为他偷看了答案"}, {"id": "b", "text": "因为他背完数字、转头就忘了老师刚布置的作业——记得住数字，记不住正事"}, {"id": "c", "text": "因为那串数字太短"}], "subject": "funny", "difficulty": "deep", "explanation": "\"过目不忘\"只用在炫技上，正经事转头就忘，自夸被现实打脸，好笑。"}, {"id": "high-funny-b2-022", "band": "high", "answer": "b", "prompt": "什么样的脑筋急转弯问题，无论你回答\"是\"还是\"不是\"，听起来都不大对劲？", "choices": [{"id": "a", "text": "\"今天星期几？\"这种"}, {"id": "b", "text": "\"你现在睡着了吗？\"这种——你只要能开口回答，就说明你醒着，答\"睡着了\"自相矛盾"}, {"id": "c", "text": "\"二加二等于几？\"这种有标准答案的"}], "subject": "funny", "difficulty": "deep", "explanation": "\"你睡着了吗\"只要你能答就说明没睡，这类自指问题怎么答都别扭，很妙。"}, {"id": "high-funny-b2-023", "band": "high", "answer": "a", "prompt": "老师让用一个词形容今天那场超难的考试，哪个学生的回答最可能让全班会心一笑？", "choices": [{"id": "a", "text": "\"难忘\"——嘴上说\"难以忘怀\"，心里其实是被\"难\"得刻骨铭心"}, {"id": "b", "text": "\"普通\""}, {"id": "c", "text": "\"顺利\""}], "subject": "funny", "difficulty": "deep", "explanation": "\"难忘\"一词双关：表面难以忘记，实则被难住到忘不掉，机灵又干净。"}, {"id": "high-funny-b2-024", "band": "high", "answer": "a", "prompt": "什么\"位置\"，全班同学都盯着想要，可它每次只容得下一个人坐？", "choices": [{"id": "a", "text": "\"第一名\"这个位置——人人都想争，可它每回只属于一个人"}, {"id": "b", "text": "窗边座位"}, {"id": "c", "text": "教室门口"}], "subject": "funny", "difficulty": "deep", "explanation": "把\"第一名\"当成一个位置，人人争却独此一份，转得有意思。"}, {"id": "high-funny-b2-025", "band": "high", "answer": "b", "prompt": "魔术师拍胸脯说\"我能让硬币穿过桌子\"，话音刚落硬币真的到了桌子底下，台下却没人鼓掌，为什么？", "choices": [{"id": "a", "text": "因为太精彩观众都看呆了"}, {"id": "b", "text": "因为硬币是他手一抖\"掉\"到桌下去的——它确实\"到了桌底\"，可根本不是穿过去的，是滚下去的"}, {"id": "c", "text": "因为大家都没看清"}], "subject": "funny", "difficulty": "deep", "explanation": "\"穿过桌子\"被偷换成\"掉到桌下\"，魔术翻车，文字游戏制造反差笑点。"}, {"id": "high-funny-b2-026", "band": "high", "answer": "b", "prompt": "什么东西，你越使劲对着它使劲对焦想看清，它越花；你一放松看远处，它反倒不烦你了？", "choices": [{"id": "a", "text": "远处的高山"}, {"id": "b", "text": "飘在眼前的小飞蚊或睫毛——你越盯着看越花，眼睛一放松看远处它就不碍事了"}, {"id": "c", "text": "镜子上的雾气"}], "subject": "funny", "difficulty": "deep", "explanation": "眼睛对太近的东西越使劲越看不清，放松反而舒服，贴近生活又巧妙。"}, {"id": "high-funny-b2-027", "band": "high", "answer": "c", "prompt": "你站在镜子前举起右手，镜子里那个\"你\"举起来的，看上去像哪只手？", "choices": [{"id": "a", "text": "两只手都举"}, {"id": "b", "text": "右手"}, {"id": "c", "text": "看上去像左手——镜子左右相反，你举右手，镜中那个人举起的正对着你像他的左手"}], "subject": "funny", "difficulty": "deep", "explanation": "镜像左右颠倒，你举右手镜中看着像对方的左手，考的是镜面原理。"}, {"id": "high-funny-b2-028", "band": "high", "answer": "b", "prompt": "什么东西，越安静的地方它越显得吵，越热闹的地方它反而听不见？", "choices": [{"id": "a", "text": "风声"}, {"id": "b", "text": "自己肚子咕咕叫的声音——安静的考场里格外响亮尴尬，热闹处却被盖住了"}, {"id": "c", "text": "闹钟"}], "subject": "funny", "difficulty": "deep", "explanation": "肚子叫在静悄悄的考场里特别响，吵闹处却没人听见，又真实又好笑。"}, {"id": "high-funny-b2-029", "band": "high", "answer": "a", "prompt": "小张把同一句话连说了三遍，每遍意思都不一样，大家不但不嫌他啰嗦，反而夸他聪明，他用了什么小窍门？", "choices": [{"id": "a", "text": "因为他每遍把重音落在不同的字上——同一句话换个地方加重，意思就变了，一句顶三句"}, {"id": "b", "text": "因为他说得特别快"}, {"id": "c", "text": "因为他说话特别大声"}], "subject": "funny", "difficulty": "deep", "explanation": "同一句话靠改变重音能表达不同含义，是语言里很妙的现象，干净有料。"}, {"id": "high-funny-b2-030", "band": "high", "answer": "a", "prompt": "什么东西，你越乐意分给别人，它在你这儿反而越值钱；你越死死藏着，它越不值钱？", "choices": [{"id": "a", "text": "知识和本事——你越乐意分享教别人，它越显出价值；死死捂着不传，慢慢就没人识货了"}, {"id": "b", "text": "钱"}, {"id": "c", "text": "邮票"}], "subject": "funny", "difficulty": "deep", "explanation": "知识越分享越有价值、越藏越贬值，立意正面又有反差趣味。"}, {"id": "high-funny-b2-031", "band": "high", "answer": "c", "prompt": "一只猫头鹰白天总闭着眼打瞌睡，主人担心它病了带去看医生，医生却说\"它健康得很\"，为什么？", "choices": [{"id": "a", "text": "因为它在装睡偷懒"}, {"id": "b", "text": "因为它眼睛坏了"}, {"id": "c", "text": "因为猫头鹰本来就昼伏夜出——白天睡觉、晚上精神，这是它的天性，不是病"}], "subject": "funny", "difficulty": "deep", "explanation": "猫头鹰是夜行动物，白天打盹是正常作息，误会被科学解释化解。"}, {"id": "high-funny-b2-032", "band": "high", "answer": "c", "prompt": "什么东西，你拉得越满它弹得越远，可你松手不碰它，它一辈子也老老实实不动？", "choices": [{"id": "a", "text": "风筝线"}, {"id": "b", "text": "门铃"}, {"id": "c", "text": "弹弓上的皮筋"}], "subject": "funny", "difficulty": "deep", "explanation": "皮筋拉得越满弹得越远，不碰它就纹丝不动，把弹力藏进了谜语里。"}, {"id": "high-funny-b2-033", "band": "high", "answer": "a", "prompt": "老师在黑板上写\"明天不上课\"，全班欢呼，可第二天大家照样得来上课，老师哪句话其实没说错？", "choices": [{"id": "a", "text": "因为\"明天\"永远在前方——今天的明天就是新的今天，那句话写在哪天都成立，可\"今天\"总要上课"}, {"id": "b", "text": "因为大家看错了"}, {"id": "c", "text": "因为老师写错了字"}], "subject": "funny", "difficulty": "deep", "explanation": "\"明天\"是个永远往后挪的词，落到实处总是\"今天上课\"，玩的是时间词的逻辑。"}, {"id": "high-funny-b2-034", "band": "high", "answer": "c", "prompt": "什么东西，长着一张\"嘴\"却从不吃饭，肚里装满了水一倒就往外\"吐\"，吐空了反而轻松？", "choices": [{"id": "a", "text": "垃圾桶"}, {"id": "b", "text": "钱包"}, {"id": "c", "text": "茶壶——有壶嘴却不吃饭，灌满了一倒就从嘴里往外\"吐\"水，倒空就轻了"}], "subject": "funny", "difficulty": "deep", "explanation": "茶壶\"有嘴不吃饭、装满往外倒\"，把日常物件拟人化得又形象又好笑。"}]$seed$::jsonb, now()) on conflict (game) do update set data = excluded.data, updated_at = now();
