": "全商场靠对讲机调度:答应指令叫\"收到\",到处转着检查叫\"巡场\""}, {"tag": "商场日常", "kind": "trivia", "role": "mom", "text": "商场\"盘点\"是干什么？为什么导购最怕它?", "emoji": "📦", "answer": "闭店后清点库存,常数到深夜,盘亏了可能要赔"}, {"tag": "商场日常", "kind": "trivia", "role": "mom", "text": "商场开门营业前,员工要先开什么会？会上干什么?", "emoji": "📣", "answer": "晨会(早会):点名、报昨天业绩、定今天目标、喊口号、检查仪容"}, {"tag": "商场日常", "kind": "trivia", "role": "mom", "text": "穿工服的员工在商场里不能走哪些地方？", "emoji": "🚪", "answer": "不能走顾客通道、不能坐客梯,只能走员工通道和货梯"}, {"tag": "商场日常", "kind": "trivia", "role": "mom", "text": "专柜和商场之间的结算方式叫什么？", "emoji": "🧮", "answer": "联营扣点——商场从专柜流水里抽百分比"}, {"tag": "商场日常", "kind": "trivia", "role": "mom", "text": "商场里那种摆在过道中间的展示区叫什么？", "emoji": "🏝️", "answer": "中岛——黄金陈列位,新品和折扣品都放这"}, {"tag": "商场日常", "kind": "trivia", "role": "mom", "text": "商场\"防损部\"是干什么的？", "emoji": "🛡️", "answer": "防盗、盘点损耗、查内盗"}, {"tag": "商场日常", "kind": "trivia", "role": "mom", "text": "商场停车场\"消费满额免停车费\"是什么套路？", "emoji": "🅿️", "answer": "逼你为了停车费凑单消费"}, {"tag": "商场日常", "kind": "trivia", "role": "mom", "text": "导购最烦顾客的什么行为？", "emoji": "🙄", "answer": "试穿一小时不买、拍照转头网上下单、临打烊进店"}, {"tag": "商场日常", "kind": "trivia", "role": "mom", "text": "导购的\"职业病\"有哪些？", "emoji": "😬", "answer": "站一整天腿酸/静脉曲张、条件反射式\"欢迎光临\"、营业假笑"}, {"tag": "带娃日常", "kind": "trivia", "role": "mom", "text": "家长群常年显示什么数字？", "emoji": "💬", "answer": "消息 999+"}, {"tag": "带娃日常", "kind": "trivia", "role": "mom", "text": "班级群里的\"接龙\"是什么？", "emoji": "🐉", "answer": "按格式排队报名/确认收到的微信玩法"}, {"tag": "带娃日常", "kind": "trivia", "role": "mom", "text": "每天要帮孩子打卡的项目有哪些？", "emoji": "✅", "answer": "跳绳打卡、阅读打卡、口算打卡——还要拍视频上传"}, {"tag": "带娃日常", "kind": "trivia", "role": "mom", "text": "辅导作业的\"全国统一症状\"是什么？", "emoji": "🩺", "answer": "血压飙升——\"不写作业母慈子孝,一写作业鸡飞狗跳\""}, {"tag": "带娃日常", "kind": "trivia", "role": "mom", "text": "\"鸡娃\"是什么意思？", "emoji": "🐔", "answer": "给孩子打鸡血式密集培养(对应的是\"佛系\"\"躺平\")"}, {"tag": "带娃日常", "kind": "trivia", "role": "mom", "text": "除了打卡,妈妈还要被迫完成的\"三大手工任务\"是什么？", "emoji": "🎨", "answer": "手抄报、亲子手工、运动会服装——最后都是妈妈做"}, {"tag": "带娃日常", "kind": "trivia", "role": "mom", "text": "\"家委会\"是干什么的？", "emoji": "🏛️", "answer": "组织活动、收班费、在老师和家长间传话"}, {"tag": "带娃日常", "kind": "trivia", "role": "mom", "text": "班级群常用的打卡小程序叫什么？", "emoji": "📲", "answer": "班级小管家、接龙管家、班小二"}, {"tag": "带娃日常", "kind": "trivia", "role": "mom", "text": "妈妈圈说的\"牛娃\"和\"普娃\"是什么意思？", "emoji": "🐮", "answer": "牛娃=别人家的超强孩子,普娃=普通孩子"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我遇到过最离谱/最好笑的顾客是什么样的？", "emoji": "🤦‍♀️"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我下班回家最想做的第一件事是什么？", "emoji": "🛁"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我最近在追的短剧或综艺是什么？", "emoji": "📺"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我在直播间最忍不住下单的是哪类东西？", "emoji": "🛒"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我是 i 人还是 e 人？", "emoji": "🎭"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我没结婚之前最喜欢做什么？", "emoji": "🌸"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我学生时代有没有\"追\"过哪个明星？追到什么程度?", "emoji": "💫"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我现在最想收到的礼物是什么？", "emoji": "🎁"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "如果我能休一个超长假期,我最想去哪里？", "emoji": "🏝️"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "商场里我最喜欢逛、但总舍不得买的是哪家店？", "emoji": "👜"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我在 KTV 必点的一首歌是什么？", "emoji": "🎶"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "当年是爸爸追的我,还是我\"看上\"的爸爸？过程是怎样的?", "emoji": "💘"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "我觉得结婚以后爸爸最大的变化是什么？", "emoji": "🔄"}, {"tag": "走心", "kind": "personal", "role": "mom", "text": "如果能回到 18 岁,我最想做的一件事是什么？", "emoji": "🕰️"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋的真名(本名)是什么？", "emoji": "🎤", "answer": "邓诗颖。\"邓紫棋\"是艺名"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "G.E.M. 这三个字母是什么意思？", "emoji": "💃", "answer": "Get Everybody Moving——让每个人动起来"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋的歌迷叫什么名字？", "emoji": "♟️", "answer": "棋士(早期叫\"渔民\")"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "《光年之外》是哪部好莱坞电影的中文主题曲？", "emoji": "🌌", "answer": "《太空旅客》"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋出生在哪个城市？几岁搬去香港？", "emoji": "🏙️", "answer": "上海出生,4 岁搬到香港"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋 2014 年参加哪个节目在内地爆红？拿了第几名？", "emoji": "🏆", "answer": "《我是歌手》第二季,亚军(冠军是韩磊)"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋几岁就在红馆开演唱会,创下最年轻女歌手纪录？", "emoji": "🎫", "answer": "19 岁"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋的英文名叫什么？她的世界巡演也用了这个名字", "emoji": "✨", "answer": "Gloria,巡演叫 I AM GLORIA"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋写的第一部长篇小说叫什么？", "emoji": "📖", "answer": "《启示路》,基于专辑《启示录》的世界观"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋为什么要重新录制自己的老歌发\"重录版\"专辑？", "emoji": "⚖️", "answer": "和前公司有版权纠纷,老歌版权不在自己手里,重录版才是\"自己的歌\""}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋离开前公司后写的第一首歌是哪首？歌名就是一种标点符号", "emoji": "⭕", "answer": "《句号》"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋几岁被经纪人发掘签约？为什么 16 岁才出道？", "emoji": "🌱", "answer": "14 岁歌唱比赛夺冠被签下,因为要先完成学业"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋的 I AM GLORIA 巡演有多猛？", "emoji": "🌍", "answer": "票房超过麦当娜巡演,是全球女歌手史上票房第四高,亚洲女歌手单主题巡演场次纪录(149+ 场)"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋 2022 年的专辑《启示录》发行方式有什么特别？", "emoji": "📺", "answer": "像\"音乐连续剧\"一样每周连载两首歌+MV,共 14 首"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋跑完 150 多场巡演后,才从妈妈那里得知自己有什么遗传问题?", "emoji": "🩸", "answer": "地中海贫血"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "《泡沫》《倒数》《来自天堂的魔鬼》《多远都要在一起》——哪首不是邓紫棋写给自己唱的原创?", "emoji": "🫧", "answer": "都是她的原创代表作,这是道送分陷阱题"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋哪一年正式出道？首张 EP 叫什么名字？", "emoji": "🚀", "answer": "2008 年,16 岁出道,首张 EP 就叫《G.E.M.》"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋的生日是哪天？什么星座？", "emoji": "🦁", "answer": "1991 年 8 月 16 日,狮子座"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋在《我是歌手》第一期唱了哪首歌一战成名？", "emoji": "🍷", "answer": "《你把我灌醉》,一开口全场起立"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "她在《我是歌手》翻唱汪峰的哪首歌成了\"炸场名场面\"？", "emoji": "🔊", "answer": "《存在》,高音直接把观众唱懵"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "《喜欢你》的原唱是哪个乐队？", "emoji": "🎸", "answer": "Beyond——邓紫棋翻唱后火遍全网,很多人以为是她的原创"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "《泡沫》的灵感是怎么来的？", "emoji": "🛁", "answer": "她说是看着泡泡有感而发:\"阳光下的泡沫,是彩色的\""}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋早期被全网调侃的标志性穿搭是什么？", "emoji": "👖", "answer": "皮裤——\"邓紫棋的皮裤\"一度是热搜常客"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "2016 年邓紫棋登上哪个国际榜单,成为当年唯一入选的华语音乐人？", "emoji": "📰", "answer": "福布斯\"30 Under 30\"(30 岁以下最具影响力人物)"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋的纪录片电影叫什么名字？", "emoji": "🎬", "answer": "《一路逆风》,讲她出道以来的起伏"}, {"tag": "邓紫棋", "kind": "trivia", "role": "bigSis", "text": "邓紫棋写歌主要靠什么乐器？", "emoji": "🎹", "answer": "钢琴——自弹自唱是她的看家本领,演唱会必有钢琴环节"}, {"tag": "热梗", "kind": "trivia", "role": "bigSis", "text": "\"从从容容、游刃有余\"的下半句是什么？", "emoji": "🏃", "answer": "\"匆匆忙忙、连滚带爬\"——2025 年度第一接梗题"}, {"tag": "热梗", "kind": "trivia", "role": "bigSis", "text": "\"浪浪山小妖怪\"用来形容哪种人？", "emoji": "⛰️", "answer": "平凡的小人物/打工人,\"我就是浪浪山的小妖怪\""}, {"tag": "热梗", "kind": "trivia", "role": "bigSis", "text": "\"助我破鼎\"出自哪部电影？什么时候用？", "emoji": "🔥", "answer": "《哪吒之魔童闹海》,给自己打气时用,比如考试前"}, {"tag": "热梗", "kind": "trivia", "role": "bigSis", "text": "\"邪修\"是什么意思？比如\"邪修背单词\"", "emoji": "🧙", "answer": "不走寻常路但意外有效的野路子(出自修仙小说)"}, {"tag": "热梗", "kind": "trivia", "role": "bigSis", "text": "\"高雅人士\"这个梗的画面是什么？什么时候用?", "emoji": "🐧", "answer": "一只魔性跳舞的胖企鹅,\"高雅人士视察中\"——快崩溃了还要强装体面"}, {"tag": "热梗", "kind": "trivia", "role": "bigSis", "text": "\"来财~来~来财\"出自哪首歌？怎么用？", "emoji": "🧧", "answer": "揽佬的《八方来财》,考试前可以喊\